module fsm (
    input CLK,
    input RST,
    input IN,
    output reg MATCH
);

    reg [2:0] state, next_state;

    parameter IDLE = 0,
              S1 = 1,
              S2 = 2,
              S3 = 3,
              S4 = 4,
              S5 = 5;

    always @(posedge CLK or posedge RST) begin
        if (RST) begin
            state <= IDLE;
            MATCH <= 0;
        end else begin
            state <= next_state;

            case (state)
                S4: MATCH <= (IN == 1);
                default: MATCH <= 0;
            endcase
        end
    end

    always @(*) begin
        case (state)
            IDLE: next_state = (IN) ? S1 : IDLE;
            S1: next_state = (IN) ? S1 : S2;
            S2: next_state = (IN) ? IDLE : S3;
            S3: next_state = (IN) ? S4 : IDLE;
            S4: next_state = (IN) ? S5 : IDLE;
            S5: next_state = (IN) ? S1 : IDLE;
            default: next_state = IDLE;
        endcase
    end

endmodule

