module sequence_detector (
    input clk,
    input reset_n,
    input data_in,
    output reg sequence_detected
);


    parameter IDLE = 3'b000,
              S1   = 3'b001,
              S2   = 3'b010,
              S3   = 3'b011,
              S4   = 3'b100;

    reg [2:0] current_state, next_state;


    always @(posedge clk or negedge reset_n) begin
        if (!reset_n) begin
            current_state <= IDLE;
        end else begin
            current_state <= next_state;
        end
    end


    always @(*) begin
        case (current_state)
            IDLE: begin
                if (data_in)
                    next_state = S1;
                else
                    next_state = IDLE;
            end
            S1: begin
                if (!data_in)
                    next_state = S2;
                else
                    next_state = S1;
            end
            S2: begin
                if (!data_in)
                    next_state = S3;
                else
                    next_state = S1;
            end
            S3: begin
                if (data_in)
                    next_state = S4;
                else
                    next_state = IDLE;
            end
            S4: begin
                next_state = S1;

            end
            default: next_state = IDLE;
        endcase
    end


    always @(*) begin
        sequence_detected = (current_state == S4);
    end

endmodule

