module asyn_fifo #(
    parameter WIDTH = 8,
    parameter DEPTH = 16
) (
    input wclk,
    input wrstn,
    input winc,
    input [WIDTH-1:0] wdata,
    output wfull,
    input rclk,
    input rrstn,
    input rinc,
    output rempty,
    output [WIDTH-1:0] rdata
);

localparam ADDR_WIDTH = $clog2(DEPTH);
localparam PTR_WIDTH = ADDR_WIDTH + 1;


dual_port_RAM #(
    .DEPTH(DEPTH),
    .WIDTH(WIDTH)
) ram (
    .wclk(wclk),
    .wenc(winc && !wfull),
    .waddr(waddr_bin[ADDR_WIDTH-1:0]),
    .wdata(wdata),
    .rclk(rclk),
    .renc(rinc && !rempty),
    .raddr(raddr_bin[ADDR_WIDTH-1:0]),
    .rdata(rdata)
);


reg [PTR_WIDTH-1:0] waddr_bin;

always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) begin
        waddr_bin <= 0;
    end else if (winc && !wfull) begin
        waddr_bin <= waddr_bin + 1;
    end
end


reg [PTR_WIDTH-1:0] wptr_gray;

always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) begin
        wptr_gray <= 0;
    end else begin
        wptr_gray <= (waddr_bin >> 1) ^ waddr_bin;
    end
end


reg [PTR_WIDTH-1:0] raddr_bin;

always @(posedge rclk or negedge rrstn) begin
    if (!rrstn) begin
        raddr_bin <= 0;
    end else if (rinc && !rempty) begin
        raddr_bin <= raddr_bin + 1;
    end
end


reg [PTR_WIDTH-1:0] rptr_gray;

always @(posedge rclk or negedge rrstn) begin
    if (!rrstn) begin
        rptr_gray <= 0;
    end else begin
        rptr_gray <= (raddr_bin >> 1) ^ raddr_bin;
    end
end


reg [PTR_WIDTH-1:0] rptr_gray_sync1, rptr_gray_sync2;

always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) begin
        rptr_gray_sync1 <= 0;
        rptr_gray_sync2 <= 0;
    end else begin
        rptr_gray_sync1 <= rptr_gray;
        rptr_gray_sync2 <= rptr_gray_sync1;
    end
