                                     ~rptr_gray_sync2[PTR_WIDTH-2], 
                                     rptr_gray_sync2[PTR_WIDTH-3:0]});


reg [PTR_WIDTH-1:0] wptr_gray_sync1, wptr_gray_sync2;

always @(posedge rclk or negedge rrstn) begin
    if (!rrstn) begin
        wptr_gray_sync1 <= 0;
        wptr_gray_sync2 <= 0;
    end else begin
        wptr_gray_sync1 <= wptr_gray;
        wptr_gray_sync2 <= wptr_gray_sync1;
    end
end


wire empty_condition = (rptr_gray == wptr_gray_sync2);

assign wfull = full_condition;
assign rempty = empty_condition;

