module pulse_detect (
    input clk,
    input rst_n,
    input data_in,
    output data_out
);

reg [1:0] current_state, next_state;

localparam IDLE = 2'b00;
localparam RISE = 2'b01;
localparam PULSE = 2'b10;


always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        current_state <= IDLE;
    end else begin
        current_state <= next_state;
    end
end


always @(*) begin
    case (current_state)
        IDLE:   next_state = data_in ? RISE : IDLE;
        RISE:   next_state = data_in ? IDLE : PULSE;
        PULSE:  next_state = IDLE;
        default: next_state = IDLE;
    endcase
end


assign data_out = (current_state == PULSE) ? 1'b1 : 1'b0;

endmodule

