module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

reg [7:0] abs_dividend;
reg [7:0] abs_divisor;
reg dividend_sign;
reg divisor_sign;
reg [15:0] SR;
reg [3:0] cnt;
reg [7:0] NEG_DIVISOR;
reg processing;

always @(posedge clk) begin
    if (rst) begin
        res_valid <= 0;
        SR <= 0;
        cnt <= 0;
        processing <= 0;
        result <= 0;
        dividend_sign <= 0;
        divisor_sign <= 0;
        abs_dividend <= 0;
        abs_divisor <= 0;
        NEG_DIVISOR <= 0;
    end else begin
        if (res_valid) begin
            res_valid <= 0;
            processing <= 0;
        end else if (opn_valid && !processing) begin

            if (sign) begin
                dividend_sign <= dividend[7];
                divisor_sign <= divisor[7];
                abs_dividend <= (dividend[7]) ? -dividend : dividend;
                abs_divisor <= (divisor[7]) ? -divisor : divisor;
            end else begin
                dividend_sign <= 0;
                divisor_sign <= 0;
                abs_dividend <= dividend;
                abs_divisor <= divisor;
            end


            SR <= {abs_dividend, 8'b0} << 1;


            NEG_DIVISOR <= -abs_divisor;

            cnt <= 0;
            processing <= 1;
            res_valid <= 0;
        end else if (processing) begin
            if (cnt < 8) begin

                SR <= SR << 1;


                reg [8:0] temp = SR[15:8] - NEG_DIVISOR;


                if (!temp[8]) begin 
                    SR[15:8] <= temp[7:0];
                    SR[0] <= 1'b1;

                end else begin 
                    SR[0] <= 1'b0;
                end

                cnt <= cnt + 1;
            end else begin

                processing <= 0;
                res_valid <= 1;


                if (sign) begin

                    if (dividend_sign ^ divisor_sign)
                        SR[7:0] <= -SR[7:0];

                    if (dividend_sign)
                        SR[15:8] <= -SR[15:8];
                end
                result <= SR;
            end
        end
    end
end

endmodule

