module div_16bit (
    input [15:0] A,
    input [7:0] B,
    output reg [15:0] result,
    output reg [15:0] odd
);

    reg [15:0] a_reg;
    reg [7:0] b_reg;


    always @(*) begin
        a_reg = A;
        b_reg = B;
    end


    always @(*) begin
        integer i;
        reg [7:0] rem;
        reg [15:0] quo;

        rem = 8'b0;
        quo = 16'b0;

        for (i = 15;
 i >= 0;
 i = i - 1) begin
            rem = {rem[6:0], a_reg[i]};
            if (rem >= b_reg) begin
                rem = rem - b_reg;
                quo = {quo[14:0], 1'b1};
            end else begin
                quo = {quo[14:0], 1'b0};
            end
        end

        result = quo;
        odd = {8'b0, rem};

    end

endmodule

