module fixed_point_adder #(
    parameter Q = 8, 
    parameter N = 16 
) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output reg [N-1:0] c
);

    reg [N-1:0] res;
    wire sign_a = a[N-1];
    wire sign_b = b[N-1];


    wire [N-1:0] abs_a = sign_a ? (~a + 1) : a;
    wire [N-1:0] abs_b = sign_b ? (~b + 1) : b;


    always @(*) begin
        if (sign_a == sign_b) begin

            res = abs_a + abs_b;
        end else begin

            if (abs_a > abs_b) begin
                res = (~abs_a + 1) + abs_b;
            end else if (abs_b > abs_a) begin
                res = (~abs_b + 1) + abs_a;
            end else begin

                res = {N{1'b0}};
            end
        end

    end


    assign c = res;

endmodule

