module fixed_point_subtractor #(
    parameter Q = 2,
    parameter N = 4
) (
    input [N-1:0] a,
    input [N-1:0] b,
    output reg [N-1:0] c
);

    reg sign_a, sign_b;
    reg [N-1:0] res;
    reg [N-1:0] abs_a, abs_b;
    reg [N-1:0] res_mag;
    reg res_sign;

    always @(*) begin
        sign_a = a[N-1];
        sign_b = b[N-1];

        if (sign_a == sign_b) begin
            res = a - b;
        end else begin
            abs_a = sign_a ? (~a + 1) : a;
            abs_b = sign_b ? (~b + 1) : b;

            if (abs_a > abs_b) begin
                res_mag = abs_a - abs_b;
                res_sign = sign_a;
            end else if (abs_b > abs_a) begin
                res_mag = abs_b - abs_a;
                res_sign = sign_b;
            end else begin
                res_mag = 0;
                res_sign = 0;
            end

            res = res_sign ? (~res_mag + 1) : res_mag;
        end

        if (res == 0) begin
            res[N-1] = 0;
        end

        c = res;
    end

endmodule

