module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);

    reg [2:0] counter = 0;
    reg a_sign, b_sign, z_sign;
    reg [7:0] a_exponent, b_exponent, z_exponent;
    reg [22:0] a_mantissa, b_mantissa;
    reg [23:0] a_mantissa_full, b_mantissa_full;
    reg [47:0] product;
    reg guard, round, sticky;
    reg [22:0] z_mantissa;
    reg overflow, underflow;

    always @(posedge clk) begin
        if (rst) begin
            counter <= 0;
            z <= 0;
            a_sign <= 0;
            b_sign <= 0;
            z_sign <= 0;
            a_exponent <= 0;
            b_exponent <= 0;
            z_exponent <= 0;
            a_mantissa <= 0;
            b_mantissa <= 0;
            a_mantissa_full <= 0;
            b_mantissa_full <= 0;
            product <= 0;
            guard <= 0;
            round <= 0;
            sticky <= 0;
            z_mantissa <= 0;
            overflow <= 0;
            underflow <= 0;
        end else begin
            case (counter)
                0: begin

                    a_sign <= a[31];
                    b_sign <= b[31];
                    z_sign <= a[31] ^ b[31];
                    a_exponent <= a[30:23];
                    b_exponent <= b[30:23];
                    a_mantissa <= a[22:0];
                    b_mantissa <= b[22:0];
                    a_mantissa_full <= {1'b1, a[22:0]};
                    b_mantissa_full <= {1'b1, b[22:0]};
                    product <= a_mantissa_full * b_mantissa_full;


                    if (a_exponent == 8'hFF || b_exponent == 8'hFF) begin
                        if (a_exponent == 8'hFF && b_exponent == 8'hFF) begin

                            z <= {z_sign, 8'hFF, 22'h0};
                        end else if (a_exponent == 8'hFF) begin

                            if (|a_mantissa) begin

                                z <= {z_sign, 8'hFF, 22'h1};
                            end else begin
                                z <= {z_sign, 8'hFF, 22'h0};
                            end
                        end else begin

                            if (|b_mantissa) begin

                                z <= {z_sign, 8'hFF, 22'h1};
                            end else begin
                                z <= {z_sign, 8'hFF, 22'h0};
                            end
                        end
                        counter <= 1;
                    end else if (a_exponent == 0) begin
                        if (|a_mantissa) begin

                            z <= {z_sign, 8'hFF, 22'h1};
                        end else begin

                            z <= {z_sign, 31'h0};
                        end
                        counter <= 1;
                    end else if (b_exponent == 0) begin
                        if (|b_mantissa) begin

                            z <= {z_sign, 8'hFF, 22'h1};
                        end else begin

                            z <= {z_sign, 31'h0};
                        end
                        counter <= 1;
                    end else begin

                        z_exponent <= a_exponent + b_exponent - 8'd127;
                        counter <= 1;
                    end
                end

                1: begin

                    if (product[47:46] == 2'b10 || product[47:46] == 2'b11) begin
                        product <= product >> 1;
                        z_exponent <= z_exponent + 1;
                    end
                    counter <= 2;
                end

                2: begin

                    guard <= product[22];
                    round <= product[21];
                    sticky <= |product[20:0];


                    if (product[47]) begin

                        z_mantissa <= product[46:24];
                    end else begin

                        z_mantissa <= product[45:23];
                    end


                    if (guard) begin
                        if (round || sticky) begin
                            if (z_mantissa[0]) begin
                                z_mantissa <= z_mantissa + 1;
                            end
                        end
                    end


                    if (z_mantissa == 23'h7FFFFF && guard && round && sticky) begin
                        z_exponent <= z_exponent + 1;
                    end

                    counter <= 3;
                end

                3: begin

                    if (z_exponent >= 8'hFF) begin
                        z <= {z_sign, 8'hFF, 22'h0};
                    end else if (z_exponent == 0) begin
                        z <= {z_sign, 31'h0};
                    end else begin
                        z <= {z_sign, z_exponent, z_mantissa};
                    end
                    counter <= 0;
                end

                default: counter <= 0;
            endcase
        end
    end

