module asyn_fifo #(
    parameter WIDTH = 8,
    parameter DEPTH = 16
) (
    input wclk,
    input wrstn,
    input rclk,
    input rrstn,
    input winc,
    input rinc,
    input [WIDTH-1:0] wdata,
    output wfull,
    output rempty,
    output [WIDTH-1:0] rdata
);

localparam ADDR_WIDTH = $clog2(DEPTH);


reg [ADDR_WIDTH:0] wptr_bin, rptr_bin;
reg [ADDR_WIDTH:0] wptr_gray, rptr_gray;


reg [ADDR_WIDTH:0] wptr_gray_sync0, wptr_gray_sync1;
reg [ADDR_WIDTH:0] rptr_gray_sync0, rptr_gray_sync1;


function [ADDR_WIDTH:0] bin2gray;
    input [ADDR_WIDTH:0] bin;
    bin2gray = bin ^ (bin >> 1);
endfunction


function [ADDR_WIDTH:0] gray2bin;
    input [ADDR_WIDTH:0] gray;
    reg [ADDR_WIDTH:0] bin;
    integer i;
    begin
        bin[ADDR_WIDTH] = gray[ADDR_WIDTH];
        for (i = ADDR_WIDTH-1;
 i >= 0;
 i = i-1)
            bin[i] = bin[i+1] ^ gray[i];
        gray2bin = bin;
    end
endfunction


always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) begin
        wptr_bin <= 0;
        wptr_gray <= 0;
    end else begin
        if (winc && !wfull) begin
            wptr_bin <= wptr_bin + 1;
        end
        wptr_gray <= bin2gray(wptr_bin);
    end
end


always @(posedge rclk or negedge rrstn) begin
    if (!rrstn) begin
        rptr_bin <= 0;
        rptr_gray <= 0;
    end else begin
        if (rinc && !rempty) begin
            rptr_bin <= rptr_bin + 1;
        end
        rptr_gray <= bin2gray(rptr_bin);
    end
end


always @(posedge wclk) begin
    rptr_gray_sync0 <= rptr_gray;
    rptr_gray_sync1 <= rptr_gray_sync0;
end

always @(posedge rclk) begin
    wptr_gray_sync0 <= wptr_gray;
    wptr_gray_sync1 <= wptr_gray_sync0;
end


wire [ADDR_WIDTH:0] wptr_bin_sync = gray2bin(wptr_gray_sync1);
wire [ADDR_WIDTH:0] rptr_bin_sync = gray2bin(rptr_gray_sync1);

assign wfull = (wptr_bin - rptr_bin_sync) == DEPTH;
assign rempty = (rptr_bin == wptr_bin_sync);


dual_port_RAM #(
    .WIDTH(WIDTH),
    .DEPTH(DEPTH)
) ram (
    .wclk(wclk),
    .wenc(winc && !wfull),
    .waddr(wptr_bin[ADDR_WIDTH-1:0]),
    .wdata(wdata),
    .rclk(rclk),
    .renc(rinc && !rempty),
    .raddr(rptr_bin[ADDR_WIDTH-1:0]),
