module pulse_detect (
    input clk,
    input rst_n,
    input data_in,
    output data_out
);


    localparam IDLE = 2'b00;
    localparam S1 = 2'b01;
    localparam S2 = 2'b10;

    reg [1:0] state;


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
        end else begin
            case (state)
                IDLE: state <= (data_in) ? IDLE : S1;
                S1: state <= (data_in) ? S2 : S1;
                S2: state <= (data_in) ? IDLE : IDLE;
                default: state <= IDLE;
            endcase
        end
    end


    assign data_out = (state == S2) && (data_in == 0);

endmodule

