        valid_lock <= 1'b0;
        data_pipeline <= 16'b0;
        valid_pipeline <= 1'b0;
        valid_out <= 1'b0;
        data_out <= 16'b0;
    end else begin
        valid_pipeline <= 1'b0;

        if (valid_in) begin
            if (valid_lock) begin
                data_pipeline <= {data_lock, data_in};
                valid_pipeline <= 1'b1;
                valid_lock <= 1'b0;
            end else begin
                data_lock <= data_in;
                valid_lock <= 1'b1;
            end
        end

        valid_out <= valid_pipeline;
        data_out <= data_pipeline;
    end
end

