module serial2parallel (
    input clk,
    input rst_n,
    input din_serial,
    input din_valid,
    output reg [7:0] dout_parallel,
    output reg dout_valid
);

reg [3:0] cnt;

reg [7:0] data_reg;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        cnt <= 4'b0;
        data_reg <= 8'b0;
        dout_valid <= 1'b0;
    end else begin
        dout_valid <= 1'b0;

        if (din_valid) begin
            if (cnt == 4'd7) begin

                data_reg[0] <= din_serial;
                dout_valid <= 1'b1;
                cnt <= 4'b0;
            end else begin

                case (cnt)
                    4'd0: data_reg[7] <= din_serial;
                    4'd1: data_reg[6] <= din_serial;
                    4'd2: data_reg[5] <= din_serial;
                    4'd3: data_reg[4] <= din_serial;
                    4'd4: data_reg[3] <= din_serial;
                    4'd5: data_reg[2] <= din_serial;
                    4'd6: data_reg[1] <= din_serial;
                    default: data_reg <= data_reg;
                endcase
                cnt <= cnt + 1;
            end
        end
    end
end

assign dout_parallel = data_reg;

