            next_wave = wave + 1;
            if (next_wave == 31) begin
                next_state = 1;
            end else begin
                next_state = state;
            end
        end
        1: begin
            next_wave = wave - 1;
            if (next_wave == 0) begin
                next_state = 0;
            end else begin
                next_state = state;
