module alu(
    input [31:0] a,
    input [31:0] b,
    input [5:0] aluc,
    output reg [31:0] r,
    output zero,
    output reg carry,
    output negative,
    output reg overflow,
    output reg flag
);


    parameter ADD  = 6'b100000;
    parameter ADDU = 6'b100001;
    parameter SUB  = 6'b100010;
    parameter SUBU = 6'b100011;
    parameter AND  = 6'b100100;
    parameter OR   = 6'b100101;
    parameter XOR  = 6'b100110;
    parameter NOR  = 6'b100111;
    parameter SLT  = 6'b101010;
    parameter SLTU = 6'b101011;
    parameter SLL  = 6'b000000;
    parameter SRL  = 6'b000010;
    parameter SRA  = 6'b000011;
    parameter SLLV = 6'b000100;
    parameter SRLV = 6'b000110;
    parameter SRAV = 6'b000111;
    parameter LUI  = 6'b001111;


    reg [32:0] add_result, sub_result, addu_result, subu_result;
    reg [31:0] shift_result;


    assign zero = (r == 32'd0);
    assign negative = r[31];

    always @(*) begin
        case (aluc)
            ADD: begin
                add_result = {1'b0, a} + {1'b0, b};
                r = add_result[31:0];
                carry = add_result[32];
                overflow = (a[31] == b[31]) && (r[31] != a[31]);
                flag = 1'bz;
            end
            ADDU: begin
                addu_result = {1'b0, a} + {1'b0, b};
                r = addu_result[31:0];
                carry = addu_result[32];
                overflow = 1'b0;
                flag = 1'bz;
            end
            SUB: begin
                sub_result = {1'b0, a} - {1'b0, b};
                r = sub_result[31:0];
                carry = sub_result[32];
                overflow = (a[31] != b[31]) && (r[31] != a[31]);
                flag = 1'bz;
            end
            SUBU: begin
                subu_result = {1'b0, a} - {1'b0, b};
                r = subu_result[31:0];
                carry = subu_result[32];
                overflow = 1'b0;
                flag = 1'bz;
            end
            AND: begin
                r = a & b;
                carry = 1'b0;
                overflow = 1'b0;
                flag = 1'bz;
            end
            OR: begin
                r = a | b;
                carry = 1'b0;
                overflow = 1'b0;
                flag = 1'bz;
            end
            XOR: begin
                r = a ^ b;
                carry = 1'b0;
                overflow = 1'b0;
                flag = 1'bz;
            end
            NOR: begin
                r = ~(a | b);
                carry = 1'b0;
                overflow = 1'b0;
                flag = 1'bz;
            end
            SLT: begin
                r = ($signed(a) < $signed(b)) ? 32'd1 : 32'd0;
                flag = ($signed(a) < $signed(b)) ? 1'b1 : 1'bz;
                carry = 1'b0;
                overflow = 1'b0;
            end
            SLTU: begin
                r = (a < b) ? 32'd1 : 32'd0;
                flag = (a < b) ? 1'b1 : 1'bz;
                carry = 1'b0;
                overflow = 1'b0;
            end
            SLL: begin
                shift_result = b << a[4:0];
                r = shift_result;
                carry = 1'b0;
                overflow = 1'b0;
                flag = 1'bz;
            end
            SRL: begin
                shift_result = b >> a[4:0];
                r = shift_result;
                carry = 1'b0;
                overflow = 1'b0;
                flag = 1'bz;
            end
            SRA: begin
                shift_result = $signed(b) >>> a[4:0];
                r = shift_result;
                carry = 1'b0;
                overflow = 1'b0;
                flag = 1'bz;
            end
            SLLV: begin
                shift_result = b << b[4:0];
                r = shift_result;
                carry = 1'b0;
                overflow = 1'b0;
                flag = 1'bz;
            end
            SRLV: begin
                shift_result = b >> b[4:0];
                r = shift_result;
                carry = 1'b0;
                overflow = 1'b0;
                flag = 1'bz;
            end
            SRAV: begin
                shift_result = $signed(b) >>> b[4:0];
                r = shift_result;
                carry = 1'b0;
                overflow = 1'b0;
                flag = 1'bz;
            end
            LUI: begin
                r = {a[15:0], 16'b0};
                carry = 1'b0;
                overflow = 1'b0;
                flag = 1'bz;
            end
            default: begin
                r = 32'bz;
                carry = 1'b0;
                overflow = 1'b0;
                flag = 1'bz;
            end
        endcase
    end

endmodule

