module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

reg [7:0] abs_dividend;
reg [7:0] abs_divisor;
reg dividend_sign;
reg divisor_sign;
reg [15:0] SR;
reg [3:0] cnt;
reg start_cnt;

always @(posedge clk) begin
    if (rst) begin
        res_valid <= 0;
        cnt <= 0;
        start_cnt <= 0;
        result <= 0;
        dividend_sign <= 0;
        divisor_sign <= 0;
        abs_dividend <= 0;
        abs_divisor <= 0;
        SR <= 0;
    end else begin
        if (opn_valid && !res_valid) begin
            res_valid <= 0;
            dividend_sign <= sign ? dividend[7] : 0;
            divisor_sign <= sign ? divisor[7] : 0;
            abs_dividend <= sign ? (dividend[7] ? -dividend : dividend) : dividend;
            abs_divisor <= sign ? (divisor[7] ? -divisor : divisor) : divisor;
            SR <= {abs_dividend, 8'b0} << 1;
            NEG_DIVISOR <= -abs_divisor;
            cnt <= 1;
            start_cnt <= 1;
        end else if (start_cnt) begin
            if (cnt == 8) begin
                start_cnt <= 0;
                cnt <= 0;
                if (sign) begin
                    result[15:8] <= (dividend_sign) ? -SR[7:0] : SR[7:0];
                    result[7:0] <= (dividend_sign ^ divisor_sign) ? -SR[15:8] : SR[15:8];
                end else begin
                    result[15:8] <= SR[7:0];
                    result[7:0] <= SR[15:8];
                end
                res_valid <= 1;
            end else begin
                wire [8:0] sub = {1'b0, SR[15:8]} - {1'b0, NEG_DIVISOR};
                wire carry = sub[8];
                reg [7:0] new_remainder;
                reg [7:0] new_quotient;
                if (carry) begin
                    new_remainder = SR[15:8];
                    new_quotient = {SR[6:0], 1'b0};
                end else begin
                    new_remainder = sub[7:0];
                    new_quotient = {SR[6:0], 1'b1};
                end
                SR <= {new_remainder, new_quotient};
                cnt <= cnt + 1;
            end
        end
    end
end

endmodule

