module fixed_point_adder #(
    parameter Q = 8,
    parameter N = 16
) (
    input [N-1:0] a,
    input [N-1:0] b,
    output reg [N-1:0] c
);

reg signed [N-1:0] a_signed, b_signed;
reg signed [N:0] sum_signed;

always @(*) begin
    a_signed = $signed(a);
    b_signed = $signed(b);
    sum_signed = a_signed + b_signed;

    if (a_signed >= 0 && b_signed >= 0) begin
        if (sum_signed > (2**(N-1)-1)) begin
            c = {1'b0, {(N-1){1'b1}}};
        end else begin
            c = sum_signed;
        end
    end else if (a_signed < 0 && b_signed < 0) begin
        if (sum_signed < (-2**(N-1))) begin
            c = {1'b1, {(N-1){1'b0}}};
        end else begin
            c = sum_signed;
        end
    end else begin

        reg signed [N-1:0] a_abs, b_abs;
        a_abs = (a_signed < 0) ? -a_signed : a_signed;
        b_abs = (b_signed < 0) ? -b_signed : b_signed;

        if (a_abs > b_abs) begin
            c = a_signed - b_signed;
        end else if (b_abs > a_abs) begin
            c = b_signed - a_signed;
        end else begin
            c = 0;
        end
    end
end

endmodule

