    reg a_sign, b_sign, z_sign;
    reg [7:0] a_exp, b_exp;
    reg [22:0] a_mant, b_mant;
    reg [23:0] product;
    reg [47:0] product_full;
    reg [7:0] z_exp;
    reg guard, round, sticky;
    reg [22:0] rounded_mantissa;

    always @(posedge clk) begin
        if (rst) begin
            counter <= 0;
            z <= 0;
            a_sign <= 0;
            b_sign <= 0;
            a_exp <= 0;
            b_exp <= 0;
            a_mant <= 0;
            b_mant <= 0;
            product <= 0;
            product_full <= 0;
            z_exp <= 0;
            guard <= 0;
            round <= 0;
            sticky <= 0;
            rounded_mantissa <= 0;
        end else begin
            case (counter)
                0: begin
                    a_sign <= a[31];
                    b_sign <= b[31];
                    a_exp <= a[30:23];
                    b_exp <= b[30:23];
                    a_mant <= (a[30:23] != 0) ? {1'b1, a[22:0]} : {1'b0, a[22:0]};
                    b_mant <= (b[30:23] != 0) ? {1'b1, b[22:0]} : {1'b0, b[22:0]};
                    counter <= 1;
                end
                1: begin

                    if ((a_exp == 8'hff || a_exp == 0) || (b_exp == 8'hff || b_exp == 0)) begin
                        z <= {a_sign ^ b_sign, 8'hff, 23'h0};
                        counter <= 3;
                    end else begin
                        product_full <= a_mant * b_mant;
                        counter <= 2;
                    end
                end
                2: begin
                    product <= product_full[47:24];
                    z_exp <= a_exp + b_exp - 8'h7f;
                    counter <= 3;
                end
                3: begin

                    if (product >= 24'h800000) begin
                        product <= product >> 1;
                        z_exp <= z_exp + 1;
                    end

                    guard <= product[22];
                    round <= product[21];
                    sticky <= |product[20:0];
                    rounded_mantissa <= product[22:0] + (guard & round & sticky);
                    counter <= 4;
                end
                4: begin

                    if (rounded_mantissa[23]) begin
                        z <= {a_sign ^ b_sign, z_exp + 1, rounded_mantissa[22:1]};
                    end else begin
                        z <= {a_sign ^ b_sign, z_exp, rounded_mantissa[22:0]};
                    end
                    counter <= 0;
                end
                default: counter <= 0;
            endcase
        end
    end

