module asyn_fifo #(
    parameter DEPTH = 16,
    parameter WIDTH = 8
) (
    input wclk,
    input wrstn,
    input winc,
    input [WIDTH-1:0] wdata,
    output wfull,
    output rempty,
    output [WIDTH-1:0] rdata,

    input rclk,
    input rrstn,
    input rinc
);

localparam ADDR_BITS = $clog2(DEPTH);
localparam PTR_BITS = ADDR_BITS + 1;


wire [ADDR_BITS-1:0] waddr = wptr_bin[ADDR_BITS-1:0];
wire [ADDR_BITS-1:0] raddr = rptr_bin[ADDR_BITS-1:0];
dual_port_RAM #(
    .DEPTH(DEPTH),
    .WIDTH(WIDTH)
) ram (
    .wclk(wclk),
    .wenc(winc && !wfull),
    .waddr(waddr),
    .wdata(wdata),
    .rclk(rclk),
    .renc(rinc && !rempty),
    .raddr(raddr),
    .rdata(rdata)
);


reg [PTR_BITS-1:0] wptr_bin, wptr_gray;
always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) begin
        wptr_bin <= 0;
    end else begin
        if (winc && !wfull) begin
            wptr_bin <= wptr_bin + 1;
        end
    end
end


always @* begin
    wptr_gray = wptr_bin ^ (wptr_bin >> 1);
end


reg [PTR_BITS-1:0] rptr_gray_sync1, rptr_gray_sync2;
always @(posedge wclk) begin
    rptr_gray_sync1 <= rptr_gray;
    rptr_gray_sync2 <= rptr_gray_sync1;
end


reg [PTR_BITS-1:0] rptr_bin, rptr_gray;
always @(posedge rclk or negedge rrstn) begin
    if (!rrstn) begin
        rptr_bin <= 0;
    end else begin
        if (rinc && !rempty) begin
            rptr_bin <= rptr_bin + 1;
        end
    end
end


always @* begin
    rptr_gray = rptr_bin ^ (rptr_bin >> 1);
end


reg [PTR_BITS-1:0] wptr_gray_sync1, wptr_gray_sync2;
always @(posedge rclk) begin
    wptr_gray_sync1 <= wptr_gray;
    wptr_gray_sync2 <= wptr_gray_sync1;
end


assign rempty = (rptr_gray == rptr_gray_sync2);

assign wfull = (wptr_gray[PTR_BITS-1] != rptr_gray_sync2[PTR_BITS-1]) &&
               (wptr_gray[PTR_BITS-2] != rptr_gray_sync2[PTR_BITS-2]) &&
               (wptr_gray[PTR_BITS-3:0] == rptr_gray_sync2[PTR_BITS-3:0]);

