module traffic_light (
    input rst_n,
    input clk,
    input pass_request,
    output reg [7:0] clock,
    output reg red,
    output reg yellow,
    output reg green
);

    parameter idle = 2'b00;
    parameter s1_red = 2'b01;
    parameter s2_yellow = 2'b10;
    parameter s3_green = 2'b11;

    reg [7:0] cnt;
    reg [1:0] state;
    reg p_red, p_yellow, p_green;


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= idle;
            cnt <= 10;
        end else begin
            case (state)
                idle: state <= s1_red;
                s1_red: begin
                    if (cnt == 0) state <= s3_green;
                    else cnt <= cnt - 1;
                end
                s3_green: begin
                    if (cnt == 0) begin
                        if (pass_request && green) begin
                            if (cnt > 10) cnt <= 10;
                            else cnt <= 60;
                        end else begin
                            cnt <= cnt - 1;
                        end
                        if (pass_request && green && cnt > 10) begin
                            state <= s1_red;
                        end else if (cnt == 0) begin
                            state <= s2_yellow;
                        end
                    end else begin
                        cnt <= cnt - 1;
                    end
                end
                s2_yellow: begin
                    if (cnt == 0) state <= s1_red;
                    else cnt <= cnt - 1;
                end
                default: state <= idle;
            endcase
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cnt <= 10;
            clock <= 10;
        end else begin
            clock <= cnt;
            if (state == s1_red) begin
                cnt <= 10;
            end else if (state == s3_green) begin
                cnt <= 60;
            end else if (state == s2_yellow) begin
                cnt <= 5;
            end else if (pass_request && green) begin
                if (cnt > 10) cnt <= 10;
            end else begin
                cnt <= cnt - 1;
            end
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            red <= 0;
            yellow <= 0;
            green <= 0;
            p_red <= 0;
            p_yellow <= 0;
            p_green <= 0;
        end else begin
            p_red <= red;
            p_yellow <= yellow;
            p_green <= green;

            case (state)
                s1_red: begin
                    red <= 1;
                    yellow <= 0;
                    green <= 0;
                end
                s2_yellow: begin
                    red <= 0;
                    yellow <= 1;
                    green <= 0;
                end
                s3_green: begin
                    red <= 0;
                    yellow <= 0;
                    green <= 1;
                end
                default: begin
                    red <= 0;
                    yellow <= 0;
                    green <= 0;
                end
            endcase
        end
    end

endmodule

