module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);


reg [15:0] SR;

reg [3:0] cnt;

reg [7:0] abs_dividend, abs_divisor;
reg [7:0] neg_divisor;
reg sign_dividend, sign_divisor;
reg state;
reg [7:0] quotient;

localparam IDLE = 0;
localparam BUSY = 1;

always @(posedge clk) begin
    if (rst) begin
        state <= IDLE;
        res_valid <= 0;
        SR <= 0;
        cnt <= 0;
        sign_dividend <= 0;
        sign_divisor <= 0;
        neg_divisor <= 0;
        result <= 0;
    end else begin
        case (state)
            IDLE: begin
                if (opn_valid && !res_valid) begin

                    sign_dividend <= sign ? dividend[7] : 1'b0;
                    sign_divisor <= sign ? divisor[7] : 1'b0;
                    abs_dividend <= sign ? (dividend[7] ? (~dividend + 1) : dividend) : dividend;
                    abs_divisor <= sign ? (divisor[7] ? (~divisor + 1) : divisor) : divisor;
                    neg_divisor <= ~abs_divisor + 1;


                    SR <= {abs_dividend, 8'b0} << 1;
                    cnt <= 0;
                    state <= BUSY;
                end
            end
            BUSY: begin
                if (cnt < 8) begin

                    {SR, quotient} <= SR << 1;
                    if (SR[15:8] >= abs_divisor) begin
                        SR[15:8] <= SR[15:8] - abs_divisor;
                        SR[0] <= 1'b1;
                    end
                    cnt <= cnt + 1;
                end else begin

                    if (sign) begin

                        quotient <= (sign_dividend ^ sign_divisor) ? (~SR[7:0] + 1) : SR[7:0];
                        SR[15:8] <= (sign_dividend) ? (~SR[15:8] + 1) : SR[15:8];
                    end

                    result <= {SR[15:8], quotient};
                    res_valid <= 1;
                    state <= IDLE;
                end
            end
        endcase
    end
end

endmodule

