        if (!rst_n) begin

            i <= 5'b0;
            areg <= 16'b0;
            breg <= 16'b0;
            yout <= 32'b0;
            done <= 1'b0;
        end else begin

            if (start) begin
                if (i < 5'd17) begin
                    i <= i + 1'b1;
                end
            end else begin
                i <= 5'b0;
            end


            if (i == 5'd16) begin
                done <= 1'b1;
            end else if (i == 5'd17) begin
                done <= 1'b0;
            end


            if (start) begin

                if (i == 5'd0) begin
                    areg <= ain;
                    breg <= bin;
                end

                else if (i >= 5'd1 && i < 5'd17) begin
                    if (areg[i-1]) begin
                        yout <= yout + (breg << (i-1));
                    end
                end
            end else begin

                yout <= 32'b0;
            end
        end
    end

