module accu (
    input clk,
    input rst_n,
    input [7:0] data_in,
    input valid_in,
    output valid_out,
    output [9:0] data_out
);

reg [1:0] count;
reg [9:0] temp_sum;

wire [9:0] sum_with_next = temp_sum + data_in;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        count <= 2'b00;
        temp_sum <= 10'b0;
    end else begin
        if (valid_in) begin
            if (count == 2'b11) begin
                temp_sum <= 0;
                count <= 2'b00;
            end else begin
                temp_sum <= sum_with_next;
                count <= count + 1;
            end
        end
    end
end

assign valid_out = (count == 2'b11) && valid_in;
assign data_out = sum_with_next;

endmodule

