module fixed_point_subtractor #(
    parameter Q = 4,
    parameter N = 8
) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output reg [N-1:0] c
);

    reg [N-1:0] res;

    always @(*) begin
        if (a[N-1] == b[N-1]) begin

            res = a - b;
        end else begin

            if (a[N-1] == 0) begin

                reg [N-1:0] abs_b = (~b + 1);
                reg [N-1:0] sum = a + abs_b;
                res = (a > abs_b) ? sum : (~sum + 1);
            end else begin

                reg [N-1:0] abs_a = (~a + 1);
                reg [N-1:0] sum = abs_a + b;
                res = (abs_a > b) ? ~sum + 1 : sum;
            end
        end


        if (res == 0)
            res = 0;

        c = res;
    end

endmodule

