module LIFObuffer (
    input clk,
    input rst,
    input en,
    input rw,
    input [3:0] dataIn,
    output EMPTY,
    output FULL,
    output [3:0] dataOut
);

    reg [3:0] SP;

    reg [3:0] stack_mem [0:3];



    assign EMPTY = (SP == 4);
    assign FULL = (SP == 0);
    assign dataOut = (EMPTY) ? 0 : stack_mem[SP-1];

    always @(posedge clk) begin
        if (rst) begin

            SP <= 4;
            stack_mem[0] <= 0;
            stack_mem[1] <= 0;
            stack_mem[2] <= 0;
            stack_mem[3] <= 0;
        end
        else if (en) begin
            if (!EMPTY) begin 
                if (rw) begin 
                    stack_mem[SP-1] <= 0;

                    SP <= SP + 1;

                end
                else if (!FULL) begin 
                    stack_mem[SP] <= dataIn;

                    SP <= SP - 1;

                end
            end
        end
    end

endmodule

