module traffic_light (
    input clk,
    input rst_n,
    input pass_request,
    output [7:0] clock,
    output reg red,
    output reg yellow,
    output reg green
);

parameter idle = 2'b00;
parameter s1_red = 2'b01;
parameter s2_yellow = 2'b10;
parameter s3_green = 2'b11;

reg [1:0] state;
reg [7:0] cnt;

assign clock = cnt;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= idle;
        red <= 0;
        yellow <= 0;
        green <= 0;
        cnt <= 10;
    end else begin
        case (state)
            idle: begin
                state <= s3_green;
                green <= 1;
                cnt <= 60;
            end
            s3_green: begin
                if (pass_request && (cnt > 10))
                    cnt <= 10;

                if (cnt == 0) begin
                    state <= s2_yellow;
                    yellow <= 1;
                    cnt <= 5;
                end else
                    cnt <= cnt - 1;

                green <= 1;
            end
            s2_yellow: begin
                if (cnt == 0) begin
                    state <= s1_red;
                    red <= 1;
                    cnt <= 10;
                end else
                    cnt <= cnt - 1;

                yellow <= 1;
            end
            s1_red: begin
                if (cnt == 0) begin
                    state <= s3_green;
                    green <= 1;
                    cnt <= 60;
                end else
                    cnt <= cnt - 1;

                red <= 1;
            end
            default: state <= idle;
        endcase
    end
end

endmodule

