    if (!rst_n) begin
        cnt <= 4'b0;
        shift_reg <= 8'b0;
        dout_valid <= 1'b0;
        dout_parallel <= 8'b0;
    end else begin
        dout_valid <= 1'b0;
        if (din_valid) begin
            shift_reg <= {shift_reg[6:0], din_serial};
            cnt <= cnt + 1;

            if (cnt + 1 == 4'd8) begin
                dout_valid <= 1'b1;
                dout_parallel <= {shift_reg[6:0], din_serial};
                cnt <= 4'b0;
            end
        end
    end
end

