module alu (
    input [31:0] a,
    input [31:0] b,
    input [5:0] aluc,
    output reg [31:0] r,
    output zero,
    output carry,
    output negative,
    output overflow,
    output flag
);

    reg [31:0] res;
    wire [32:0] sum_add;
    wire [32:0] sum_sub;

    parameter ADD = 6'b100000;
    parameter ADDU = 6'b100001;
    parameter SUB = 6'b100010;
    parameter SUBU = 6'b100011;
    parameter AND = 6'b100100;
    parameter OR = 6'b100101;
    parameter XOR = 6'b100110;
    parameter NOR = 6'b100111;
    parameter SLT = 6'b101010;
    parameter SLTU = 6'b101011;
    parameter SLL = 6'b000000;
    parameter SRL = 6'b000010;
    parameter SRA = 6'b000011;
    parameter SLLV = 6'b000100;
    parameter SRLV = 6'b000110;
    parameter SRAV = 6'b000111;
    parameter LUI = 6'b001111;

    always @(*) begin
        case (aluc)
            ADD: begin
                sum_add = {1'b0, a} + {1'b0, b};
                res = sum_add[31:0];
                carry = sum_add[32];
                overflow = (a[31] == b[31]) && (res[31] != a[31]);
            end
            ADDU: begin
                res = a + b;
                carry = sum_add[32];

                overflow = 0;
            end
            SUB: begin
                sum_sub = {1'b0, a} - {1'b0, b};
                res = sum_sub[31:0];
                carry = sum_sub[32];

                overflow = (a[31] != b[31]) && (res[31] != a[31]);
            end
            SUBU: begin
                res = a - b;
                carry = (a < b);

                overflow = 0;
            end
            AND: res = a & b;
            OR: res = a | b;
            XOR: res = a ^ b;
            NOR: res = ~(a | b);
            SLT: res = (a < b) ? 32'd1 : 32'd0;
            SLTU: res = (a < b) ? 32'd1 : 32'd0;

            SLL: res = b << a[4:0];
            SRL: res = b >> a[4:0];
            SRA: res = b >>> a[4:0];
            SLLV: res = a << b[4:0];
            SRLV: res = a >> b[4:0];
            SRAV: res = a >>> b[4:0];
            LUI: res = {a[15:0], 16'b0};

            default: res = 32'bz;
        endcase
    end


    reg flag_reg;
    always @(*) begin
        if (aluc == SLT || aluc == SLTU)
            flag_reg = res[0];
        else
            flag_reg = 1'bz;
    end

    assign r = res;


    assign zero = (r == 32'b0);


    assign negative = r[31];


























    reg carry_reg, overflow_reg;

    always @(*) begin
        case (aluc)
            ADD: begin
                sum_add = {1'b0, a} + {1'b0, b};
                res = sum_add[31:0];
                carry_reg = sum_add[32];
                overflow_reg = (a[31] == b[31]) && (res[31] != a[31]);
            end
            ADDU: begin
                res = a + b;
                carry_reg = ( {1'b0, a} + {1'b0, b} )[32];

                overflow_reg = 0;
            end
            SUB: begin
                sum_sub = {1'b0, a} - {1'b0, b};
                res = sum_sub[31:0];
                carry_reg = sum_sub[32];
                overflow_reg = (a[31] != b[31]) && (res[31] != a[31]);
            end
            SUBU: begin
                res = a - b;
                carry_reg = (a < b);
                overflow_reg = 0;
            end

            AND: begin
                res = a & b;
                carry_reg = 0;
                overflow_reg = 0;
            end
            OR: begin
                res = a | b;
                carry_reg = 0;
                overflow_reg = 0;
            end


            SLL: begin
                res = b << a[4:0];
                carry_reg = 0;
                overflow_reg = 0;
            end
            SRL: begin
                res = b >> a[4:0];
                carry_reg = 0;
                overflow_reg = 0;
            end
            SRA: begin
                res = b >>> a[4:0];
                carry_reg = 0;
                overflow_reg = 0;
            end
            SLLV: begin
                res = a << b[4:0];
                carry_reg = 0;
                overflow_reg = 0;
            end
            SRLV: begin
                res = a >> b[4:0];
                carry_reg = 0;
                overflow_reg = 0;
            end
            SRAV: begin
                res = a >>> b[4:0];
                carry_reg = 0;
                overflow_reg = 0;
            end
            LUI: begin
                res = {a[15:0], 16'b0};
                carry_reg = 0;
                overflow_reg = 0;
            end
            default: begin
                res = 32'bz;
                carry_reg = 0;
                overflow_reg = 0;
            end
        endcase
    end

    assign r = res;
    assign carry = carry_reg;
    assign overflow = overflow_reg;


    assign zero = (r == 32'b0);


    assign negative = r[31];


    assign flag = (aluc == SLT || aluc == SLTU) ? res[0] : 1'bz;

endmodule

