module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

    reg [3:0] cnt;
    reg [8:0] SR;

    reg sign_quotient;
    reg sign_remainder;
    reg [7:0] abs_dividend;
    reg [7:0] abs_divisor;
    reg [7:0] neg_divisor;


    reg [1:0] state;
    localparam IDLE  = 2'b00;
    localparam INIT  = 2'b01;
    localparam PROCESS = 2'b10;
    localparam DONE  = 2'b11;

    always @(posedge clk) begin
        if (rst) begin
            state <= IDLE;
            res_valid <= 0;
            result <= 0;
            cnt <= 0;
            SR <= 0;
            sign_quotient <= 0;
            sign_remainder <= 0;
            abs_dividend <= 0;
            abs_divisor <= 0;
            neg_divisor <= 0;
        end else begin
            case (state)
                IDLE: begin
                    res_valid <= 0;
                    if (opn_valid && !res_valid) begin

                        if (sign) begin
                            sign_quotient <= dividend[7] ^ divisor[7];
                            sign_remainder <= dividend[7];
                            abs_dividend <= dividend[7] ? -dividend : dividend;
                            abs_divisor <= divisor[7] ? -divisor : divisor;
                            neg_divisor <= -abs_divisor;
                        end else begin
                            sign_quotient <= 0;
                            sign_remainder <= 0;
                            abs_dividend <= dividend;
                            abs_divisor <= divisor;
                            neg_divisor <= -divisor;
                        end

                        SR <= {abs_dividend, 1'b0};
                        cnt <= 1;
                        state <= PROCESS;
                    end
                end
                PROCESS: begin
                    if (cnt <= 8) begin

                        if ({1'b0, SR[8:1]} >= {1'b0, neg_divisor}) begin
                            SR <= {SR[8:1] - neg_divisor, SR[0], 1'b1};
                        end else begin
                            SR <= {SR[8:1], SR[0], 1'b0};
                        end
                        cnt <= cnt + 1;
                    end else begin
                        state <= DONE;
                    end
                end
                DONE: begin

                    if (sign) begin

                        if (sign_remainder) begin
                            result[15:8] <= -SR[8:1];
                        end else begin
                            result[15:8] <= SR[8:1];
                        end

                        if (sign_quotient) begin
                            result[7:0] <= -SR[0:7];
                        end else begin
                            result[7:0] <= SR[0:7];
                        end
                    end else begin

                        result[15:8] <= SR[8:1];
                        result[7:0] <= SR[0:7];
                    end
                    res_valid <= 1;
                    state <= IDLE;
                end
                default: state <= IDLE;
            endcase
        end
    end
endmodule

