module accu (
    input clk,
    input rst_n,
    input [7:0] data_in,
    input valid_in,
    output reg valid_out,
    output reg [9:0] data_out
);

reg [7:0] shift_reg [3:0];
reg [1:0] count;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        count <= 0;
        shift_reg[0] <= 0;
        shift_reg[1] <= 0;
        shift_reg[2] <= 0;
        shift_reg[3] <= 0;
        valid_out <= 0;
        data_out <= 0;
    end
    else begin
        valid_out <= 0;

        if (valid_in) begin

            shift_reg[0] <= data_in;
            shift_reg[1] <= shift_reg[0];
            shift_reg[2] <= shift_reg[1];
            shift_reg[3] <= shift_reg[2];


            count <= count + 1;


            if (count == 2'b11) begin

                data_out <= shift_reg[0] + shift_reg[1] + shift_reg[2] + data_in;
                valid_out <= 1;
                count <= 0;
            end
        end
    end
end

endmodule

