module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);

    reg [2:0] counter;
    reg a_sign, b_sign, z_sign;
    reg [7:0] a_exponent, b_exponent, z_exponent;
    reg [22:0] a_mantissa, b_mantissa;
    reg [47:0] product;
    reg [22:0] normalized_mantissa;
    reg guard_bit, round_bit, sticky;

    always @(posedge clk) begin
        if (rst) begin
            counter <= 0;
            z <= 0;
            a_sign <= 0;
            b_sign <= 0;
            a_exponent <= 0;
            b_exponent <= 0;
            a_mantissa <= 0;
            b_mantissa <= 0;
            product <= 0;
            normalized_mantissa <= 0;
            guard_bit <= 0;
            round_bit <= 0;
            sticky <= 0;
        end else begin
            case (counter)
                0: begin

                    a_sign <= a[31];
                    a_exponent <= a[30:23];
                    a_mantissa <= {1'b1, a[22:0]};
                    b_sign <= b[31];
                    b_exponent <= b[30:23];
                    b_mantissa <= {1'b1, b[22:0]};
                    counter <= 1;
                end
                1: begin

                    if ((a_exponent == 8'hFF && a_mantissa != 0) || 
                        (b_exponent == 8'hFF && b_mantissa != 0)) begin

                        z <= {1'b0, 8'hFF, 23'h000001};
                        counter <= 0;
                    end else if ((a_exponent == 8'hFF && b_exponent == 8'hFF) || 
                               (a_mantissa == 0 && b_mantissa == 0)) begin

                        z_sign <= a_sign ^ b_sign;
                        z_exponent <= 8'hFF;
                        z_mantissa <= 23'h0;
                        z <= {z_sign, 8'hFF, z_mantissa};
                        counter <= 0;
                    end else if (a_exponent == 8'hFF || b_exponent == 8'hFF) begin

                        if (a_exponent == 8'hFF) begin
                            z_sign <= a_sign ^ b_sign;
                            z <= {z_sign, 8'hFF, z_mantissa};
                        end else begin
                            z_sign <= a_sign ^ b_sign;
                            z <= {z_sign, 8'hFF, z_mantissa};
                        end
                        counter <= 0;
                    end else if (a_mantissa == 0 || b_mantissa == 0) begin

                        z_sign <= a_sign ^ b_sign;
                        z <= {z_sign, 8'h00, 23'h0};
                        counter <= 0;
                    end else begin

                        product <= a_mantissa * b_mantissa;
                        z_exponent <= a_exponent + b_exponent - 8'd127;
                        counter <= 2;
                    end
                end
                2: begin

                    if (product[47]) begin
                        normalized_mantissa <= product[46:24];
                        z_exponent <= z_exponent + 1;
                        guard_bit <= product[23];
                        round_bit <= product[22];
                        sticky <= |product[21:0];
                    end else begin
                        normalized_mantissa <= product[45:23];
                        guard_bit <= product[23];
                        round_bit <= product[22];
                        sticky <= |product[21:0];
                    end
                    counter <= 3;
                end
                3: begin

                    if (guard_bit && (round_bit || sticky || normalized_mantissa[0])) begin
                        if (normalized_mantissa == 23'h7FFFFF) begin
                            normalized_mantissa <= 0;
                            z_exponent <= z_exponent + 1;
                        end else begin
                            normalized_mantissa <= normalized_mantissa + 1;
                        end
                    end
                    counter <= 4;
                end
                4: begin

                    if (z_exponent >= 8'hFE) begin
                        z <= {z_sign, 8'hFF, 23'h0};
                    end else if (z_exponent == 0) begin

                        z <= {z_sign, 8'h0, normalized_mantissa};
                    end else begin
                        z <= {z_sign, z_exponent, normalized_mantissa};
                    end
                    counter <= 0;
                end
            endcase
        end
    end

endmodule

