module asyn_fifo #(
    parameter WIDTH = 8,
    parameter DEPTH = 16
) (
    input wclk,
    input wrstn,
    input winc,
    input [WIDTH-1:0] wdata,
    output wfull,
    input rclk,
    input rrstn,
    input rinc,
    output rempty,
    output [WIDTH-1:0] rdata
);

    localparam ADDR_WIDTH = $clog2(DEPTH);
    localparam PTR_WIDTH = ADDR_WIDTH + 1;


    reg [PTR_WIDTH-1:0] waddr_bin = 0;
    reg [PTR_WIDTH-1:0] wgray = 0;


    reg [PTR_WIDTH-1:0] raddr_bin = 0;
    reg [PTR_WIDTH-1:0] rgray = 0;


    reg [PTR_WIDTH-1:0] rgray_sync1 = 0, rgray_sync2 = 0;
    reg [PTR_WIDTH-1:0] wgray_sync1 = 0, wgray_sync2 = 0;


    function [PTR_WIDTH-1:0] bin2gray;
        input [PTR_WIDTH-1:0] bin;
        bin2gray = bin ^ (bin >> 1);
    endfunction


    function [PTR_WIDTH-1:0] gray2bin;
        input [PTR_WIDTH-1:0] gray;
        reg [PTR_WIDTH-1:0] bin;
        integer i;
        begin
            bin[PTR_WIDTH-1] = gray[PTR_WIDTH-1];
            for (i = PTR_WIDTH-2;
 i >= 0;
 i = i - 1)
                bin[i] = bin[i+1] ^ gray[i];
            gray2bin = bin;
        end
    endfunction


    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn) begin
            waddr_bin <= 0;
            wgray <= 0;
        end else begin
            if (winc && !wfull) begin
                waddr_bin <= waddr_bin + 1;
                wgray <= bin2gray(waddr_bin + 1);
            end
        end
    end


    always @(posedge rclk or negedge rrstn) begin
        if (!rrstn) begin
            raddr_bin <= 0;
            rgray <= 0;
        end else begin
            if (rinc && !rempty) begin
                raddr_bin <= raddr_bin + 1;
                rgray <= bin2gray(raddr_bin + 1);
            end
        end
    end


    always @(posedge wclk) begin
        rgray_sync1 <= rgray;
        rgray_sync2 <= rgray_sync1;
    end


    always @(posedge rclk) begin
        wgray_sync1 <= wgray;
        wgray_sync2 <= wgray_sync1;
    end


    wire [PTR_WIDTH-1:0] raddr_bin_sync = gray2bin(rgray_sync2);
    wire [PTR_WIDTH-1:0] waddr_bin_sync = gray2bin(wgray_sync2);


    assign wfull = (waddr_bin - raddr_bin_sync) >= DEPTH;


    assign rempty = (raddr_bin == waddr_bin_sync);


    dual_port_RAM #(
        .WIDTH(WIDTH),
        .DEPTH(DEPTH)
    ) ram (
        .wclk(wclk),
        .wenc(winc && !wfull),
        .waddr(waddr_bin[ADDR_WIDTH-1:0]),
        .wdata(wdata),
        .rclk(rclk),
        .renc(rinc && !rempty),
        .raddr(raddr_bin[ADDR_WIDTH-1:0]),
        .rdata(rdata)
    );

endmodule

