    end else begin
        if (cnt == 2'b11) begin
            shift_reg <= d;
            cnt <= 2'b00;
            valid_out <= 1;
            dout <= d[3];
        end else begin
            shift_reg <= shift_reg << 1;
            valid_out <= 0;
            dout <= shift_reg[3];
            cnt <= cnt + 1;
        end
    end
