module traffic_light (
    input  wire      rst_n,
    input  wire      clk,
    input  wire      pass_request,
    output wire [7:0] clock,
    output reg       red,
    output reg       yellow,
    output reg       green
);


    parameter [1:0] idle     = 2'b00,
                    s1_red   = 2'b01,
                    s2_yellow= 2'b10,
                    s3_green = 2'b11;

    reg  [1:0] state;
    reg  [7:0] cnt;
    reg        p_red, p_yellow, p_green;


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= idle;
            red <= 0;
            yellow <= 0;
            green <= 0;
        end else begin
            case (state)
                idle: begin
                    state <= s1_red;
                    red <= 1;
                    green <= 0;
                    yellow <= 0;
                end

                s1_red: begin
                    if (cnt == 0) begin
                        state <= s3_green;
                        red <= 0;
                        green <= 1;
                    end
                end

                s3_green: begin
                    if (cnt == 0) begin
                        state <= s2_yellow;
                        green <= 0;
                        yellow <= 1;
                    end
                end

                s2_yellow: begin
                    if (cnt == 0) begin
                        state <= s1_red;
                        yellow <= 0;
                        red <= 1;
                    end
                end

                default: state <= idle;
            endcase
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cnt <= 10;
        end else begin
            if (pass_request && green) begin
                cnt <= 10;
            end else if (!green && p_green) begin
                cnt <= 60;
            end else if (!yellow && p_yellow) begin
