module alu (
    input [31:0] a,
    input [31:0] b,
    input [5:0] aluc,
    output reg [31:0] r = 0,
    output zero,
    output reg carry = 0,
    output negative,
    output reg overflow = 0,
    output flag = 1'bz
);

    assign zero = (r == 32'd0);
    assign negative = r[31];

    assign flag = (aluc == 6'b101010 || aluc == 6'b101011) ? 
                  (aluc == 6'b101010 ? ($signed(a) < $signed(b)) : (a < b)) : 
                  1'bz;

    always @(*) begin
        carry = 0;
        overflow = 0;
        r = 32'bz;

        case (aluc)

            6'b100000: begin
                {carry, r} = {1'b0, a} + {1'b0, b};
                overflow = ( (a[31] == b[31]) && (r[31] != a[31]) );
            end

            6'b100001: begin
                {carry, r} = {1'b0, a} + {1'b0, b};
                overflow = 0;
            end

            6'b100010: begin
                {carry, r} = {1'b0, a} - {1'b0, b};
                overflow = ( (a[31] != b[31]) && (r[31] != a[31]) );
            end

            6'b100011: begin
                {carry, r} = {1'b0, a} - {1'b0, b};
                overflow = 0;
            end

            6'b100100: r = a & b;

            6'b100101: r = a | b;

            6'b100110: r = a ^ b;

            6'b100111: r = ~(a | b);

            6'b101010: r = ($signed(a) < $signed(b)) ? 32'd1 : 32'd0;

            6'b101011: r = (a < b) ? 32'd1 : 32'd0;

            6'b000000: r = b << a[4:0];

            6'b000010: r = b >> a[4:0];

            6'b000011: r = $signed(b) >>> a[4:0];

            6'b000100: r = b << a[4:0];

            6'b000110: r = b >> a[4:0];

            6'b000111: r = $signed(b) >>> a[4:0];

            6'b001111: r = {a[31:16], 16'd0};
            default: r = 32'bz;
        endcase
    end

endmodule

