module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

    reg [2:0] cnt;
    reg processing;
    reg [7:0] remainder;
    reg [7:0] quotient;
    reg [7:0] dividend_abs;
    reg [7:0] divisor_abs;
    reg orig_dividend_sign;
    reg orig_divisor_sign;

    always @(posedge clk) begin
        if (rst) begin
            processing <= 0;
            cnt <= 0;
            res_valid <= 0;
            remainder <= 0;
            quotient <= 0;
            dividend_abs <= 0;
            divisor_abs <= 0;
            orig_dividend_sign <= 0;
            orig_divisor_sign <= 0;
        end else begin
            if (processing) begin
                if (cnt == 3'd7) begin
                    if (sign) begin
                        if (orig_dividend_sign) begin
                            remainder <= -remainder;
                        end
                        if (orig_dividend_sign ^ orig_divisor_sign) begin
                            quotient <= -quotient;
                        end
                    end
                    result <= {remainder, quotient};
                    res_valid <= 1;
                    processing <= 0;
                    cnt <= 0;
                end else begin
                    remainder <= remainder << 1;
                    quotient <= quotient << 1;
                    if (remainder >= divisor_abs) begin
                        remainder <= remainder - divisor_abs;
                        quotient[0] <= 1;
                    end else begin
                        quotient[0] <= 0;
                    end
                    cnt <= cnt + 1;
                end
            end else if (opn_valid && !res_valid) begin
                processing <= 1;
                cnt <= 0;
                res_valid <= 0;
                orig_dividend_sign <= sign ? dividend[7] : 0;
                orig_divisor_sign <= sign ? divisor[7] : 0;
                if (sign) begin
                    dividend_abs <= dividend[7] ? -dividend : dividend;
                    divisor_abs <= divisor[7] ? -divisor : divisor;
                end else begin
                    dividend_abs <= dividend;
                    divisor_abs <= divisor;
                end
                remainder <= 0;
                quotient <= dividend_abs << 1;
            end else begin
                if (res_valid) begin
                    res_valid <= 0;
                end
            end
        end
    end

endmodule

