reg [7:0] b_reg;


always @* begin
    a_reg = A;
    b_reg = B;
end


reg [15:0] temp_remainder;
reg [15:0] temp_quotient;
integer i;

always @* begin
    temp_remainder = 16'b0;
    temp_quotient = 16'b0;
    for (i = 15;
 i >= 0;
 i = i - 1) begin
        temp_remainder = {temp_remainder[14:0], (a_reg >> i) & 1'b1};
        if (temp_remainder >= {8'b0, b_reg}) begin
            temp_remainder = temp_remainder - {8'b0, b_reg};
            temp_quotient = {temp_quotient[14:0], 1'b1};
        end else begin
            temp_quotient = {temp_quotient[14:0], 1'b0};
        end
    end
    result = temp_quotient;
    odd = temp_remainder;
end

endmodule

