module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z = 0
);

reg [2:0] counter;
reg [23:0] a_mantissa, b_mantissa;
reg [8:0] a_exponent, b_exponent;
reg a_sign, b_sign;
reg [49:0] product;
reg guard_bit, round_bit, sticky;

always @(posedge clk) begin
    if (rst) begin
        counter <= 3'b0;
        z <= 32'b0;
        a_sign <= 0;
        b_sign <= 0;
        a_exponent <= 0;
        b_exponent <= 0;
        a_mantissa <= 0;
        b_mantissa <= 0;
        product <= 0;
    end else begin
        case (counter)
            3'b000: begin

                a_sign <= a[31];
                b_sign <= b[31];
                a_exponent <= {1'b0, a[30:23]};
                b_exponent <= {1'b0, b[30:23]};
                a_mantissa <= (a[30:23] == 8'b0) ? {1'b0, a[22:0]} : {1'b1, a[22:0]};
                b_mantissa <= (b[30:23] == 8'b0) ? {1'b0, b[22:0]} : {1'b1, b[22:0]};


                if ((a[30:23] == 8'hff && |a[22:0]) ||  
                    (b[30:23] == 8'hff && |b[22:0])) begin
                    z <= {a_sign ^ b_sign, 8'hff, 23'h1};
                end else if ((a[30:23] == 8'hff) ||      
                            (b[30:23] == 8'hff)) begin
                    if ((a[30:23] == 8'hff && b[30:23] == 8'hff) ||
                        (a[30:23] == 8'hff && (b[30:23] == 0 && &b[22:0])) ||
                        (b[30:23] == 8'hff && (a[30:23] == 0 && &a[22:0]))) begin
                        z <= {a_sign ^ b_sign, 8'hff, 23'h1};
                    end else begin
                        z <= {a_sign ^ b_sign, 8'hff, 23'h0};
                    end
                end else if ((|a_mantissa[22:0] == 0) || (|b_mantissa[22:0] == 0)) begin
                    z <= {a_sign ^ b_sign, 8'h0, 23'h0};
                end else begin
                    product <= {1'b0, a_mantissa} * {1'b0, b_mantissa};
                    counter <= 3'b001;
                end
            end

            3'b001: begin

                if (product[49:48] == 2'b11) begin
                    product <= product >> 1;
                    a_exponent <= a_exponent + b_exponent - 9'd127 + 9'd1;
                end else if (product[49:48] == 2'b10) begin
                    product <= product >> 1;
                    a_exponent <= a_exponent + b_exponent - 9'd127 + 9'd1;
                end else begin
                    a_exponent <= a_exponent + b_exponent - 9'd127;
                end
                counter <= 3'b010;
            end

            3'b010: begin

                {sticky, round_bit, guard_bit} = {product[21:0], product[22], product[23]};
                if (guard_bit && (round_bit || sticky)) begin
                    product[47:24] = product[47:24] + 1;
                end
                if (product[47:24] == 24'h1000000) begin
                    product[47:24] = 24'h800000;
                    a_exponent = a_exponent + 1;
                end
                counter <= 3'b011;
            end

            3'b011: begin

                if (a_exponent[8] || (a_exponent < 9'd1)) begin
                    z <= {a_sign ^ b_sign, 8'h0, 23'h0};
                end else begin
                    z <= {a_sign ^ b_sign, a_exponent[7:0], product[47:25]};
                end
                counter <= 3'b000;
            end
        endcase
    end
end

endmodule

