module asyn_fifo #(
    parameter WIDTH = 8,
    parameter DEPTH = 16
) (
    input wclk,
    input wrstn,
    input winc,
    input [WIDTH-1:0] wdata,
    input rclk,
    input rrstn,
    input rinc,
    output reg rempty,
    output reg wfull,
    output [WIDTH-1:0] rdata
);

    dual_port_RAM #(
        .WIDTH(WIDTH),
        .DEPTH(DEPTH)
    ) ram (
        .wclk(wclk),
        .wenc(wenc),
        .waddr(waddr[3:0]),
        .wdata(wdata),
        .rclk(rclk),
        .renc(renc),
        .raddr(raddr[3:0]),
        .rdata(rdata)
    );

    reg [4:0] waddr_bin;
    wire [4:0] wptr_gray;
    reg [4:0] rptr_gray_sync1, rptr_gray_sync2;

    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn) begin
            waddr_bin <= 0;
            rptr_gray_sync1 <= 0;
            rptr_gray_sync2 <= 0;
        end else begin
            if (winc && !wfull) begin
                waddr_bin <= waddr_bin + 1;
            end
            rptr_gray_sync1 <= rptr_gray;
            rptr_gray_sync2 <= rptr_gray_sync1;
        end
    end

    assign wptr_gray = (waddr_bin >> 1) ^ waddr_bin;

    wire full_condition = (wptr_gray == { ~rptr_gray_sync2[4:3], rptr_gray_sync2[2:0] });

    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn) begin
            wfull <= 0;
        end else begin
            wfull <= full_condition;
        end
    end

    reg [4:0] raddr_bin;
    wire [4:0] rptr_gray;
    reg [4:0] wptr_gray_sync1, wptr_gray_sync2;

    always @(posedge rclk or negedge rrstn) begin
        if (!rrstn) begin
            raddr_bin <= 0;
            wptr_gray_sync1 <= 0;
            wptr_gray_sync2 <= 0;
        end else begin
            if (rinc && !rempty) begin
                raddr_bin <= raddr_bin + 1;
            end
            wptr_gray_sync1 <= wptr_gray;
            wptr_gray_sync2 <= wptr_gray_sync1;
        end
    end

    assign rptr_gray = (raddr_bin >> 1) ^ raddr_bin;

    wire empty_condition = (rptr_gray == wptr_gray_sync2);

    always @(posedge rclk or negedge rrstn) begin
        if (!rrstn) begin
            rempty <= 1;
        end else begin
            rempty <= empty_condition;
        end
    end

    wire wenc = winc && !wfull;
    wire renc = rinc && !rempty;

    wire [3:0] waddr = waddr_bin[3:0];
    wire [3:0] raddr = raddr_bin[3:0];

endmodule

