module LIFObuffer (
    input [3:0] dataIn,
    input RW,
    input EN,
    input Rst,
    input Clk,
    output reg EMPTY,
    output reg FULL,
    output reg [3:0] dataOut
);

reg [3:0] stack_mem [0:3];
reg [2:0] SP;

always @(posedge Clk) begin
    if (Rst) begin
        SP <= 3'b100;

        stack_mem[0] <= 4'b0;
        stack_mem[1] <= 4'b0;
        stack_mem[2] <= 4'b0;
        stack_mem[3] <= 4'b0;
        EMPTY <= 1;
        FULL <= 0;
    end else if (EN) begin
        reg [2:0] next_SP;
        reg [3:0] next_stack_mem [0:3];
        reg [3:0] temp_dataOut;


        next_SP = SP;
        for (int i = 0;
 i < 4;
 i = i + 1) begin
            next_stack_mem[i] = stack_mem[i];
        end
        temp_dataOut = dataOut;

        if (RW) begin 
            if (!EMPTY) begin
                temp_dataOut = stack_mem[SP];
                next_stack_mem[SP] = 4'b0;

                next_SP = SP + 1;
            end
        end else begin 
            if (!FULL) begin
                next_stack_mem[SP] = dataIn;
                next_SP = SP - 1;
            end
        end


        stack_mem[0] <= next_stack_mem[0];
        stack_mem[1] <= next_stack_mem[1];
        stack_mem[2] <= next_stack_mem[2];
        stack_mem[3] <= next_stack_mem[3];
        SP <= next_SP;
        dataOut <= temp_dataOut;


        EMPTY <= (next_SP == 3'b100);
        FULL <= (next_SP == 3'b000);
    end
end

endmodule

