module width_8to16 (
    input clk,
    input rst_n,
    input valid_in,
    input [7:0] data_in,
    output reg valid_out = 0,
    output reg [15:0] data_out = 0
);

reg [7:0] data_reg;
reg has_data;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        data_reg <= 8'b0;
        has_data <= 0;
        valid_out <= 0;
        data_out <= 0;
    end else begin
        if (valid_in) begin
            if (!has_data) begin
                data_reg <= data_in;
                has_data <= 1;
                valid_out <= 0;
            end else begin
                data_out <= {data_reg, data_in};
                valid_out <= 1;
                has_data <= 0;
            end
        end
