module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

reg [7:0] abs_dividend, abs_divisor;
reg [7:0] original_dividend_sign, original_divisor_sign;
reg [15:0] SR;
reg [3:0] cnt;
reg start_cnt;
reg [7:0] NEG_DIVISOR;

always @(posedge clk) begin
    if (rst) begin
        res_valid <= 0;
        cnt <= 0;
        start_cnt <= 0;
        SR <= 0;
        NEG_DIVISOR <= 0;
        original_dividend_sign <= 0;
        original_divisor_sign <= 0;
        abs_dividend <= 0;
        abs_divisor <= 0;
        result <= 0;
    end else begin
        if (opn_valid && !res_valid) begin
            if (sign) begin
                original_dividend_sign <= dividend[7];
                original_divisor_sign <= divisor[7];
                abs_dividend <= dividend[7] ? -dividend : dividend;
                abs_divisor <= divisor[7] ? -divisor : divisor;
            end else begin
                original_dividend_sign <= 0;
                original_divisor_sign <= 0;
                abs_dividend <= dividend;
                abs_divisor <= divisor;
            end

            SR <= {abs_dividend, 8'b0} << 1;
            NEG_DIVISOR <= -abs_divisor;
            cnt <= 1;
            start_cnt <= 1;
            res_valid <= 0;
        end else if (start_cnt) begin
            if (cnt == 8) begin
                start_cnt <= 0;
                cnt <= 0;
                res_valid <= 1;

                if (sign) begin
                    result[7:0] <= (original_dividend_sign ^ original_divisor_sign) ? -SR[7:0] : SR[7:0];
                    result[15:8] <= original_dividend_sign ? -abs_dividend : abs_dividend;
                end else begin
                    result <= {SR[15:8], SR[7:0]};
                end
            end else begin
                reg [8:0] sub_result;
                sub_result = {1'b0, SR[15:8]} - {1'b0, NEG_DIVISOR};

                if (sub_result[8]) begin
                    SR[15:8] <= sub_result[7:0];
                    SR[7:0] <= {SR[7:0][6:0], 1'b0};
                end else begin
                    SR[15:8] <= sub_result[7:0];
                    SR[7:0] <= {SR[7:0][6:0], 1'b1};
                end

                cnt <= cnt + 1;
            end
        end else if (res_valid) begin
            res_valid <= 0;
        end
    end
end

endmodule

