module div_16bit (
    input [15:0] A,
    input [7:0] B,
    output reg [15:0] result = 0,
    output reg [15:0] odd = 0
);

reg [15:0] a_reg;
reg [7:0] b_reg;

always @(*) begin
    a_reg = A;
    b_reg = B;
end

always @(*) begin
    reg [8:0] remainder;

    reg [15:0] quotient;
    integer i;

    remainder = 9'b0;
    quotient = 16'b0;

    for (i = 0;
 i < 16;
 i = i + 1) begin

        remainder = (remainder << 1) | ((a_reg >> (15 - i)) & 1);


        if (remainder >= {1'b0, b_reg}) begin
            remainder = remainder - {1'b0, b_reg};
            quotient[i] = 1'b1;
        end else begin
            quotient[i] = 1'b0;
        end
    end

    result = quotient;

    odd = {7'b0, remainder[7:0]};
end

endmodule

