module accu (
    input clk,
    input rst_n,
    input [7:0] data_in,
    input valid_in,
    output reg valid_out,
    output reg [9:0] data_out
);

    reg [1:0] state;
    reg [9:0] sum_reg;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= 2'b00;
            sum_reg <= 10'b0;
            valid_out <= 1'b0;
            data_out <= 10'b0;
        end else begin
            valid_out <= 1'b0;

            if (valid_in) begin
                case (state)
                    2'b00: begin 
                        sum_reg <= data_in;
                        state <= 2'b01;
                    end
                    2'b01: begin 
                        sum_reg <= sum_reg + data_in;
                        state <= 2'b10;
                    end
                    2'b10: begin 
                        sum_reg <= sum_reg + data_in;
                        state <= 2'b11;
                    end
                    2'b11: begin 
                        sum_reg <= sum_reg + data_in;
                        data_out <= sum_reg + data_in;
                        valid_out <= 1'b1;
                        state <= 2'b00;
                    end
                    default: state <= 2'b00;
                endcase
            end
        end
    end

endmodule

