module fixed_point_adder #(
    parameter Q = 4, 
    parameter N = 8  
) (
    input [N-1:0] a,
    input [N-1:0] b,
    output reg [N-1:0] c
);

    reg [N-1:0] res;
    wire sign_a = a[N-1];
    wire sign_b = b[N-1];
    wire same_sign = (sign_a == sign_b);
    wire [N-1:0] abs_a = sign_a ? ( (1 << (N-1)) - a[N-2:0] ) : a;
    wire [N-1:0] abs_b = sign_b ? ( (1 << (N-1)) - b[N-2:0] ) : b;
    wire signed [N:0] sum_signed = $signed(a) + $signed(b);
    localparam max_positive = (1 << (N-1)) - 1;
    localparam min_negative = -(1 << (N-1));
    wire overflow = (sum_signed > $signed(max_positive)) || (sum_signed < $signed(min_negative));

    always @(*) begin
        if (same_sign) begin
            if (overflow) begin
                res = sign_a ? {N{1'b1}} : {1'b0, {(N-1){1'b1}}};
            end else begin
                res = sum_signed[N-1:0];
            end
        end else begin
            if (abs_a > abs_b) begin
                res = {1'b0, abs_a[N-2:0] - abs_b[N-2:0]};
            end else if (abs_b > abs_a) begin
                res = {1'b1, abs_b[N-2:0] - abs_a[N-2:0]};
            end else begin
                res = {N{1'b0}};
            end
        end
        c = res;
    end

endmodule

