    always @(posedge clk) begin
        if (rst) begin
            counter <= 0;
            z <= 0;
            sign <= 0;
            mantissa <= 0;
            exponent_sum <= 0;
            guard <= 0;
            round <= 0;
            sticky <= 0;
        end else begin
            case (counter)
                0: begin

                    a_sign <= a[31];
                    b_sign <= b[31];
                    a_exponent <= a[30:23];
                    b_exponent <= b[30:23];
                    a_frac <= a[22:0];
                    b_frac <= b[22:0];


                    if ((a_exponent == 8'hFF && a_frac != 0) || (b_exponent == 8'hFF && b_frac != 0)) begin

                        z <= 32'h7FC00000;
                        counter <= 5;
                    end else if ((a_exponent == 0 && a_frac == 0) || (b_exponent == 0 && b_frac == 0)) begin

                        if (a_exponent == 0 && b_exponent == 0) begin
                            z <= {a_sign ^ b_sign, 31'h0};
                        end else if (a_exponent == 0 && (b_exponent != 0 || b_frac != 0)) begin

                            if (b_exponent == 8'hFF) begin
                                z <= 32'h7FC00000;
                            end else begin
                                z <= {a_sign ^ b_sign, 31'h0};
                            end
                        end else begin

                            if (a_exponent == 8'hFF) begin
                                z <= 32'h7FC00000;
                            end else begin
                                z <= {a_sign ^ b_sign, 31'h0};
                            end
                        end
                        counter <= 5;
                    end else if (a_exponent == 8'hFF) begin

                        if (b_exponent == 8'hFF) begin
                            if (a_frac == 0 && b_frac == 0) begin

                                z <= {a_sign ^ b_sign, 8'hFF, 23'h0};
                            end else begin
                                z <= 32'h7FC00000;
                            end
                        end else begin
                            z <= {a_sign ^ b_sign, 8'hFF, 23'h0};
                        end
                        counter <= 5;
                    end else if (b_exponent == 8'hFF) begin

                        z <= {a_sign ^ b_sign, 8'hFF, 23'h0};
                        counter <= 5;
                    end else begin


                        a_mant <= (a_exponent == 0) ? {1'b0, a_frac} : {1'b1, a_frac};
                        b_mant <= (b_exponent == 0) ? {1'b0, b_frac} : {1'b1, b_frac};
                        counter <= counter + 1;
                    end
                end
                1: begin

                    product <= a_mant * b_mant;
                    exponent_sum <= a_exponent + b_exponent - 8'd127;

                    counter <= counter + 1;
                end
                2: begin


                    norm_product = product;
                    if (product[47]) begin

                        norm_product = product;
                        exponent_sum <= exponent_sum - 0;
                    end else if (product[46]) begin

                        norm_product = product >> 1;
                        exponent_sum <= exponent_sum + 1;
                    end else begin


                        norm_product = 0;
                    end

                    {guard, round, sticky} <= {product[0], product[1], |product[48:2]};
                    counter <= counter + 1;
                end
                3: begin


                    if (round) begin
                        if (guard) begin
                            mantissa <= mantissa + 1;
                            if (mantissa == 23'h7FFFFF) begin
                                mantissa <= 0;
                                exponent_sum <= exponent_sum + 1;
                            end
                        end
                    end
                    counter <= counter + 1;
                end
                4: begin

                    if (exponent_sum >= 255) begin

                        z <= {sign, 8'hFF, 23'h0};
                    end else if (exponent_sum <= 0) begin

                        z <= {sign, 31'h0};
                    end else begin

                        z <= {sign, exponent_sum[7:0], mantissa};
                    end
                    counter <= counter + 1;
                end
                5: begin

                    counter <= 0;
                end
                default: counter <= 0;
            endcase
        end
    end

