module fsm (
    input CLK,
    input RST,
    input IN,
    output reg MATCH
);

    reg [2:0] current_state, next_state;

    parameter S0 = 3'b000;
    parameter S1 = 3'b001;
    parameter S2 = 3'b010;
    parameter S3 = 3'b011;
    parameter S4 = 3'b100;
    parameter S5 = 3'b101;

    always @(posedge CLK or posedge RST) begin
        if (RST) begin
            current_state <= S0;
            MATCH <= 1'b0;
        end else begin
            current_state <= next_state;
        end
    end

    always @(*) begin
        case (current_state)
            S0: begin
                if (IN) begin
                    next_state = S1;
                    MATCH = 1'b0;
                end else begin
                    next_state = S0;
                    MATCH = 1'b0;
                end
            end
            S1: begin
                if (!IN) begin
                    next_state = S2;
                    MATCH = 1'b0;
                end else begin
                    next_state = S1;
                    MATCH = 1'b0;
                end
            end
            S2: begin
                if (!IN) begin
                    next_state = S3;
                    MATCH = 1'b0;
                end else begin
                    next_state = S0;
                    MATCH = 1'b0;
                end
            end
            S3: begin
                if (IN) begin
                    next_state = S4;
                    MATCH = 1'b0;
                end else begin
                    next_state = S0;
                    MATCH = 1'b0;
                end
            end
