module alu (
    input [31:0] a,
    input [31:0] b,
    input [5:0] aluc,
    output reg [31:0] r,
    output zero,
    output carry,
    output negative,
    output overflow,
    output flag
);

    parameter ADD  = 6'b100000;
    parameter ADDU = 6'b100001;
    parameter SUB  = 6'b100010;
    parameter SUBU = 6'b100011;
    parameter AND  = 6'b100100;
    parameter OR   = 6'b100101;
    parameter XOR  = 6'b100110;
    parameter NOR  = 6'b100111;
    parameter SLT  = 6'b101010;
    parameter SLTU = 6'b101011;
    parameter SLL  = 6'b000000;
    parameter SRL  = 6'b000010;
    parameter SRA  = 6'b000011;
    parameter SLLV = 6'b000100;
    parameter SRLV = 6'b000110;
    parameter SRAV = 6'b000111;
    parameter LUI  = 6'b001111;

    reg [32:0] sum;

    reg [31:0] shift_amount;
    reg signed_lt, unsigned_lt;


    wire carry_addu = (a + b) >> 32;
    wire carry_subu = (a >= b) ? 1'b1 : 1'b0;
    wire overflow_add = (a[31] == b[31]) && (sum[31] != a[31]);
    wire overflow_sub = (a[31] != b[31]) && (sum[31] != a[31]);


    always @(*) begin
        case (aluc)
            SLL, SRL, SRA: shift_amount = a[4:0];
            SLLV, SRLV, SRAV: shift_amount = b[4:0];
            default: shift_amount = 5'b0;
        endcase
    end


    always @(*) begin
        case (aluc)
            ADD: begin
                sum = {a[31], a} + {b[31], b};
                r = sum[31:0];
                carry = sum[32];
                overflow = overflow_add;
            end
            ADDU: begin
                r = a + b;
                carry = carry_addu;
                overflow = 0;
            end
            SUB: begin
                sum = {a[31], a} - {b[31], b};
                r = sum[31:0];
                carry = ~sum[32];

                overflow = overflow_sub;
            end
            SUBU: begin
                r = a - b;
                carry = carry_subu;
                overflow = 0;
            end
            AND: r = a & b;
