module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);


reg [15:0] shift_reg;
reg [3:0] cnt;
reg [7:0] abs_dividend;
reg [7:0] abs_divisor;
reg sign_dividend, sign_divisor;

reg [1:0] state;

localparam IDLE = 2'b00;
localparam BUSY = 2'b01;

always @(posedge clk) begin
    if (rst) begin
        state <= IDLE;
        res_valid <= 0;
        shift_reg <= 0;
        cnt <= 0;
        abs_dividend <= 0;
        abs_divisor <= 0;
        sign_dividend <= 0;
        sign_divisor <= 0;
        result <= 0;
    end else begin
        case (state)
            IDLE: begin
                res_valid <= 0;
                if (opn_valid) begin

                    if (sign) begin
                        sign_dividend <= dividend[7];
                        sign_divisor <= divisor[7];
                        abs_dividend <= dividend[7] ? -dividend : dividend;
                        abs_divisor <= divisor[7] ? -divisor : divisor;
                    end else begin
                        sign_dividend <= 0;
                        sign_divisor <= 0;
                        abs_dividend <= dividend;
                        abs_divisor <= divisor;
                    end

                    shift_reg <= {8'b0, abs_dividend};
                    cnt <= 0;
                    state <= BUSY;
                end
            end
            BUSY: begin
                if (cnt < 8) begin

                    reg [15:0] temp_shift = shift_reg;

                    temp_shift = {temp_shift[14:0], 1'b0};

                    if (temp_shift[15:8] >= abs_divisor) begin
                        temp_shift[15:8] = temp_shift[15:8] - abs_divisor;
                        temp_shift[0] = 1'b1;
                    end else begin
                        temp_shift[0] = 1'b0;
                    end
                    shift_reg <= temp_shift;
                    cnt <= cnt + 1;
                end else begin

                    if (sign) begin

                        reg [7:0] abs_quotient = shift_reg[7:0];
                        reg [7:0] abs_remainder = shift_reg[15:8];


                        if (sign_dividend ^ sign_divisor) begin
                            abs_quotient = -abs_quotient;
                        end


                        if (sign_dividend) begin
                            abs_remainder = -abs_remainder;
                        end

                        result <= {abs_remainder, abs_quotient};
                    end else begin
                        result <= shift_reg;
                    end
                    res_valid <= 1;
                    state <= IDLE;
                end
            end
        endcase
    end
end

endmodule

