        reg [15:0] temp_quotient;
        integer i;

        temp_remainder = 0;
        temp_quotient = 0;

        for (i = 15;
 i >= 0;
 i = i - 1) begin

            temp_remainder = temp_remainder << 1;
            temp_remainder[0] = a_reg[i];

            if (temp_remainder >= b_reg) begin
                temp_remainder = temp_remainder - b_reg;
                temp_quotient[i] = 1;
            end else begin
                temp_quotient[i] = 0;
            end
        end

        result = temp_quotient;
        odd = temp_remainder;
    end

endmodule

