    if (!rst_n) begin
        count <= 0;
        valid_out <= 0;
        data_out <= 0;
        buffer[0] <= 0;
        buffer[1] <= 0;
        buffer[2] <= 0;
        buffer[3] <= 0;
    end else begin
        valid_out <= 0;

        if (valid_in && (count < 4)) begin
            buffer[count[1:0]] <= data_in;

            count <= count + 1;
        end

        if (count == 4) begin
            data_out <= buffer[0] + buffer[1] + buffer[2] + buffer[3];
            valid_out <= 1;
            count <= 0;
        end
    end
end

endmodule

