module fixed_point_adder #(
    parameter Q = 4,  
    parameter N = 8   
) (
    input [N-1:0] a,
    input [N-1:0] b,
    output [N-1:0] c
);

reg [N-1:0] abs_a, abs_b;
reg a_sign, b_sign;
reg [N-2:0] magnitude;
reg result_sign;

always @* begin
    a_sign = a[N-1];
    b_sign = b[N-1];


    abs_a = a_sign ? (~a[N-2:0] + 1) : a[N-2:0];
    abs_b = b_sign ? (~b[N-2:0] + 1) : b[N-2:0];

    if (a_sign == b_sign) begin

        c = a + b;
    end else begin

        if (abs_a > abs_b) begin
            magnitude = abs_a - abs_b;
            result_sign = a_sign;
        end else if (abs_b > abs_a) begin
            magnitude = abs_b - abs_a;
            result_sign = b_sign;
        end else begin

            magnitude = 0;
            result_sign = 0;
        end


        c = {result_sign, magnitude};
    end
end

endmodule

