module parallel2serial (
    input clk,
    input rst_n,
    input [3:0] d,
    output reg valid_out,
    output reg dout
);

    reg [1:0] cnt;
    reg [3:0] data;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cnt <= 2'b0;
            data <= 4'b0;
            valid_out <= 1'b0;
        end else begin
            if (cnt == 2'b11) begin
                data <= d;
                cnt <= 2'b00;
                valid_out <= 1'b1;
            end else begin
                cnt <= cnt + 1;
                valid_out <= 1'b1;
            end
        end
    end

    always @(*) begin
        case (cnt)
            2'b00: dout = data[3];
            2'b01: dout = data[2];
            2'b10: dout = data[1];
            2'b11: dout = data[0];
            default: dout = 1'b0;
        endcase
    end

