module width_8to16 (
    input clk,
    input rst_n,
    input valid_in,
    input [7:0] data_in,
    output reg valid_out,
    output reg [15:0] data_out
);

reg [7:0] first_data;
reg [7:0] second_data;
reg has_first;
reg valid_next;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        first_data <= 0;
        second_data <= 0;
        has_first <= 0;
        valid_out <= 0;
        data_out <= 0;
        valid_next <= 0;
    end else begin
        valid_out <= 0;
        if (valid_next) begin
            data_out <= {first_data, second_data};
            valid_out <= 1;
            valid_next <= 0;
        end

        if (has_first) begin
            if (valid_in) begin
                second_data <= data_in;
                valid_next <= 1;
                has_first <= 0;
            end
        end else if (valid_in) begin
            first_data <= data_in;
            has_first <= 1;
        end
    end
end

