module alu (
    input [31:0] a,
    input [31:0] b,
    input [5:0] aluc,
    output reg [31:0] r,
    output zero,
    output carry,
    output negative,
    output overflow,
    output flag
);

    parameter ADD  = 6'b100000;
    parameter ADDU = 6'b100001;
    parameter SUB  = 6'b100010;
    parameter SUBU = 6'b100011;
    parameter AND  = 6'b100100;
    parameter OR   = 6'b100101;
    parameter XOR  = 6'b100110;
    parameter NOR  = 6'b100111;
    parameter SLT  = 6'b101010;
    parameter SLTU = 6'b101011;
    parameter SLL  = 6'b000000;
    parameter SRL  = 6'b000010;
    parameter SRA  = 6'b000011;
    parameter SLLV = 6'b000100;
    parameter SRLV = 6'b000110;
    parameter SRAV = 6'b000111;
    parameter LUI  = 6'b001111;

    reg [32:0] res_temp;
    reg [31:0] result;
    reg carry_out;
    reg overflow_out;

    always @(*) begin
        case (aluc)
            ADD: begin
                res_temp = {1'b0, a} + {1'b0, b};
                result = res_temp[31:0];
                carry_out = res_temp[32];
                overflow_out = (a[31] == b[31]) && (result[31] != a[31]);
            end
            ADDU: begin
                res_temp = {1'b0, a} + {1'b0, b};
                result = res_temp[31:0];
                carry_out = res_temp[32];
                overflow_out = 0;
            end
            SUB: begin
                res_temp = {1'b0, a} - {1'b0, b};
                result = res_temp[31:0];
                carry_out = res_temp[32];
                overflow_out = (a[31] != b[31]) && (result[31] != a[31]);
            end
            SUBU: begin
                res_temp = {1'b0, a} - {1'b0, b};
                result = res_temp[31:0];
                carry_out = res_temp[32];
                overflow_out = 0;
            end
            AND: begin
                result = a & b;
                carry_out = 0;
                overflow_out = 0;
            end
            OR: begin
                result = a | b;
                carry_out = 0;
                overflow_out = 0;
            end
            XOR: begin
                result = a ^ b;
                carry_out = 0;
                overflow_out = 0;
            end
            NOR: begin
                result = ~(a | b);
                carry_out = 0;
                overflow_out = 0;
            end
            SLT: begin
                result = ($signed(a) < $signed(b)) ? 32'd1 : 32'd0;
                carry_out = 0;
                overflow_out = 0;
            end
            SLTU: begin
                result = (a < b) ? 32'd1 : 32'd0;
                carry_out = 0;
                overflow_out = 0;
            end
            SLL: begin
                result = a << b[4:0];
                carry_out = 0;
                overflow_out = 0;
            end
            SRL: begin
                result = a >> b[4:0];
                carry_out = 0;
                overflow_out = 0;
            end
            SRA: begin
                result = $signed(a) >>> b[4:0];
                carry_out = 0;
                overflow_out = 0;
            end
            SLLV: begin
                result = b << a[4:0];
                carry_out = 0;
                overflow_out = 0;
            end
            SRLV: begin
                result = b >> a[4:0];
                carry_out = 0;
                overflow_out = 0;
            end
            SRAV: begin
                result = $signed(b) >>> a[4:0];
                carry_out = 0;
                overflow_out = 0;
            end
            LUI: begin
                result = {a[31:16], 16'b0};
                carry_out = 0;
                overflow_out = 0;
            end
            default: begin
                result = 32'bz;
                carry_out = 0;
                overflow_out = 0;
            end
        endcase
    end

    assign zero = (result == 32'b0);
    assign negative = result[31];
    assign flag = (aluc == SLT || aluc == SLTU) ? 1'b1 : 1'bz;
    assign r = result;
    assign carry = carry_out;
    assign overflow = overflow_out;

endmodule

