    input [3:0] B,
    input Cin,
    output [3:0] Sum,
    output Cout
);

    wire [4:0] sum_bin = A + B + Cin;
    wire [4:0] sum_plus_6 = sum_bin + 5'd6;

    assign Sum = (sum_bin > 9) ? sum_plus_6[3:0] : sum_bin[3:0];
    assign Cout = (sum_bin > 9) ? sum_plus_6[4] : sum_bin[4];

