                a_reg <= adda;
                b_reg <= addb;
            end
            en_pipe <= {en_pipe[2:0], i_en};
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            sum_stage1 <= 16'b0;
            carry_stage1 <= 1'b0;
        end else if (en_pipe[0]) begin
            {carry_stage1, sum_stage1} <= a_reg[15:0] + b_reg[15:0];
        end
    end

    always @(posedge clk or negedge rst_n) begin
