module fixed_point_adder #(
    parameter Q = 4,
    parameter N = 8
) (
    input [N-1:0] a,
    input [N-1:0] b,
    output [N-1:0] c
);

reg [N-1:0] res;


localparam [N-1:0] MAX_POS = ( (1 << (N-Q)) - 1 ) << Q;
localparam [N-1:0] MIN_NEG = - ( (1 << (N-Q)) << Q );

always @(*) begin
    if (a[N-1] == b[N-1]) begin

        res = a + b;
        if (res[N-1] != a[N-1]) begin

            res = a[N-1] ? MIN_NEG : MAX_POS;
        end
    end else begin

        reg [N-1:0] abs_a = a[N-1] ? -a : a;
        reg [N-1:0] abs_b = b[N-1] ? -b : b;
        reg [N-1:0] diff;
        if (abs_a >= abs_b) begin
            diff = abs_a - abs_b;
            res = a[N-1] ? {1'b1, diff[N-2:0]} : {1'b0, diff[N-2:0]};
        end else begin
            diff = abs_b - abs_a;
            res = b[N-1] ? {1'b1, diff[N-2:0]} : {1'b0, diff[N-2:0]};
        end
    end
end

assign c = res;

endmodule

