module fixed_point_subtractor #(
    parameter Q = 8,
    parameter N = 16
) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output reg [N-1:0] c
);

reg [N-1:0] a_abs, b_abs;
reg a_sign, b_sign;
reg [N-1:0] res;
reg same_sign;

always @(*) begin
    a_sign = a[N-1];
    b_sign = b[N-1];


    a_abs = a_sign ? (~a + 1) : a;
    b_abs = b_sign ? (~b + 1) : b;

    same_sign = (a_sign == b_sign);

    if (same_sign) begin

        res = a - b;


        if (res == 0)
            res[N-1] = 0;
    end else begin

        if (a_sign == 0 && b_sign == 1) begin 
            res = (a > b) ? (a_abs + b_abs) : (b_abs - a_abs);
            res[N-1] = (a > b) ? 0 : 1;
        end else begin 
            res = (a < b) ? (a_abs + b_abs) : (b_abs - a_abs);
            res[N-1] = (a < b) ? 1 : 0;
        end


        if (res == 0)
            res[N-1] = 0;
    end

    c = res;
end

endmodule

