    reg a_sign, b_sign, z_sign;
    reg [7:0] a_exponent, b_exponent, z_exponent;
    reg [23:0] a_mantissa, b_mantissa;
    reg [47:0] product;
    reg guard_bit, round_bit, sticky;
    reg a_is_nan, b_is_nan, a_is_inf, b_is_inf, a_is_zero, b_is_zero;

    always @(posedge clk) begin
        if (rst) begin
            counter <= 0;
            z <= 0;
            a_sign <= 0;
            b_sign <= 0;
            a_exponent <= 0;
            b_exponent <= 0;
            a_mantissa <= 0;
            b_mantissa <= 0;
            product <= 0;
            guard_bit <= 0;
            round_bit <= 0;
            sticky <= 0;
            a_is_nan <= 0;
            b_is_nan <= 0;
            a_is_inf <= 0;
            b_is_inf <= 0;
            a_is_zero <= 0;
            b_is_zero <= 0;
        end else begin
            case (counter)
                0: begin

                    a_sign <= a[31];
                    b_sign <= b[31];
                    a_exponent <= a[30:23];
                    b_exponent <= b[30:23];
                    a_mantissa <= {1'b1, a[22:0]};
                    b_mantissa <= {1'b1, b[22:0]};

                    a_is_nan <= (a[30:23] == 8'hFF) && (|a[22:0]);
                    b_is_nan <= (b[30:23] == 8'hFF) && (|b[22:0]);
                    a_is_inf <= (a[30:23] == 8'hFF) && (a[22:0] == 0);
                    b_is_inf <= (b[30:23] == 8'hFF) && (b[22:0] == 0);
                    a_is_zero <= (a[30:23] == 0) && (a[22:0] == 0);
                    b_is_zero <= (b[30:23] == 0) && (b[22:0] == 0);

                    counter <= 1;
                end

                1: begin

                    product <= a_mantissa * b_mantissa;
                    counter <= 2;
                end

                2: begin

                    if (product[47:46] >= 2) begin
                        product <= product >> 1;
                        z_exponent <= a_exponent + b_exponent - 127 + 1;
                    end else begin
                        z_exponent <= a_exponent + b_exponent - 127;
                    end

                    {guard_bit, round_bit, sticky} <= {product[23], product[22], |product[21:0]};
                    z_mantissa <= product[46:24];
                    counter <= 3;
                end

                3: begin

                    if (guard_bit && (round_bit || sticky) || (guard_bit && !round_bit && !sticky)) begin
                        if (z_mantissa == 24'hFFFFFF) begin
                            z_exponent <= z_exponent + 1;
                            z_mantissa <= 24'h0;
                        end else begin
                            z_mantissa <= z_mantissa + 1;
                        end
                    end

                    if (z_exponent >= 8'hFF) begin
                        z <= {a_sign ^ b_sign, 8'hFF, 23'h0};
                    end else if (z_exponent == 0) begin
                        z <= {a_sign ^ b_sign, 8'h0, 23'h0};
                    end else begin
                        z <= {a_sign ^ b_sign, z_exponent, z_mantissa[22:0]};
                    end
                    counter <= 0;
                end

                default: counter <= 0;
            endcase
        end
    end

endmodule

