module asyn_fifo #(parameter WIDTH = 8, DEPTH = 16) (
    input wclk,
    input rclk,
    input wrstn,
    input rrstn,
    input winc,
    input rinc,
    input [WIDTH-1:0] wdata,
    output rempty,
    output wfull,
    output [WIDTH-1:0] rdata
);

    localparam ADDR_WIDTH = $clog2(DEPTH);
    localparam PTR_WIDTH = ADDR_WIDTH + 1;


    reg [PTR_WIDTH-1:0] wptr_bin, rptr_bin;
    reg [PTR_WIDTH-1:0] wptr_gray, rptr_gray;


    reg [PTR_WIDTH-1:0] wptr_gray_sync_rd_1, wptr_gray_sync_rd_2;
    reg [PTR_WIDTH-1:0] rptr_gray_sync_wr_1, rptr_gray_sync_wr_2;


    always @(posedge rclk or negedge rrstn) begin
        if (!rrstn) begin
            wptr_gray_sync_rd_1 <= 0;
            wptr_gray_sync_rd_2 <= 0;
        end else begin
            wptr_gray_sync_rd_1 <= wptr_gray;
            wptr_gray_sync_rd_2 <= wptr_gray_sync_rd_1;
        end
    end


    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn) begin
            rptr_gray_sync_wr_1 <= 0;
            rptr_gray_sync_wr_2 <= 0;
        end else begin
            rptr_gray_sync_wr_1 <= rptr_gray;
            rptr_gray_sync_wr_2 <= rptr_gray_sync_wr_1;
        end
    end


    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn)
            wptr_bin <= 0;
        else if (winc && !wfull)
            wptr_bin <= wptr_bin + 1;
    end


    assign wptr_gray = (wptr_bin >> 1) ^ wptr_bin;


    always @(posedge rclk or negedge rrstn) begin
        if (!rrstn)
            rptr_bin <= 0;
        else if (rinc && !rempty)
            rptr_bin <= rptr_bin + 1;
    end


    assign rptr_gray = (rptr_bin >> 1) ^ rptr_bin;


    assign wfull = (wptr_gray[PTR_WIDTH-1] != rptr_gray_sync_wr_2[PTR_WIDTH-1]) &&
                   (wptr_gray[PTR_WIDTH-2] != rptr_gray_sync_wr_2[PTR_WIDTH-2]) &&
                   (wptr_gray[PTR_WIDTH-3:0] == rptr_gray_sync_wr_2[PTR_WIDTH-3:0]);

    assign rempty = (rptr_gray == wptr_gray_sync_rd_2);


    dual_port_RAM #(
        .WIDTH(WIDTH),
        .DEPTH(DEPTH)
    ) ram (
        .wclk(wclk),
        .wenc(winc && !wfull),
        .waddr(wptr_bin[ADDR_WIDTH-1:0]),
        .wdata(wdata),
        .rclk(rclk),
        .renc(rinc && !rempty),
        .raddr(rptr_bin[ADDR_WIDTH-1:0]),
        .rdata(rdata)
    );

endmodule


module dual_port_RAM #(
    parameter WIDTH = 8,
    parameter DEPTH = 16
) (
    input wclk,
    input wenc,
    input [$clog2(DEPTH)-1:0] waddr,
    input [WIDTH-1:0] wdata,
    input rclk,
    input renc,
    input [$clog2(DEPTH)-1:0] raddr,
    output reg [WIDTH-1:0] rdata
);

    reg [WIDTH-1:0] RAM_MEM [0:DEPTH-1];


    always @(posedge wclk) begin
        if (wenc)
            RAM_MEM[waddr] <= wdata;
    end


    always @(posedge rclk) begin
        if (renc)
            rdata <= RAM_MEM[raddr];
    end

endmodule

