        stack_mem[0] <= 4'b0;
        stack_mem[1] <= 4'b0;
        stack_mem[2] <= 4'b0;
        stack_mem[3] <= 4'b0;
        data_reg <= 4'b0;
    end else if (EN) begin
        if (!FULL && !EMPTY) begin 
            if (RW == 0) begin 
                stack_mem[SP-1] <= dataIn;
                SP <= SP - 1;
            end else begin 
                data_reg <= stack_mem[SP];
                stack_mem[SP] <= 4'b0;
                SP <= SP + 1;
            end
        end
    end
end

