module traffic_light (
    input clk,
    input rst_n,
    input pass_request,
    output reg [7:0] clock,
    output reg red,
    output reg yellow,
    output reg green
);

parameter idle = 2'b00;
parameter s1_red = 2'b01;
parameter s2_yellow = 2'b10;
parameter s3_green = 2'b11;

reg [1:0] state;
reg [7:0] cnt;
reg p_red, p_yellow, p_green;


always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= idle;
    end else begin
        case (state)
            idle: state <= s1_red;
            s1_red: if (cnt == 0) state <= s3_green;
            s3_green: if (cnt == 0) state <= s2_yellow;
            s2_yellow: if (cnt == 0) state <= s1_red;
            default: state <= idle;
        endcase
    end
end


always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        cnt <= 10;
    end else begin
        if (pass_request && p_green) begin
            cnt <= 10;
        end else if (!p_green && cnt == 0) begin
            cnt <= 60;
        end else if (!p_yellow && cnt == 0) begin
            cnt <=5;
        end else if (!p_red && cnt ==0) begin
            cnt <=10;
        end else begin
            cnt <= cnt - 1;
        end
    end
end


always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        p_red <= 0;
        p_yellow <=0;
        p_green <=0;
    end else begin
        case (state)
            s1_red: begin
                p_red <= 1;
                p_yellow <=0;
                p_green <=0;
            end
            s3_green: begin
                p_red <=0;
                p_yellow <=0;
                p_green <=1;
            end
            s2_yellow: begin
                p_red <=0;
                p_yellow <=1;
                p_green <=0;
            end
            default: begin
                p_red <=0;
                p_yellow <=0;
                p_green <=0;
            end
        endcase
    end
end


always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        red <=0;
        yellow <=0;
        green <=0;
    end else begin
        red <= p_red;
        yellow <= p_yellow;
        green <= p_green;
    end
end

assign clock = cnt;

endmodule

