module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

    reg [1:0] state;
    reg [7:0] dividend_reg, divisor_reg;
    reg [7:0] quotient, remainder;
    reg [15:0] result_reg;
    reg [7:0] abs_dividend, abs_divisor;
    reg [7:0] NEG_DIVISOR;
    reg [3:0] cnt;
    reg [8:0] SR;

    reg original_sign_dividend, original_sign_divisor;
    reg quotient_sign, remainder_sign;

    localparam IDLE = 2'b00;
    localparam INIT = 2'b01;
    localparam DIVIDE = 2'b10;
    localparam ADJUST = 2'b11;

    function [7:0] abs_func(input [7:0] val, input sign);
        abs_func = sign ? (val[7] ? (~val + 1) : val) : val;
    endfunction

    function [7:0] adjust_sign(input [7:0] val, input sign);
        adjust_sign = sign ? (val[7] ? (~val + 1) : val) : val;
    endfunction

    always @(posedge clk) begin
        if (rst) begin
            state <= IDLE;
            res_valid <= 0;
            result <= 0;
            cnt <= 0;
            SR <= 0;
            quotient <= 0;
            remainder <= 0;
            dividend_reg <= 0;
            divisor_reg <= 0;
            abs_dividend <= 0;
            abs_divisor <= 0;
            NEG_DIVISOR <= 0;
            original_sign_dividend <= 0;
            original_sign_divisor <= 0;
            quotient_sign <= 0;
            remainder_sign <= 0;
        end else begin
            case (state)
                IDLE: begin
                    res_valid <= 0;
                    if (opn_valid) begin
                        dividend_reg <= dividend;
                        divisor_reg <= divisor;
                        state <= INIT;
                    end
                end
                INIT: begin
                    abs_dividend <= abs_func(dividend, sign);
                    abs_divisor <= abs_func(divisor, sign);
                    original_sign_dividend <= sign ? dividend[7] : 0;
                    original_sign_divisor <= sign ? divisor[7] : 0;
                    quotient_sign <= (original_sign_dividend ^ original_sign_divisor);
                    remainder_sign <= original_sign_dividend;
                    NEG_DIVISOR <= -abs_divisor;
                    SR <= {abs_dividend, 1'b0} << 1;

                    cnt <= 1;
                    state <= DIVIDE;
                end
                DIVIDE: begin
                    if (cnt == 8) begin
                        remainder <= SR[8:1];
                        quotient <= SR[0];
                        state <= ADJUST;
                    end else begin
                        temp = {SR[8:1], 1'b0} - NEG_DIVISOR;
                        if (temp[8]) begin 
                            SR <= {SR[8:1], 1'b0};
                        end else begin 
                            SR <= {temp, 1'b1};
                        end
                        cnt <= cnt + 1;
                    end
                end
                ADJUST: begin
                    if (sign) begin
                        quotient <= adjust_sign(quotient, quotient_sign);
                        remainder <= adjust_sign(remainder, remainder_sign);
                    end
                    result <= {remainder, quotient};
                    res_valid <= 1;
                    state <= IDLE;
                end
                default: state <= IDLE;
            endcase
        end
    end

endmodule

