    assign diff[0] = A[0] ^ B[0] ^ borrow[0];
    assign borrow[1] = (B[0] & borrow[0]) | (~A[0] & (B[0] ^ borrow[0]));


    assign diff[1] = A[1] ^ B[1] ^ borrow[1];
    assign borrow[2] = (B[1] & borrow[1]) | (~A[1] & (B[1] ^ borrow[1]));


    assign diff[2] = A[2] ^ B[2] ^ borrow[2];
    assign borrow[3] = (B[2] & borrow[2]) | (~A[2] & (B[2] ^ borrow[2]));


    assign diff[3] = A[3] ^ B[3] ^ borrow[3];
    assign borrow[4] = (B[3] & borrow[3]) | (~A[3] & (B[3] ^ borrow[3]));

