        for (i=0;
 i<8;
 i=i+1) begin: level1
            assign G1[i] = G_bits[2*i] | (P_bits[2*i] & G_bits[2*i+1]);
            assign P1[i] = P_bits[2*i] & P_bits[2*i+1];
        end
    endgenerate

