        sum_reg <= 0;
        cnt <= 0;
        valid_out <= 0;
        data_out <= 0;
    end else begin
        valid_out <= 0;

        if (valid_in) begin
            sum_reg <= sum_reg + data_in;
            cnt <= cnt + 1;
            if (cnt == 2'b11) begin 
