module fixed_point_adder #(
    parameter Q = 4,
    parameter N = 8
) (
    input [N-1:0] a,
    input [N-1:0] b,
    output [N-1:0] c
);

reg [N-1:0] res;

always @(*) begin
    reg sign_a, sign_b;
    reg [N-2:0] mag_a, mag_b;
    reg [N-1:0] sum_mag;
    reg [N-2:0] diff_mag;
    reg sign_res;
    integer max_mag;

    sign_a = a[N-1];
    sign_b = b[N-1];
    mag_a = a[N-2:0];
    mag_b = b[N-2:0];

    if (sign_a == sign_b) begin

        sum_mag = {1'b0, mag_a} + {1'b0, mag_b};

        max_mag = (1 << (N-1)) - 1;

        if (sum_mag > max_mag) begin

            res = {sign_a, {N-1{1'b1}}};
        end else begin
            res = {sign_a, sum_mag[N-2:0]};
        end
    end else begin

        if (mag_a > mag_b) begin
            diff_mag = mag_a - mag_b;
            sign_res = sign_a;
        end else if (mag_b > mag_a) begin
            diff_mag = mag_b - mag_a;
            sign_res = sign_b;
        end else begin

            diff_mag = {N-2{1'b0}};
            sign_res = 1'b0;
        end

        res = {sign_res, diff_mag};
    end
end

assign c = res;

endmodule

