wire [PTR_WIDTH-1:0] waddr_next = waddr_bin + 1;
wire waddr_inc = winc && !wfull;


reg [PTR_WIDTH-1:0] raddr_bin;
wire [PTR_WIDTH-1:0] raddr_next = raddr_bin + 1;
wire raddr_inc = rinc && !rempty;


wire [PTR_WIDTH-1:0] wptr_gray = waddr_bin ^ (waddr_bin >> 1);
wire [PTR_WIDTH-1:0] rptr_gray = raddr_bin ^ (raddr_bin >> 1);


reg [PTR_WIDTH-1:0] rptr_gray_sync1, rptr_gray_sync2;
always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) {rptr_gray_sync2, rptr_gray_sync1} <= 0;
    else {rptr_gray_sync2, rptr_gray_sync1} <= {rptr_gray_sync1, rptr_gray};
end


reg [PTR_WIDTH-1:0] wptr_gray_sync1, wptr_gray_sync2;
always @(posedge rclk or negedge rrstn) begin
    if (!rrstn) {wptr_gray_sync2, wptr_gray_sync1} <= 0;
    else {wptr_gray_sync2, wptr_gray_sync1} <= {wptr_gray_sync1, wptr_gray};
end


assign wfull  = (wptr_gray == {~rptr_gray_sync2[PTR_WIDTH-1 -: 2], rptr_gray_sync2[PTR_WIDTH-2:0]});
assign rempty = (rptr_gray == wptr_gray_sync2);


always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) waddr_bin <= 0;
    else if (waddr_inc) waddr_bin <= waddr_next;
