module LIFObuffer (
    input Clk,
    input EN,
    input Rst,
    input [3:0] dataIn,
    input RW,
    output reg EMPTY,
    output reg FULL,
    output reg [3:0] dataOut
);

reg [3:0] stack_mem [0:3];

reg [2:0] SP;


always @(posedge Clk) begin
    if (EN) begin
        if (Rst) begin

            SP <= 3'b0;

            stack_mem[0] <= 4'b0;
            stack_mem[1] <= 4'b0;
            stack_mem[2] <= 4'b0;
            stack_mem[3] <= 4'b0;
            EMPTY <= 1'b1;
            FULL <= 1'b0;
        end else begin
            if (!RW) begin 
                if (SP < 4) begin
                    stack_mem[SP] <= dataIn;

                    SP <= SP + 1;

                end
            end else begin 
                if (SP > 0) begin
                    dataOut <= stack_mem[SP-1];

                    stack_mem[SP-1] <= 4'b0;

                    SP <= SP - 1;

                end
            end
        end
    end
end


always @(*) begin
    EMPTY = (SP == 0);

    FULL = (SP == 4);

end

endmodule

