module traffic_light (
    input rst_n,
    input clk,
    input pass_request,
    output [7:0] clock,
    output red,
    output yellow,
    output green
);
    parameter idle = 2'b00;
    parameter s1_red = 2'b01;
    parameter s2_yellow = 2'b10;
    parameter s3_green = 2'b11;

    reg [1:0] state, next_state;
    reg [7:0] cnt;
    reg p_red, p_yellow, p_green;
    reg pass_request_prev;


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= idle;
            pass_request_prev <= 0;
        end else begin
            state <= next_state;
            pass_request_prev <= pass_request;
        end
    end


    always @(*) begin
        case (state)
            idle:    next_state = s1_red;
            s1_red:  next_state = (cnt == 0) ? s3_green : s1_red;
            s3_green: next_state = (cnt == 0) ? s2_yellow : s3_green;
            s2_yellow: next_state = (cnt == 0) ? s1_red : s2_yellow;
            default: next_state = idle;
        endcase
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cnt <= 10;
        end else begin
            case (state)
                s1_red: cnt <= (cnt == 0) ? 60 : cnt - 1;
                s3_green: begin
                    if (pass_request && !pass_request_prev && cnt > 10)
                        cnt <= 10;
                    else if (cnt == 0)
                        cnt <= 5;
                    else
                        cnt <= cnt - 1;
                end
                s2_yellow: cnt <= (cnt == 0) ? 10 : cnt - 1;
                default: cnt <= 10;
            endcase
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            {p_red, p_yellow, p_green} <= 3'b000;
        end else begin
            case (state)
                s1_red:    {p_red, p_yellow, p_green} <= 3'b100;
                s2_yellow: {p_red, p_yellow, p_green} <= 3'b010;
                s3_green:  {p_red, p_yellow, p_green} <= 3'b001;
                default:   {p_red, p_yellow, p_green} <= 3'b000;
            endcase
        end
    end

    assign red = p_red;
    assign yellow = p_yellow;
    assign green = p_green;
    assign clock = cnt;

endmodule

