module alu (
    input [31:0] a,
    input [31:0] b,
    input [5:0] aluc,
    output reg [31:0] r,
    output reg carry,
    output reg overflow,
    output zero,
    output negative,
    output flag
);


parameter ADD  = 6'b100000;
parameter ADDU = 6'b100001;
parameter SUB  = 6'b100010;
parameter SUBU = 6'b100011;
parameter AND  = 6'b100100;
parameter OR   = 6'b100101;
parameter XOR  = 6'b100110;
parameter NOR  = 6'b100111;
parameter SLT  = 6'b101010;
parameter SLTU = 6'b101011;
parameter SLL  = 6'b000000;
parameter SRL  = 6'b000010;
parameter SRA  = 6'b000011;
parameter SLLV = 6'b000100;
parameter SRLV = 6'b000110;
parameter SRAV = 6'b000111;
parameter LUI  = 6'b001111;


reg [32:0] sum, diff;



always @(*) begin
    case (aluc)
        ADD: begin
            {carry, r} = {1'b0, a} + {1'b0, b};
            overflow = (a[31] == b[31]) && (r[31] != a[31]);
        end
        ADDU: begin
            {carry, r} = {1'b0, a} + {1'b0, b};
            overflow = 0;
        end
        SUB: begin
            {carry, r} = {1'b0, a} - {1'b0, b};
            overflow = (a[31] != b[31]) && (r[31] != a[31]);
        end
        SUBU: begin
            {carry, r} = {1'b0, a} - {1'b0, b};
            overflow = 0;
        end
        AND: begin
            r = a & b;
            carry = 0;
            overflow = 0;
        end
        OR: begin
            r = a | b;
            carry = 0;
            overflow = 0;
        end
        XOR: begin
            r = a ^ b;
            carry = 0;
            overflow = 0;
        end
        NOR: begin
            r = ~(a | b);
            carry = 0;
            overflow = 0;
        end
        SLT: begin
            r = ($signed(a) < $signed(b)) ? 32'd1 : 32'd0;
            carry = 0;
            overflow = 0;
        end
        SLTU: begin
            r = (a < b) ? 32'd1 : 32'd0;
            carry = 0;
            overflow = 0;
        end
        SLL: begin
            r = b << a[4:0];
            carry = 0;
            overflow = 0;
        end
        SRL: begin
            r = b >> a[4:0];
            carry = 0;
            overflow = 0;
        end
        SRA: begin
            r = $signed(b) >>> a[4:0];
            carry = 0;
            overflow = 0;
        end
        SLLV: begin
            r = b << a[4:0];
            carry = 0;
            overflow = 0;
        end
        SRLV: begin
            r = b >> a[4:0];
            carry = 0;
            overflow = 0;
        end
        SRAV: begin
            r = $signed(b) >>> a[4:0];
            carry = 0;
            overflow = 0;
        end
        LUI: begin
            r = {b[15:0], 16'b0};
            carry = 0;
            overflow = 0;
        end
        default: begin
            r = 32'bz;
            carry = 0;
            overflow = 0;
        end
    endcase
end


assign zero = (r == 32'b0) ? 1'b1 : 1'b0;


assign negative = r[31];


assign flag = (aluc == SLT || aluc == SLTU) ? r[0] : 1'bz;

endmodule

