module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

reg [15:0] shift_reg;
reg [7:0] absolute_divisor;
reg [7:0] absolute_dividend;
reg [3:0] cnt;
reg [1:0] state;

reg dividend_sign;
reg divisor_sign;
reg quotient_sign;
reg remainder_sign;

localparam IDLE = 0;
localparam DIVIDE = 1;
localparam DONE = 2;

wire [15:0] next_shift_reg;
wire [7:0] new_remainder;
wire [7:0] new_quotient;
wire subtract;


assign subtract = (shift_reg[15:8] >= absolute_divisor);

assign new_remainder = subtract ? (shift_reg[15:8] - absolute_divisor) : shift_reg[15:8];
assign new_quotient = (shift_reg[7:0] << 1) | subtract;

assign next_shift_reg = {new_remainder, new_quotient};

always @(posedge clk) begin
    if (rst) begin
        state <= IDLE;
        res_valid <= 0;
        shift_reg <= 0;
        cnt <= 0;
        absolute_dividend <= 0;
        absolute_divisor <= 0;
        dividend_sign <= 0;
        divisor_sign <= 0;
    end else begin
        case (state)
            IDLE: begin
                if (opn_valid && !res_valid) begin

                    dividend_sign <= sign ? dividend[7] : 1'b0;
                    divisor_sign <= sign ? divisor[7] : 1'b0;


                    if (sign) begin
                        absolute_dividend <= dividend[7] ? -dividend : dividend;
                        absolute_divisor <= divisor[7] ? -divisor : divisor;
                    end else begin
                        absolute_dividend <= dividend;
                        absolute_divisor <= divisor;
                    end

                    shift_reg <= {8'b0, absolute_dividend};
                    cnt <= 0;
                    state <= DIVIDE;
                    res_valid <= 0;
                end
            end
            DIVIDE: begin
                if (cnt < 8) begin

                    shift_reg <= next_shift_reg;
                    cnt <= cnt + 1;
                end else begin


                    quotient_sign <= dividend_sign ^ divisor_sign;
                    remainder_sign <= dividend_sign;


                    if (remainder_sign) begin
                        result[15:8] <= ~shift_reg[15:8] + 1'b1;
                    end else begin
                        result[15:8] <= shift_reg[15:8];
                    end

                    if (quotient_sign) begin
                        result[7:0] <= ~next_shift_reg[7:0] + 1'b1;
                    end else begin
                        result[7:0] <= next_shift_reg[7:0];
                    end

                    res_valid <= 1;
                    state <= DONE;
                end
            end
            DONE: begin
                res_valid <= 0;
                state <= IDLE;
            end
        endcase
    end
end

endmodule

