module div_16bit (
    input [15:0] A,
    input [7:0] B,
    output reg [15:0] result = 0,
    output reg [15:0] odd = 0
);

reg [7:0] a_reg, b_reg;


always @(*) begin
    a_reg = A;
    b_reg = B;
end


always @(*) begin
    integer i;
    reg [8:0] remainder;

    reg [15:0] quotient;
    reg [15:0] dividend;

    dividend = a_reg;
    remainder = 9'b0;
    quotient = 16'b0;

    for (i = 0;
 i < 16;
 i = i + 1) begin
        reg [8:0] current_bit;
        current_bit = {remainder[7:0], dividend[15 - i]};

        if (current_bit >= {1'b0, b_reg}) begin
            remainder = current_bit - {1'b0, b_reg};
            quotient[15 - i] = 1'b1;
        end else begin
            quotient[15 - i] = 1'b0;
        end
    end


    odd = {8'b0, remainder};
    result = quotient;
end

endmodule

