  assign C1 = G_i[1] | (P_i[1] & Cin);
  assign C2 = G_i[2] | (P_i[2] & G_i[1]) | (P_i[2] & P_i[1] & Cin);
  assign C3 = G_i[3] | (P_i[3] & G_i[2]) | (P_i[3] & P_i[2] & G_i[1]) | (P_i[3] & P_i[2] & P_i[1] & Cin);
  assign Cout = G_i[4] | (P_i[4] & G_i[3]) | (P_i[4] & P_i[3] & G_i[2]) | (P_i[4] & P_i[3] & P_i[2] & G_i[1]) | (P_i[4] & P_i[3] & P_i[2] & P_i[1] & Cin);

  assign S[1] = P_i[1] ^ Cin;
  assign S[2] = P_i[2] ^ C1;
  assign S[3] = P_i[3] ^ C2;
  assign S[4] = P_i[4] ^ C3;

  assign G = G_i[4] | (P_i[4] & G_i[3]) | (P_i[4] & P_i[3] & G_i[2]) | (P_i[4] & P_i[3] & P_i[2] & G_i[1]);
