reg [9:0] accumulator;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        counter <= 2'b0;
        accumulator <= 10'b0;
        valid_out <= 1'b0;
        data_out <= 10'b0;
    end else begin
        valid_out <= 1'b0;

        if (valid_in) begin
            if (counter < 2'b11) begin
                accumulator <= accumulator + data_in;
                counter <= counter + 1'b1;
            end else begin
                accumulator <= 10'b0;
                data_out <= accumulator + data_in;
                valid_out <= 1'b1;
                counter <= 2'b0;
            end
        end
    end
end

endmodule

