module fixed_point_adder #(
    parameter Q = 4,
    parameter N = 8
) (
    input [N-1:0] a,
    input [N-1:0] b,
    output [N-1:0] c
);

    reg [N-1:0] res;

    always @* begin
        if (a[N-1] == b[N-1]) begin

            reg [N-1:0] a_abs, b_abs, sum_abs;
            a_abs = a[N-1] ? -a : a;
            b_abs = a[N-1] ? -b : b;
            sum_abs = a_abs + b_abs;


            if (sum_abs[N-1]) begin
                res = {1'b0, {(N-1){1'b1}}};

            end else begin
                res = sum_abs;
            end
        end else begin

            reg [N-1:0] a_abs, b_abs, diff;
            a_abs = a[N-1] ? -a : a;
            b_abs = a[N-1] ? -b : b;

            if (a_abs >= b_abs) begin
                diff = a_abs - b_abs;
                res = {1'b0, diff[N-2:0]};

            end else begin
                diff = b_abs - a_abs;
                res = {1'b0, diff[N-2:0]};
            end
        end
    end

    assign c = res;

endmodule

