module fixed_point_subtractor #(parameter Q=4, N=8) (
    input [N-1:0] a,
    input [N-1:0] b,
    output reg [N-1:0] c
);

    reg sign_a, sign_b;
    reg [N-2:0] magnitude_a, magnitude_b;
    reg [N-2:0] result_mag;
    reg result_sign;

    always @(*) begin
        sign_a = a[N-1];
        sign_b = b[N-1];
        magnitude_a = a[N-2:0];
        magnitude_b = b[N-2:0];

        if (sign_a == sign_b) begin

            reg signed [N-1:0] signed_diff;
            signed_diff = {1'b0, magnitude_a} - {1'b0, magnitude_b};
            if (signed_diff < 0) begin
                result_sign = sign_a;
                result_mag = -signed_diff[N-2:0];
            end else begin
                result_sign = sign_a;
                result_mag = signed_diff[N-2:0];
            end
        end else begin

            if (magnitude_a > magnitude_b) begin
                result_sign = sign_a;
                result_mag = magnitude_a - magnitude_b;
            end else if (magnitude_b > magnitude_a) begin
                result_sign = sign_b;
                result_mag = magnitude_b - magnitude_a;
            end else begin
                result_sign = 0;
                result_mag = 0;
            end
        end


        c = {result_sign, result_mag};


        if (result_mag == 0 && result_sign == 0)
            c = {1'b0, {N-1{1'b0}}};
    end

endmodule

