    wire a_is_nan, b_is_nan, a_is_inf, b_is_inf, a_is_zero, b_is_zero;


    reg [5:0] lz;

    always @(posedge clk) begin
        if (rst) begin
            counter <= 3'b0;
            z <= 32'b0;
        end else begin
            case (counter)
                3'b000: begin

                    a_sign <= a[31];
                    b_sign <= b[31];
                    a_exp <= a[30:23];
                    b_exp <= b[30:23];
                    a_mant <= (a[30:23] == 8'b0) ? {1'b0, a[22:0]} : {1'b1, a[22:0]};
                    b_mant <= (b[30:23] == 8'b0) ? {1'b0, b[22:0]} : {1'b1, b[22:0]};


                    a_is_nan <= (a[30:23] == 8'hff) && (a[22:0] != 0);
                    b_is_nan <= (b[30:23] == 8'hff) && (b[22:0] != 0);
                    a_is_inf <= (a[30:23] == 8'hff) && (a[22:0] == 0);
                    b_is_inf <= (b[30:23] == 8'hff) && (b[22:0] == 0);
                    a_is_zero <= (a[30:23] == 0) && (a[22:0] == 0);
                    b_is_zero <= (b[30:23] == 0) && (b[22:0] == 0);

                    if (a_is_nan || b_is_nan) begin
                        z <= {a_sign ^ b_sign, 8'hff, 23'h1};

                        counter <= 3'b000;
                    end else if (a_is_inf && b_is_zero) begin
                        z <= {a_sign ^ b_sign, 8'hff, 23'h1};

                        counter <= 3'b000;
                    end else if (b_is_inf && a_is_zero) begin
                        z <= {a_sign ^ b_sign, 8'hff, 23'h1};

                        counter <= 3'b000;
                    end else if (a_is_inf || b_is_inf) begin
                        if (a_is_inf) begin
                            z <= {a_sign, 8'hff, 23'h0};

                        end else begin
                            z <= {b_sign, 8'hff, 23'h0};

                        end
                        counter <= 3'b000;
                    end else if (a_is_zero || b_is_zero) begin
                        z <= {a_sign ^ b_sign, 31'h0};

                        counter <= 3'b000;
                    end else begin
                        product <= a_mant * b_mant;
                        counter <= 3'b001;
                    end
