                3'b001: begin

                    lz <= 0;
                    if (product[47]) begin
                        lz <= 47;
                    end else if (product[46]) begin
                        lz <= 46;
                    end else if (product[45]) begin
                        lz <= 45;

                    end




                    counter <= 3'b010;
                end


            endcase
        end
    end

