module asyn_fifo #(
    parameter WIDTH = 8,
    parameter DEPTH = 16
) (
    input wire wclk,
    input wire rclk,
    input wire wrstn,
    input wire rrstn,
    input wire winc,
    input wire rinc,
    input wire [WIDTH-1:0] wdata,
    output reg rempty,
    output reg wfull,
    output wire [WIDTH-1:0] rdata
);

    localparam ADDR_BITS = $clog2(DEPTH);
    localparam PTR_BITS = ADDR_BITS + 1;

    function [PTR_BITS-1:0] bin2gray(input [PTR_BITS-1:0] bin);
        bin2gray = bin ^ (bin >> 1);
    endfunction

    function [PTR_BITS-1:0] gray2bin(input [PTR_BITS-1:0] gray);
        reg [PTR_BITS-1:0] bin;
        integer i;
        begin
            bin[PTR_BITS-1] = gray[PTR_BITS-1];
            for (i = PTR_BITS-2;
 i >= 0;
 i = i - 1)
                bin[i] = bin[i+1] ^ gray[i];
            gray2bin = bin;
        end
    endfunction

    reg [PTR_BITS-1:0] wptr_bin, rptr_bin;
    wire [ADDR_BITS-1:0] waddr_bin = wptr_bin[ADDR_BITS-1:0];
    wire [ADDR_BITS-1:0] raddr_bin = rptr_bin[ADDR_BITS-1:0];


    wire winc_valid = winc && !wfull;
    reg [PTR_BITS-1:0] wptr_bin_next = wptr_bin + winc_valid;

    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn) begin
            wptr_bin <= 0;
        end else begin
            wptr_bin <= winc_valid ? wptr_bin_next : wptr_bin;
        end
    end


    wire rinc_valid = rinc && !rempty;
    reg [PTR_BITS-1:0] rptr_bin_next = rptr_bin + rinc_valid;

    always @(posedge rclk or negedge rrstn) begin
        if (!rrstn) begin
            rptr_bin <= 0;
        end else begin
            rptr_bin <= rinc_valid ? rptr_bin_next : rptr_bin;
        end
    end


    wire [PTR_BITS-1:0] wptr_gray = bin2gray(wptr_bin);
    wire [PTR_BITS-1:0] rptr_gray = bin2gray(rptr_bin);


    reg [PTR_BITS-1:0] rptr_gray_sync0, rptr_gray_sync;
    reg [PTR_BITS-1:0] wptr_gray_sync0, wptr_gray_sync;


    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn) begin
            rptr_gray_sync0 <= 0;
            rptr_gray_sync <= 0;
        end else begin
            rptr_gray_sync0 <= rptr_gray;
            rptr_gray_sync <= rptr_gray_sync0;
        end
    end


    always @(posedge rclk or negedge rrstn) begin
        if (!rrstn) begin
            wptr_gray_sync0 <= 0;
            wptr_gray_sync <= 0;
        end else begin
            wptr_gray_sync0 <= wptr_gray;
            wptr_gray_sync <= wptr_gray_sync0;
        end
    end


    wire [PTR_BITS-1:0] rptr_bin_sync = gray2bin(rptr_gray_sync);
    wire [PTR_BITS-1:0] wptr_bin_sync = gray2bin(wptr_gray_sync);


    wire full_cond = (wptr_bin - rptr_bin_sync) >= DEPTH;
    wire empty_cond = (rptr_bin == wptr_bin_sync);


    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn) begin
            wfull <= 0;
        end else begin
            wfull <= full_cond;
        end
    end

    always @(posedge rclk or negedge rrstn) begin
        if (!rrstn) begin
            rempty <= 1;
        end else begin
            rempty <= empty_cond;
        end
    end


    dual_port_RAM #(.DEPTH(DEPTH), .WIDTH(WIDTH)) ram (
        .wclk(wclk),
        .wenc(winc_valid),
        .waddr(waddr_bin),
        .wdata(wdata),
        .rclk(rclk),
        .renc(rinc_valid),
        .raddr(raddr_bin),
        .rdata(rdata)
    );

endmodule

