module LIFObuffer (
    input wire [3:0] dataIn,
    input wire RW,
    input wire EN,
    input wire Rst,
    input wire Clk,
    output wire EMPTY,
    output wire FULL,
    output wire [3:0] dataOut
);

reg [3:0] stack [0:3];

reg [3:0] sp = 0;

reg [3:0] dataOut_reg;



assign EMPTY = (sp == 0);
assign FULL = (sp == 4);
assign dataOut = dataOut_reg;

integer i;

always @(posedge Clk) begin
    if (Rst) begin

        sp <= 0;
        dataOut_reg <= 0;
        for (i = 0;
 i < 4;
 i = i + 1) begin
            stack[i] <= 0;
        end
    end else if (EN) begin
        if (RW) begin 
            if (sp > 0) begin
                dataOut_reg <= stack[sp - 1];

