module traffic_light (
    input  rst_n,
    input  clk,
    input  pass_request,
    output reg [7:0] clock,
    output red,
    output yellow,
    output green
);

    parameter idle     = 2'b00;
    parameter s1_red   = 2'b01;
    parameter s2_yellow= 2'b10;
    parameter s3_green = 2'b11;

    reg [1:0] state;
    reg [7:0] cnt;
    reg p_red, p_yellow, p_green;


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= idle;
        end else begin
            case (state)
                idle:     state <= s1_red;
                s1_red:   if (cnt == 0) state <= s3_green;
                s3_green: if (cnt == 0) state <= s2_yellow;
                s2_yellow:if (cnt == 0) state <= s1_red;
                default:  state <= idle;
            endcase
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cnt <= 8'd10;
        end else begin

            if (pass_request && (state == s3_green) && (cnt > 8'd10)) begin
                cnt <= 8'd10;
            end else begin

                case (state)
                    idle:     cnt <= 8'd10;
                    s1_red:   cnt <= 8'd3;
                    s3_green: cnt <= 8'd60;
                    s2_yellow:cnt <= 8'd5;
                    default:  cnt <= 8'd10;
                endcase
            end
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            p_red     <= 1'b0;
            p_yellow  <= 1'b0;
            p_green   <= 1'b0;
        end else begin
            p_red     <= (state == s1_red) ? 1'b1 : 1'b0;
            p_yellow  <= (state == s2_yellow) ? 1'b1 : 1'b0;
            p_green   <= (state == s3_green) ? 1'b1 : 1'b0;
        end
    end

    assign clock = cnt;
    assign red = p_red;
    assign yellow = p_yellow;
    assign green = p_green;

endmodule

