module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

    reg [15:0] SR;

    reg [3:0] counter;
    reg in_progress;

    reg [7:0] absolute_dividend;
    reg [7:0] absolute_divisor;
    reg sign_quotient;
    reg sign_remainder;

    always @(posedge clk) begin
        if (rst) begin
            SR <= 16'b0;
            counter <= 0;
            in_progress <= 0;
            res_valid <= 0;
            result <= 16'b0;
            absolute_dividend <= 0;
            absolute_divisor <= 0;
            sign_quotient <= 0;
            sign_remainder <= 0;
        end else begin
            if (in_progress) begin
                if (counter < 8) begin

                    reg [7:0] temp_remainder = {SR[15:8][6:0], SR[7]};
                    reg [7:0] temp_remainder_sub = temp_remainder - absolute_divisor;

                    if (temp_remainder_sub[7] == 0) begin

                        SR <= {temp_remainder_sub, {SR[7:1], 1'b1}};
                    end else begin

                        SR <= {temp_remainder, {SR[7:1], 1'b0}};
                    end

                    counter <= counter + 1;
                end else begin

                    in_progress <= 0;
                    res_valid <= 1;

                    if (sign) begin
                        reg [7:0] final_remainder = (sign_remainder) ? -SR[15:8] : SR[15:8];
                        reg [7:0] final_quotient = (sign_quotient) ? -SR[7:0] : SR[7:0];
                        result <= {final_remainder, final_quotient};
                    end else begin
                        result <= {SR[15:8], SR[7:0]};
                    end
                end
            end else if (opn_valid && !res_valid) begin

                if (sign) begin

                    reg sign_dividend = dividend[7];
                    reg sign_divisor = divisor[7];
                    absolute_dividend = (sign_dividend) ? (~dividend + 1) : dividend;
                    absolute_divisor = (sign_divisor) ? (~divisor + 1) : divisor;
                    sign_quotient = sign_dividend ^ sign_divisor;
                    sign_remainder = sign_dividend;
                end else begin
                    absolute_dividend = dividend;
                    absolute_divisor = divisor;
                    sign_quotient = 0;
                    sign_remainder = 0;
                end


                SR <= {8'b0, absolute_dividend};
                counter <= 0;
                in_progress <= 1;
            end else begin
                res_valid <= 0;
            end
        end
    end

endmodule

