    output [4:1] S,
    output G,
    output P
);
    wire [4:1] G_i, P_i;
    wire C1, C2, C3, C4;

    assign G_i[1] = A[1] & B[1];
    assign P_i[1] = A[1] ^ B[1];
    assign G_i[2] = A[2] & B[2];
    assign P_i[2] = A[2] ^ B[2];
    assign G_i[3] = A[3] & B[3];
    assign P_i[3] = A[3] ^ B[3];
