module accu (
    input clk,
    input rst_n,
    input [7:0] data_in,
    input valid_in,
    output reg valid_out,
    output [9:0] data_out
);

    reg [7:0] buffer0;
    reg [7:0] buffer1;
    reg [7:0] buffer2;
    reg [7:0] buffer3;
    reg [1:0] count;
    reg [9:0] sum;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            buffer0 <= 8'b0;
            buffer1 <= 8'b0;
            buffer2 <= 8'b0;
            buffer3 <= 8'b0;
            count <= 2'b00;
            sum <= 10'b0;
            valid_out <= 1'b0;
        end else begin
            valid_out <= 1'b0;
            if (valid_in) begin
                case (count)
                    2'b00: begin
                        buffer0 <= data_in;
                        count <= count + 1;
                    end
                    2'b01: begin
                        buffer1 <= data_in;
                        count <= count + 1;
                    end
                    2'b10: begin
                        buffer2 <= data_in;
                        count <= count + 1;
                    end
                    2'b11: begin
                        buffer3 <= data_in;
                        sum <= buffer0 + buffer1 + buffer2 + data_in;
                        valid_out <= 1'b1;
                        count <= 2'b00;
                    end
                endcase
            end
        end
    end

    assign data_out = sum;

endmodule

