module fixed_point_adder #(
    parameter Q = 4,  
    parameter N = 8   
) (
    input [N-1:0] a,
    input [N-1:0] b,
    output reg [N-1:0] c
);

    reg sign_a, sign_b;
    reg [N-1:0] abs_a, abs_b;
    reg [N-1:0] larger_abs, smaller_abs;
    reg [N-1:0] diff;
    reg sign_res;

    always @(*) begin
        sign_a = a[N-1];
        sign_b = b[N-1];


        abs_a = sign_a ? (~a + 1) : a;
        abs_b = sign_b ? (~b + 1) : b;


        if (abs_a > abs_b) begin
            larger_abs = abs_a;
            smaller_abs = abs_b;
            sign_res = sign_a;
        end else if (abs_b > abs_a) begin
            larger_abs = abs_b;
            smaller_abs = abs_a;
            sign_res = sign_b;
        end else begin
            larger_abs = abs_a;
            smaller_abs = abs_b;
            sign_res = 1'b0;

        end


        if (sign_a == sign_b) begin
            c = a + b;

        end else begin
            diff = larger_abs - smaller_abs;

            if (diff == 0) sign_res = 1'b0;
            c = {sign_res, diff[N-2:0]};
        end
    end

endmodule

