module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);

reg [2:0] counter;
reg a_sign, b_sign;
reg [7:0] a_exp, b_exp;
reg [22:0] a_man, b_man;
reg [23:0] a_mantissa, b_mantissa;
reg [47:0] product;
reg [9:0] exp_sum;
reg sign;
reg [22:0] round_man;
reg guard_bit, round_bit, sticky;
reg [23:0] z_mantissa;
reg [7:0] z_exp;

always @(posedge clk) begin
    if (rst) begin
        counter <= 0;
        z <= 0;
    end else begin
        case (counter)
            0: begin
                a_sign <= a[31];
                b_sign <= b[31];
                a_exp <= a[30:23];
                b_exp <= b[30:23];
                a_man <= a[22:0];
                b_man <= b[22:0];
                a_mantissa <= {1'b1, a_man};
                b_mantissa <= {1'b1, b_man};


                if (a_exp == 8'hff || b_exp == 8'hff) begin
                    if ((a_exp == 8'hff && b_exp == 8'hff) || (a_exp == 8'hff && a_man != 0) || (b_exp == 8'hff && b_man != 0)) begin
                        z <= {1'b0, 8'hff, 23'h1};

                    end else if ((a_exp == 8'hff && b_exp == 0 && b_man == 0) || (b_exp == 8'hff && a_exp == 0 && a_man == 0)) begin
                        z <= {1'b0, 8'hff, 23'h1};

                    end else if (a_exp == 8'hff && b_exp == 0 && b_man == 0) begin
                        z <= {a_sign ^ b_sign, 8'hff, 23'h0};

                    end else begin
                        z <= {a_sign ^ b_sign, a_exp == 8'hff ? 8'hff : b_exp == 8'hff ? 8'hff : 8'h0, 23'h0};

                    end
                    counter <= 7;
                end else if ((a_exp == 0 && a_man == 0) || (b_exp == 0 && b_man == 0)) begin
                    z <= {a_sign ^ b_sign, 31'h0};

                    counter <= 7;
                end else begin
                    counter <= 1;
                end
            end
            1: begin
                product <= a_mantissa * b_mantissa;
                counter <= 2;
            end
            2: begin

                if (product[47]) begin
                    z_mantissa <= product[46:24];
                    exp_sum <= a_exp + b_exp - 8'd127;
                    {guard_bit, round_bit, sticky} = {product[23], product[22], |product[21:0]};
                end else if (product[46]) begin
                    product = product >> 1;
                    z_mantissa <= product[45:23];
                    exp_sum <= a_exp + b_exp - 8'd127 + 1;
                    {guard_bit, round_bit, sticky} = {product[23], product[22], |product[21:0]};
                end else begin
                    product = product >> 2;
                    z_mantissa <= product[44:22];
                    exp_sum <= a_exp + b_exp - 8'd127 + 2;
                    {guard_bit, round_bit, sticky} = {product[23], product[22], |product[21:0]};
                end
                counter <= 3;
            end
            3: begin

                round_man = z_mantissa + guard_bit && (round_bit || sticky || (z_mantissa[0] ^ z_mantissa[1]));
                if (round_man[23]) begin
                    z_mantissa = round_man[23:1];
                    exp_sum <= exp_sum + 1;
                end else begin
                    z_mantissa = round_man[22:0];
                end
                counter <= 4;
            end
            4: begin

                if (exp_sum >= 8'hff) begin
                    z <= {sign, 8'hff, 23'h0};

                end else if (exp_sum <= 0) begin
                    z <= {sign, 31'h0};

                end else begin
                    z <= {sign, exp_sum, z_mantissa[22:0]};
                end
                counter <= 7;
            end
            default: counter <= 0;
        endcase
    end
end

endmodule

