module asyn_fifo #(
    parameter WIDTH = 8,
    parameter DEPTH = 16
) (
    input wclk,
    input wrstn,
    input rclk,
    input rrstn,
    input winc,
    input rinc,
    input [WIDTH-1:0] wdata,
    output rempty,
    output wfull,
    output [WIDTH-1:0] rdata
);

localparam ADDR_WIDTH = $clog2(DEPTH);
localparam PTR_WIDTH = ADDR_WIDTH + 1;


reg [PTR_WIDTH-1:0] wptr_bin, rptr_bin;


function [PTR_WIDTH-1:0] bin2gray(input [PTR_WIDTH-1:0] bin);
    bin2gray = bin ^ (bin >> 1);
endfunction

wire [PTR_WIDTH-1:0] wgray = bin2gray(wptr_bin);
wire [PTR_WIDTH-1:0] rgray = bin2gray(rptr_bin);


reg [PTR_WIDTH-1:0] wgray_sync1, wgray_sync2;
reg [PTR_WIDTH-1:0] rgray_sync1, rgray_sync2;


always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) wptr_bin <= 0;
    else if (winc && !wfull) wptr_bin <= wptr_bin + 1;
end


always @(posedge rclk or negedge rrstn) begin
    if (!rrstn) rptr_bin <= 0;
    else if (rinc && !rempty) rptr_bin <= rptr_bin + 1;
end



always @(posedge rclk or negedge rrstn) begin
    if (!rrstn) begin
        wgray_sync1 <= 0;
        wgray_sync2 <= 0;
    end else begin
        wgray_sync1 <= wgray;
        wgray_sync2 <= wgray_sync1;
    end
end


always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) begin
        rgray_sync1 <= 0;
        rgray_sync2 <= 0;
    end else begin
        rgray_sync1 <= rgray;
        rgray_sync2 <= rgray_sync1;
    end
end


assign wfull = (wgray == {~rgray_sync2[PTR_WIDTH-1], rgray_sync2[PTR_WIDTH-2:0]});
assign rempty = (rgray == wgray_sync2);


dual_port_RAM #(
    .WIDTH(WIDTH),
    .DEPTH(DEPTH)
) ram (
    .wclk(wclk),
    .wenc(winc && !wfull),
    .waddr(wptr_bin[ADDR_WIDTH-1:0]),
    .wdata(wdata),
    .rclk(rclk),
    .renc(rinc && !rempty),
    .raddr(rptr_bin[ADDR_WIDTH-1:0]),
    .rdata(rdata)
);

endmodule


