module pulse_detect (
    input clk,
    input rst_n,
    input data_in,
    output reg data_out
);


    localparam STATE0 = 2'b00;
    localparam STATE1 = 2'b01;
    localparam STATE2 = 2'b10;

    reg [1:0] current_state, next_state;


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            current_state <= STATE0;
            data_out <= 0;
        end else begin
            current_state <= next_state;
            data_out <= (next_state == STATE2) ? 1 : 0;
        end
    end


    always @(*) begin
        case (current_state)
            STATE0: begin
                next_state = data_in ? STATE1 : STATE0;
            end
            STATE1: begin
                next_state = data_in ? STATE1 : STATE2;
            end
            STATE2: begin
                next_state = STATE0;
            end
            default: next_state = STATE0;
        endcase
    end

endmodule

