module traffic_light (
    input rst_n,
    input clk,
    input pass_request,
    output reg [7:0] clock,
    output reg red,
    output reg yellow,
    output reg green
);

    parameter idle = 0;
    parameter s1_red = 1;
    parameter s2_yellow = 2;
    parameter s3_green = 3;

    reg [1:0] state, next_state;
    reg [7:0] counter;


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= idle;
            red <= 0;
            yellow <= 0;
            green <= 0;
        end else begin
            case (state)
                idle: begin
                    state <= s1_red;
                    red <= 1;
                    green <= 0;
                    yellow <= 0;
                    counter <= 10;
                end
                s1_red: begin
                    if (counter == 0) begin
                        state <= s3_green;
                        red <= 0;
                        green <= 1;
                        counter <= 60;
                    end else begin
                        counter <= counter - 1;
                    end
                end
                s3_green: begin
                    if (pass_request && green && (counter > 10)) begin
                        counter <= 10;
                    end
                    if (counter == 0) begin
                        state <= s2_yellow;
                        green <= 0;
                        yellow <= 1;
                        counter <= 5;
                    end else begin
                        counter <= counter - 1;
                    end
                end
                s2_yellow: begin
                    if (counter == 0) begin
                        state <= s1_red;
                        yellow <= 0;
                        red <= 1;
                        counter <= 10;
                    end else begin
                        counter <= counter - 1;
                    end
                end
                default: begin
                    state <= idle;
                    red <= 0;
                    green <= 0;
                    yellow <= 0;
                end
            endcase
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) clock <= 10;
        else clock <= counter;
    end

endmodule

