        if (!rst_n) begin
            data_lock <= 8'b0;
            has_data <= 1'b0;
            data_combo <= 16'b0;
            valid_combo <= 1'b0;
            data_out <= 16'b0;
            valid_out <= 1'b0;
        end else begin
            if (has_data) begin
                if (valid_in) begin
                    data_combo <= {data_lock, data_in};
                    valid_combo <= 1'b1;
                    has_data <= 1'b0;
                end else begin
                    valid_combo <= 1'b0;
                end
            end else begin
                if (valid_in) begin
                    data_lock <= data_in;
                    has_data <= 1'b1;
                    valid_combo <= 1'b0;
                end
            end
            data_out <= data_combo;
            valid_out <= valid_combo;
        end
    end

