module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid = 0,
    output reg [15:0] result = 0
);

    reg [1:0] state;
    localparam IDLE = 2'b00;
    localparam CAPTURE = 2'b01;
    localparam DIVIDE = 2'b10;
    localparam DONE = 2'b11;

    reg [7:0] abs_dividend, abs_divisor;
    reg [7:0] neg_divisor;
    reg [7:0] quo_reg;
    reg [7:0] rem_reg;
    reg [3:0] cnt;
    reg [16:0] SR;

    reg quo_sign, rem_sign;

    always @(posedge clk) begin
        if (rst) begin
            state <= IDLE;
            res_valid <= 0;
            result <= 0;
            cnt <= 0;
            SR <= 0;
            abs_dividend <= 0;
            abs_divisor <= 0;
            quo_sign <= 0;
            rem_sign <= 0;
            neg_divisor <= 0;
            quo_reg <= 0;
            rem_reg <= 0;
        end else begin
            case (state)
                IDLE: begin
                    res_valid <= 0;
                    if (opn_valid && !res_valid) begin
                        state <= CAPTURE;
                    end
                end
                CAPTURE: begin

                    if (sign) begin
                        abs_dividend = dividend[7] ? -dividend : dividend;
                        abs_divisor = divisor[7] ? -divisor : divisor;
                        quo_sign = dividend[7] ^ divisor[7];
                        rem_sign = dividend[7];
                    end else begin
                        abs_dividend = dividend;
                        abs_divisor = divisor;
                        quo_sign = 0;
                        rem_sign = 0;
                    end

                    if (abs_divisor == 0) begin 
                        result <= {8'hFF, 8'hFF};
                        state <= DONE;
                    end else begin

                        SR <= {9'b0, abs_dividend, 8'b0} << 1;
                        neg_divisor <= -abs_divisor;
                        cnt <= 1;
                        state <= DIVIDE;
                    end
                end
                DIVIDE: begin
                    if (cnt <= 8) begin

                        if (SR[16:8] >= neg_divisor) begin
                            SR[16:8] <= SR[16:8] - neg_divisor;
                            SR[0] <= 1'b1;
                        end else begin
                            SR[0] <= 1'b0;
                        end
                        SR <= SR << 1;
                        cnt <= cnt + 1;
                    end else begin
                        state <= DONE;
                    end
                end
                DONE: begin

                    quo_reg = (quo_sign) ? -SR[7:0] : SR[7:0];
                    rem_reg = (rem_sign && SR[15:8]) ? -SR[15:8] : SR[15:8];
                    result <= {rem_reg, quo_reg};
                    res_valid <= 1;
                    state <= IDLE;
                end
            endcase
        end
    end

endmodule

