module div_16bit (
    input [15:0] A,
    input [7:0] B,
    output [15:0] result,
    output [15:0] odd
);

reg [15:0] a_reg;
reg [7:0] b_reg;


always @(*) begin
    a_reg = A;
    b_reg = B;
end

reg [15:0] quo;
reg [15:0] rem;


always @(*) begin
    integer i;
    reg [15:0] remainder;
    reg [15:0] quotient;

    remainder = 16'b0;
    quotient = 16'b0;

    for (i = 15;
 i >= 0;
 i = i - 1) begin
        remainder = {remainder[14:0], a_reg[i]};
        if (remainder >= {8'b0, b_reg}) begin
            remainder = remainder - {8'b0, b_reg};
            quotient[i] = 1'b1;
        end else begin
            quotient[i] = 1'b0;
        end
    end

    quo = quotient;
    rem = {8'b0, remainder[7:0]};
end

assign result = quo;
assign odd = rem;

endmodule

