module comparator_4bit (
    input [3:0] A,
    input [3:0] B,
    output A_greater,
    output A_equal,
    output A_less
);

    wire [3:0] diff;
    wire [4:0] borrow;

    assign borrow[0] = 0;

    generate
        genvar i;
        for (i = 0;
 i < 4;
 i = i + 1) begin : subtractor
            assign diff[i] = A[i] ^ B[i] ^ borrow[i];
            assign borrow[i+1] = (~A[i] & B[i]) | ((~A[i] | B[i]) & borrow[i]);
        end
    endgenerate

    assign A_less = borrow[4];
    assign A_greater = (diff != 4'b0) && !borrow[4];
    assign A_equal = (diff == 4'b0) && !borrow[4];

endmodule

