module fixed_point_adder #(
    parameter Q = 8,  
    parameter N = 16  
) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output reg [N-1:0] c
);

    always @(*) begin
        wire sign_a = a[N-1];
        wire sign_b = b[N-1];
        wire [N-2:0] mag_a = a[N-2:0];
        wire [N-2:0] mag_b = b[N-2:0];

        if (sign_a == sign_b) begin

            wire [N-1:0] sum_mag = {1'b0, mag_a} + {1'b0, mag_b};
            if (sum_mag[N-1]) begin

                c = {sign_a, {N-1{1'b1}}};
            end else begin
                c = {sign_a, sum_mag[N-2:0]};
            end
        end else begin

            if (mag_a > mag_b) begin
                c = {1'b0, mag_a - mag_b};
            end else if (mag_b > mag_a) begin
                c = {1'b1, mag_b - mag_a};
            end else begin

                c = {1'b0, {N-1{1'b0}}};
            end
        end
    end

endmodule

