module fixed_point_subtractor #(
    parameter Q = 4,  
    parameter N = 8   
) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output reg [N-1:0] c
);

    reg sign_a, sign_b;
    reg [N-2:0] mag_a, mag_b;
    reg [N-2:0] mag_diff;
    reg res_sign;

    always @(*) begin
        sign_a = a[N-1];
        sign_b = b[N-1];
        mag_a = a[N-2:0];
        mag_b = b[N-2:0];

        if (sign_a == sign_b) begin

            if (mag_a >= mag_b) begin
                mag_diff = mag_a - mag_b;
                res_sign = sign_a;
            end else begin
                mag_diff = mag_b - mag_a;
                res_sign = ~sign_a;
            end


            if (mag_diff == 0) begin
                res_sign = 0;
            end
        end else begin

            if (mag_a > mag_b) begin
                mag_diff = mag_a - mag_b;
                res_sign = 0;
            end else if (mag_a < mag_b) begin
                mag_diff = mag_b - mag_a;
                res_sign = 1;
            end else begin
                mag_diff = 0;
                res_sign = 0;
            end
        end


        c = {res_sign, mag_diff};
    end

endmodule

