module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);

    reg [2:0] counter;
    reg a_sign, b_sign, z_sign;
    reg [7:0] a_exponent, b_exponent;
    reg [22:0] a_mantissa, b_mantissa;
    reg [9:0] sum_exp;
    reg [23:0] a_mant, b_mant;
    reg [47:0] product;
    reg guard, round, sticky;
    reg [23:0] product_mant;
    reg [9:0] final_exp;

    always @(posedge clk) begin
        if (rst) begin
            counter <= 0;
            z <= 0;
        end else begin
            case (counter)
                0: begin

                    a_sign <= a[31];
                    a_exponent <= {1'b0, a[30:23]};
                    a_mantissa <= a[22:0];

                    b_sign <= b[31];
                    b_exponent <= {1'b0, b[30:23]};
                    b_mantissa <= b[22:0];


                    if ((a_exponent == 9'h0ff && a_mantissa != 0) || 
                       (b_exponent == 9'h0ff && b_mantissa != 0)) begin
                        z <= {a_sign ^ b_sign, 8'hff, 23'h1};
                        counter <= 0;
                    end else if ((a_exponent == 9'h0ff) || (b_exponent == 9'h0ff)) begin

                        if ((a_exponent == 9'h0ff && b_exponent == 9'h0ff)) begin
                            z <= {a_sign ^ b_sign, 8'hff, 23'h0};
                        end else if (a_exponent == 9'h0ff) begin
                            z <= {a_sign ^ b_sign, 8'hff, 23'h0};
                        end else if (b_exponent == 9'h0ff) begin
                            z <= {a_sign ^ b_sign, 8'hff, 23'h0};
                        end else begin
                            z <= {a_sign ^ b_sign, 8'hff, 23'h1};
                        end
                        counter <= 0;
                    end else if (a_exponent == 0 && a_mantissa == 0) || 
                               (b_exponent == 0 && b_mantissa == 0) begin

                        z <= {a_sign ^ b_sign, 9'b0, 23'b0};
                        counter <= 0;
                    end else begin

                        sum_exp <= a_exponent + b_exponent - 9'd127;
                        counter <= 1;
                    end
                end
                1: begin

                    a_mant <= {1'b1, a_mantissa};
                    b_mant <= {1'b1, b_mantissa};
                    product <= a_mant * b_mant;
                    counter <= 2;
                end
                2: begin

                    if (product[47] && product[46]) begin 
                        product <= product >> 1;
                        sum_exp <= sum_exp + 1;
                    end
                    counter <= 3;
                end
                3: begin

                    product_mant <= product[46:23];

                    guard <= product[22];
                    round <= product[21];
                    sticky <= |product[20:0];

                    if (guard && (round || sticky || product_mant[0])) begin
                        product_mant <= product_mant + 1;
                    end
                    counter <= 4;
                end
                4: begin

                    final_exp <= sum_exp + 9'd127;
                    if (final_exp >= 9'h100) begin
                        z <= {a_sign ^ b_sign, 8'hff, 23'h0};

                    end else if (final_exp <= 0) begin
                        z <= {a_sign ^ b_sign, 9'b0, 23'b0};

                    end else begin
                        z <= {a_sign ^ b_sign, final_exp[7:0], product_mant[22:0]};
                    end
                    counter <= 0;
                end
                default: counter <= 0;
            endcase
        end
    end

