        stack_mem[0] <= 0;
        stack_mem[1] <= 0;
        stack_mem[2] <= 0;
        stack_mem[3] <= 0;
        EMPTY <= 1;
        FULL <= 0;
        dataOut <= 0;
    end
    else if (EN) begin
        if (RW == 0) begin 
            if (!FULL) begin

                stack_mem[SP-1] <= dataIn;
                SP <= SP - 1;
            end
        end
        else begin 
            if (!EMPTY) begin

                dataOut <= stack_mem[SP];
                SP <= SP + 1;
            end
        end

        EMPTY <= (SP == 4);
        FULL <= (SP == 0);
    end
end

endmodule

