module pulse_detect (
    input clk,
    input rst_n,
    input data_in,
    output reg data_out
);

    reg [1:0] current_state, next_state;


    localparam IDLE = 2'b00,
               S1   = 2'b01,
               S2   = 2'b10;


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            current_state <= IDLE;
        end else begin
            current_state <= next_state;
        end
    end


    always @(*) begin
        case (current_state)
            IDLE: next_state = (data_in) ? IDLE : S1;
            S1:   next_state = (data_in) ? S2 : IDLE;
            S2:   next_state = (data_in) ? IDLE : IDLE;
            default: next_state = IDLE;
        endcase
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            data_out <= 0;
        end else begin
            data_out <= (current_state == S2) && (data_in == 0);
        end
    end

