module traffic_light (
    input clk,
    input rst_n,
    input pass_request,
    output reg [7:0] clock,
    output reg red,
    output reg yellow,
    output reg green
);

parameter idle = 2'b00,
          s1_red = 2'b01,
          s3_green = 2'b10,
          s2_yellow = 2'b11;

reg [1:0] state;
reg [7:0] cnt;
reg p_green_prev, p_yellow_prev, p_red_prev;


always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= idle;
    end else begin
        case (state)
            idle: state <= s1_red;
            s1_red: state <= (cnt == 0) ? s3_green : s1_red;
            s3_green: state <= (cnt == 0) ? s2_yellow : s3_green;
            s2_yellow: state <= (cnt == 0) ? s1_red : s2_yellow;
            default: state <= idle;
        endcase
    end
end


always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        cnt <= 10;
    end else begin
        if (pass_request && green)
            cnt <= 10;
        else if (!green && p_green_prev)
            cnt <= 60;
        else if (!yellow && p_yellow_prev)
            cnt <= 5;
        else if (!red && p_red_prev)
            cnt <= 10;
        else
            cnt <= cnt - 1;
    end
end


always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        {p_red_prev, p_yellow_prev, p_green_prev} <= 0;
    end else begin
        p_red_prev <= red;
        p_yellow_prev <= yellow;
        p_green_prev <= green;
    end
end


always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        {red, yellow, green} <= 0;
    end else begin
        case (state)
            idle: {red, yellow, green} <= 0;
            s1_red: {red, yellow, green} <= 3'b100;
            s3_green: {red, yellow, green} <= 3'b001;
            s2_yellow: {red, yellow, green} <= 3'b010;
            default: {red, yellow, green} <= 0;
        endcase
    end
end

assign clock = cnt;

endmodule

