        a_prev <= a;

        if (a_prev == 0 && a == 1) begin
            rise <= 1;
            down <= 0;

        end else if (a_prev == 1 && a == 0) begin
            rise <= 0;
            down <= 1;

        end else begin
            rise <= 0;
            down <= 0;
        end
    end
end

