module alu (
    input [31:0] a,
    input [31:0] b,
    input [5:0] aluc,
    output [31:0] r,
    output zero,
    output carry,
    output negative,
    output overflow,
    output flag
);


    localparam ADD  = 6'b100000;
    localparam ADDU = 6'b100001;
    localparam SUB  = 6'b100010;
    localparam SUBU = 6'b100011;
    localparam AND  = 6'b100100;
    localparam OR   = 6'b100101;
    localparam XOR  = 6'b100110;
    localparam NOR  = 6'b100111;
    localparam SLT  = 6'b101010;
    localparam SLTU = 6'b101011;
    localparam SLL  = 6'b000000;
    localparam SRL  = 6'b000010;
    localparam SRA  = 6'b000011;
    localparam SLLV = 6'b000100;
    localparam SRLV = 6'b000110;
    localparam SRAV = 6'b000111;
    localparam LUI  = 6'b001111;


    reg [31:0] r_reg;
    reg carry_reg;
    reg overflow_reg;
    reg flag_reg;


    assign r = r_reg;
    assign carry = carry_reg;
    assign overflow = overflow_reg;
    assign flag = flag_reg;


    assign zero = (r_reg == 32'b0);
    assign negative = r_reg[31];

    always @(*) begin

        r_reg = 32'b0;
        carry_reg = 0;
        overflow_reg = 0;
        flag_reg = 1'bz;

        case (aluc)
            ADD: begin
                {carry_reg, r_reg} = {1'b0, a} + {1'b0, b};
                overflow_reg = (a[31] == b[31]) && (r_reg[31] != a[31]);
            end
            ADDU: begin
                {carry_reg, r_reg} = {1'b0, a} + {1'b0, b};
            end
            SUB: begin
                {carry_reg, r_reg} = {1'b0, a} - {1'b0, b};
                overflow_reg = (a[31] != b[31]) && (r_reg[31] != a[31]);
            end
            SUBU: begin
                {carry_reg, r_reg} = {1'b0, a} - {1'b0, b};
            end
            AND: begin
                r_reg = a & b;
            end
            OR: begin
                r_reg = a | b;
            end
            XOR: begin
                r_reg = a ^ b;
            end
            NOR: begin
                r_reg = ~(a | b);
            end
            SLT: begin
                r_reg = {31'b0, ($signed(a) < $signed(b))};
                flag_reg = ($signed(a) < $signed(b)) ? 1'b1 : 1'bz;
            end
            SLTU: begin
                r_reg = {31'b0, (a < b)};
                flag_reg = (a < b) ? 1'b1 : 1'bz;
            end
            SLL: begin
                r_reg = b << a[4:0];
            end
            SRL: begin
                r_reg = b >> a[4:0];
            end
            SRA: begin
                r_reg = $signed(b) >>> a[4:0];
            end
            SLLV: begin
                r_reg = a << b[4:0];
            end
            SRLV: begin
                r_reg = a >> b[4:0];
            end
            SRAV: begin
                r_reg = $signed(a) >>> b[4:0];
            end
            LUI: begin
                r_reg = {b[15:0], 16'b0};
            end
            default: begin
                r_reg = 32'bz;
            end
        endcase
    end

endmodule

