module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

    reg [1:0] state;
    localparam IDLE = 2'b00;
    localparam CALC_ABS = 2'b01;
    localparam DIVIDE = 2'b10;
    localparam ADJUST_SIGN = 2'b11;

    reg [7:0] dividend_abs, divisor_abs;
    reg sign_dividend, sign_divisor;
    reg [15:0] combined_reg;
    reg [3:0] cnt;
    reg [7:0] quotient_unsigned, remainder_unsigned;

    always @(posedge clk) begin
        if (rst) begin
            state <= IDLE;
            res_valid <= 0;
            combined_reg <= 0;
            cnt <= 0;
            dividend_abs <= 0;
            divisor_abs <= 0;
            sign_dividend <= 0;
            sign_divisor <= 0;
            quotient_unsigned <= 0;
            remainder_unsigned <= 0;
            result <= 0;
        end else begin
            case (state)
                IDLE: begin
                    if (opn_valid) begin

                        if (sign) begin
                            sign_dividend <= dividend[7];
                            sign_divisor <= divisor[7];
                            dividend_abs <= (dividend[7]) ? (~dividend + 1) : dividend;
                            divisor_abs <= (divisor[7]) ? (~divisor + 1) : divisor;
                        end else begin
                            sign_dividend <= 0;
                            sign_divisor <= 0;
                            dividend_abs <= dividend;
                            divisor_abs <= divisor;
                        end

                        combined_reg <= {8'b0, dividend_abs};
                        cnt <= 0;
                        res_valid <= 0;
                        state <= DIVIDE;
                    end
                end

                DIVIDE: begin
                    if (cnt < 8) begin

                        reg [15:0] next_combined;
                        next_combined = combined_reg << 1;
                        if (next_combined[15:8] >= divisor_abs) begin
                            next_combined[15:8] = next_combined[15:8] - divisor_abs;
                            next_combined[0] = 1;
                        end else begin
                            next_combined[0] = 0;
                        end
                        combined_reg <= next_combined;
                        cnt <= cnt + 1;
                    end else begin

                        quotient_unsigned <= combined_reg[7:0];
                        remainder_unsigned <= combined_reg[15:8];
                        state <= ADJUST_SIGN;
                    end
                end

                ADJUST_SIGN: begin

                    if (sign) begin
                        if (sign_dividend ^ sign_divisor) begin
                            quotient_unsigned <= -quotient_unsigned;
                        end
                        if (sign_dividend) begin
                            remainder_unsigned <= -remainder_unsigned;
                        end
                    end


                    result <= {remainder_unsigned, quotient_unsigned};
                    res_valid <= 1;
                    state <= IDLE;
                end

                default: state <= IDLE;
            endcase
        end
    end

endmodule

