module div_16bit (
    input [15:0] A,
    input [7:0] B,
    output [15:0] result,
    output [15:0] odd
);

reg [15:0] a_reg, b_reg;


always @(*) begin
    a_reg = A;
    b_reg = B;
end


reg [15:0] quotient;
reg [15:0] remainder;
integer i;

always @(*) begin
    remainder = 16'b0;
    quotient = 16'b0;
    for (i = 15;
 i >= 0;
 i = i - 1) begin
        remainder = {remainder[14:0], a_reg[i]};
        if (remainder >= {8'b0, b_reg}) begin
            remainder = remainder - {8'b0, b_reg};
            quotient[i] = 1'b1;
        end else begin
            quotient[i] = 1'b0;
        end
    end
end

assign result = quotient;
assign odd = remainder;

endmodule

