module fixed_point_adder #(parameter Q=4, N=8) (
    input [N-1:0] a,
    input [N-1:0] b,
    output reg [N-1:0] c
);

    reg [N-1:0] mag_a, mag_b;
    reg [N-1:0] res;

    always @(*) begin

        mag_a = a[N-1] ? (~a + 1) : a;
        mag_b = b[N-1] ? (~b + 1) : b;

        if (a[N-1] == b[N-1]) begin

            res = mag_a + mag_b;

            c = {a[N-1], res[N-2:0]};
        end else begin

            if (mag_a > mag_b) begin
                res = mag_a - mag_b;

                c = {a[N-1], res[N-2:0]};
            end else if (mag_b > mag_a) begin
                res = mag_b - mag_a;

                c = {b[N-1], res[N-2:0]};
            end else begin

                c = {a[N-1], {(N-1){1'b0}}};
            end
        end
    end

endmodule

