module fixed_point_subtractor #(
    parameter Q = 2,
    parameter N = 4
) (
    input [N-1:0] a,
    input [N-1:0] b,
    output reg [N-1:0] c
);

    always @(*) begin
        reg sign_a = a[N-1];
        reg sign_b = b[N-1];
        reg [N-2:0] abs_a, abs_b;
        reg [N-1:0] magnitude;
        reg sign;

        if (sign_a == sign_b) begin

            c = a - b;

            if (c[N-1] == 0 && c[N-2:0] == 0) begin
                c[N-1] = 0;
            end
        end else begin

            abs_a = sign_a ? (~a + 1) : a;
            abs_b = sign_b ? (~b + 1) : b;

            if (sign_a == 0 && sign_b == 1) begin

                if (abs_a > abs_b) begin
                    sign = 0;
                    magnitude = {1'b0, abs_a} - {1'b0, abs_b};
                end else begin
                    sign = 1;
                    magnitude = {1'b0, abs_b} - {1'b0, abs_a};
                end
            end else begin

                sign = 1;
                magnitude = {1'b0, abs_a} + {1'b0, abs_b};
            end

            c = {sign, magnitude};
        end
    end

endmodule

