module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);

    reg [2:0] counter;
    reg a_sign, b_sign, z_sign;
    reg [7:0] a_exponent, b_exponent, z_exponent;
    reg [23:0] a_mantissa, b_mantissa;
    reg [47:0] product;
    reg [22:0] mantissa;
    reg [7:0] exponent;
    reg [3:0] guard, round, sticky;
    reg overflow;


    localparam EXTRACT = 0;
    localparam SPECIAL = 1;
    localparam MULTIPLY = 2;
    localparam NORMALIZE = 3;
    localparam ROUND = 4;
    localparam ADJUST = 5;
    localparam OUTPUT = 6;

    always @(posedge clk) begin
        if (rst) begin
            counter <= EXTRACT;
            z <= 0;
        end else begin
            case (counter)
                EXTRACT: begin

                    a_sign <= a[31];
                    b_sign <= b[31];
                    a_exponent <= a[30:23];
                    b_exponent <= b[30:23];
                    a_mantissa <= (a[30:23] != 0) ? {1'b1, a[22:0]} : {1'b0, a[22:0]};
                    b_mantissa <= (b[30:23] != 0) ? {1'b1, b[22:0]} : {1'b0, b[22:0]};
                    counter <= SPECIAL;
                end

                SPECIAL: begin

                    if (a[30:23] == 8'hff || b[30:23] == 8'hff) begin
                        if ((a[30:23] == 8'hff || b[30:23] == 8'hff) && 
                            (a[22:0] != 0 || b[22:0] != 0)) begin
                            z <= {1'b0, 8'hff, 23'h1};
                        end else begin
                            z <= {a_sign ^ b_sign, 8'hff, (a[30:23] == 8'hff) ? 23'h0 : 23'h1};
                        end
                    end else if (a[22:0] == 0 && b[22:0] == 0) begin
                        z <= {a_sign ^ b_sign, 31'h0};
                    end else if (a[22:0] == 0 || b[22:0] == 0) begin
                        z <= {a_sign ^ b_sign, 31'h0};
                    end else begin
                        counter <= MULTIPLY;
                    end
                end

                MULTIPLY: begin
                    product <= a_mantissa * b_mantissa;
                    counter <= NORMALIZE;
                end

                NORMALIZE: begin

                    if (product[47:46] >= 2'b10) begin
                        mantissa <= product[47:24];
                        exponent <= (a_exponent + b_exponent) - 127 + 1;
                    end else begin
                        mantissa <= product[46:23];
                        exponent <= a_exponent + b_exponent - 127;
                    end
                    counter <= ROUND;
                end

                ROUND: begin

                    guard = |mantissa[23:21];
                    round = |mantissa[20:18];
                    sticky = |mantissa[17:0];
                    if ((guard & (round | sticky)) || (guard & ~round & ~sticky & mantissa[23])) begin
                        {overflow, mantissa} = {mantissa + 1} + 24'd0;
                        if (overflow) begin
                            exponent <= exponent + 1;
                            mantissa <= 24'd0;
                        end
                    end
                    counter <= ADJUST;
                end

                ADJUST: begin

                    if (exponent > 255) begin
                        z <= {a_sign ^ b_sign, 8'hff, 23'd0};
                    end else if (exponent < 0) begin
                        z <= {a_sign ^ b_sign, 31'd0};
                    end else begin
                        z <= {a_sign ^ b_sign, exponent, mantissa};
                    end
                    counter <= OUTPUT;
                end

                OUTPUT: begin
                    counter <= EXTRACT;
                end

                default: counter <= EXTRACT;
            endcase
        end
    end

endmodule

