    input rinc,
    output rempty,
    output [WIDTH-1:0] rdata
);

localparam PTR_WIDTH = $clog2(DEPTH) + 1;


reg [PTR_WIDTH-1:0] wptr_bin, rptr_bin;
reg [PTR_WIDTH-1:0] wptr_gray, rptr_gray;


