    .rclk(rclk),
    .renc(rinc && !rempty),
    .raddr(raddr),
    .rdata(rdata)
);


always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) begin
        wptr_bin <= 0;
        wptr_gray <= 0;
    end else if (winc && !wfull) begin
        wptr_bin <= wptr_bin + 1;
        wptr_gray <= bin2gray(wptr_bin + 1);
