end

always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) begin
        rptr_gray_sync1 <= 0;
        rptr_gray_sync2 <= 0;
    end else begin
        rptr_gray_sync1 <= rptr_gray;
        rptr_gray_sync2 <= rptr_gray_sync1;
    end
end


assign rempty = (rptr_gray == wptr_gray_sync2);
assign wfull = (wptr_gray[$clog2(DEPTH)] != rptr_gray_sync2[$clog2(DEPTH)]) &&
               (wptr_gray[$clog2(DEPTH)-1:0] == rptr_gray_sync2[$clog2(DEPTH)-1:0]);


