module traffic_light (
    input rst_n,
    input clk,
    input pass_request,
    output reg [7:0] clock,
    output reg red,
    output reg yellow,
    output reg green
);

    localparam S_IDLE  = 2'b00,
               S_RED   = 2'b01,
               S_GREEN = 2'b10,
               S_YELLOW= 2'b11;

    reg [1:0] state, next_state;
    reg [7:0] cnt, next_cnt;
    reg next_red, next_green, next_yellow;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= S_IDLE;
            cnt <= 10;
            red <= 0;
            green <= 0;
            yellow <= 0;
            clock <= 10;
        end else begin
            state <= next_state;
            cnt <= next_cnt;
            red <= next_red;
            green <= next_green;
            yellow <= next_yellow;
            clock <= cnt;
        end
    end

    always @(*) begin
        next_state = state;
        next_cnt = cnt;
        next_red = red;
        next_green = green;
        next_yellow = yellow;

        case (state)
            S_IDLE: begin
                next_state = S_RED;
                next_cnt = 10;
                next_red = 1;
                next_green = 0;
                next_yellow = 0;
            end

            S_RED: begin
                if (cnt == 0) begin
                    next_state = S_GREEN;
                    next_cnt = 60;
                    next_red = 0;
                    next_green = 1;
                    next_yellow = 0;
                end else begin
                    next_cnt = cnt - 1;
                end
            end

            S_GREEN: begin
                if (pass_request && (cnt > 10)) begin
                    next_cnt = 10;
                end

                if (cnt == 0) begin
                    next_state = S_YELLOW;
                    next_cnt = 5;
                    next_red = 0;
                    next_green = 0;
                    next_yellow = 1;
                end else begin
                    next_cnt = cnt - 1;
                end
            end

            S_YELLOW: begin
                if (cnt == 0) begin
                    next_state = S_RED;
                    next_cnt = 10;
                    next_red = 1;
                    next_green = 0;
                    next_yellow = 0;
                end else begin
                    next_cnt = cnt - 1;
                end
            end

            default: begin
                next_state = S_IDLE;
                next_cnt = 10;
                next_red = 0;
                next_green = 0;
                next_yellow = 0;
            end
        endcase
    end

endmodule

