module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);


localparam IDLE = 2'b00;
localparam RUN = 2'b01;
localparam DONE = 2'b10;

reg [1:0] state;
reg [7:0] abs_dividend, abs_divisor;
reg [7:0] quotient, remainder;
reg [3:0] cnt;
reg sign_q, sign_r;
reg [7:0] temp_dividend;

always @(posedge clk) begin
    if (rst) begin
        state <= IDLE;
        res_valid <= 0;
        quotient <= 0;
        remainder <= 0;
        cnt <= 0;
        temp_dividend <= 0;
        sign_q <= 0;
        sign_r <= 0;
        abs_dividend <= 0;
        abs_divisor <= 0;
        result <= 0;
    end else begin
        case (state)
            IDLE: begin
                res_valid <= 0;
                if (opn_valid) begin

                    if (sign) begin
                        abs_dividend <= (dividend[7]) ? (-dividend) : dividend;
                        abs_divisor <= (divisor[7]) ? (-divisor) : divisor;
                        sign_q <= dividend[7] ^ divisor[7];
                        sign_r <= dividend[7];
                    end else begin
                        abs_dividend <= dividend;
                        abs_divisor <= divisor;
                        sign_q <= 0;
                        sign_r <= 0;
                    end
                    temp_dividend <= abs_dividend << 1;
                    remainder <= 0;
                    quotient <= 0;
                    cnt <= 0;
                    state <= RUN;
                end
            end
            RUN: begin
                if (cnt < 8) begin

                    remainder <= (remainder << 1) | (temp_dividend[7]);
                    temp_dividend <= temp_dividend << 1;

                    if (remainder >= abs_divisor) begin
                        remainder <= remainder - abs_divisor;
                        quotient <= (quotient << 1) | 1;
                    end else begin
                        quotient <= quotient << 1;
                    end
                    cnt <= cnt + 1;
                end else begin
                    state <= DONE;
                end
            end
            DONE: begin

                if (sign_q) quotient <= -quotient;
                if (sign_r) remainder <= -remainder;
                result <= {remainder, quotient};
                res_valid <= 1;
                state <= IDLE;
            end
        endcase
    end
end

endmodule

