module div_16bit (
    input [15:0] A,
    input [7:0] B,
    output reg [15:0] result,
    output reg [15:0] odd
);

    reg [15:0] a_reg;
    reg [7:0] b_reg;

    always @(A, B) begin
        a_reg = A;
        b_reg = B;
    end

    always @(A, B) begin
        integer i;
        reg [7:0] rem;
        reg [7:0] divisor;
        reg [15:0] dividend;

        dividend = a_reg;
        divisor = b_reg;
        rem = 8'b0;
        result = 16'b0;

        for (i = 15;
 i >= 0;
 i = i - 1) begin
            rem = (rem << 1) | ((dividend >> i) & 1);
            if (rem >= divisor) begin
                result[i] = 1;
                rem = rem - divisor;
            end else begin
                result[i] = 0;
            end
        end

        odd = {8'b0, rem};
    end

endmodule

