module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z = 0
);

reg [2:0] counter;
reg [23:0] a_mantissa, b_mantissa;
reg [9:0] a_exp, b_exp;
reg a_sign, b_sign;
reg [49:0] product;
reg [7:0] sum_exp;
reg [4:0] shift_amount;
reg [22:0] rounded_man;
reg guard, round_bit, sticky;
reg [7:0] final_exp;


localparam IDLE = 0;
localparam INPUT_PROCESS = 1;
localparam SPECIAL_CASE = 2;
localparam MULTIPLY = 3;
localparam NORMALIZE = 4;
localparam ROUND = 5;
localparam ADJUST = 6;
localparam OUTPUT_RESULT = 7;

always @(posedge clk) begin
    if (rst) begin
        counter <= IDLE;
        z <= 0;
        a_sign <= 0;
        b_sign <= 0;
        a_exp <= 0;
        b_exp <= 0;
        a_mantissa <= 0;
        b_mantissa <= 0;
        product <= 0;
        sum_exp <= 0;
        shift_amount <= 0;
        rounded_man <= 0;
        guard <= 0;
        round_bit <= 0;
        sticky <= 0;
        final_exp <= 0;
    end else begin
        case (counter)
            IDLE: begin
                counter <= INPUT_PROCESS;
            end
            INPUT_PROCESS: begin
                a_sign <= a[31];
                b_sign <= b[31];
                a_exp <= a[30:23];
                b_exp <= b[30:23];
                a_mantissa <= (a[30:23] == 8'd0) ? {1'b0, a[22:0]} : {1'b1, a[22:0]};
                b_mantissa <= (b[30:23] == 8'd0) ? {1'b0, b[22:0]} : {1'b1, b[22:0]};
                sum_exp <= a_exp + b_exp - 127;
                counter <= SPECIAL_CASE;
            end
            SPECIAL_CASE: begin
                if ((a_exp == 8'hFF && b_exp != 8'hFF) || (b_exp == 8'hFF && a_exp != 8'hFF)) begin
                    z <= {a_sign ^ b_sign, 8'hFF, 0};
                    counter <= IDLE;
                end else if (a_exp == 8'hFF || b_exp == 8'hFF) begin
                    z <= {a_sign ^ b_sign, 8'hFF, 22'h1};
                    counter <= IDLE;
                end else if (a_mantissa == 0 && b_mantissa == 0) begin
                    z <= {a_sign ^ b_sign, 0, 0};
                    counter <= IDLE;
                end else begin
                    counter <= MULTIPLY;
                end
            end
            MULTIPLY: begin
                product <= a_mantissa * b_mantissa;
                counter <= NORMALIZE;
            end
            NORMALIZE: begin
                integer i;
                reg [4:0] leading_one;
                leading_one = 0;
                for (i=47;
 i>=0;
 i=i-1) begin
                    if (product[i]) begin
                        leading_one = i;
                        disable find_leading;
                    end
                end
                shift_amount = 47 - leading_one;
                counter <= ROUND;
            end
            ROUND: begin
                product <= product << shift_amount;
                sum_exp <= sum_exp + shift_amount;
                guard <= product[46];
                round_bit <= product[45];
                sticky <= |product[44:0];
                rounded_man <= product[46:24];
                counter <= ADJUST;
            end
            ADJUST: begin
                if (guard && (round_bit || sticky)) begin
                    if (rounded_man[23]) begin
                        rounded_man <= rounded_man + 1;
                        if (rounded_man == 24'h1000000) begin
                            rounded_man <= 24'h0;
                            sum_exp <= sum_exp + 1;
                        end
                    end else begin
                        rounded_man <= rounded_man + 1;
                    end
                end
                final_exp <= sum_exp + (rounded_man == 24'h1000000 ? 1 : 0);
                counter <= OUTPUT_RESULT;
            end
            OUTPUT_RESULT: begin
                if (final_exp > 254) begin
                    z <= {a_sign ^ b_sign, 8'hFF, 0};
                end else if (final_exp < 1) begin
                    z <= {a_sign ^ b_sign, 0, rounded_man[22:0]};
                end else begin
                    z <= {a_sign ^ b_sign, final_exp[7:0], rounded_man[22:0]};
                end
                counter <= IDLE;
            end
            default: counter <= IDLE;
        endcase
    end
end

endmodule

