module traffic_light (
    input rst_n,
    input clk,
    input pass_request,
    output reg [7:0] clock,
    output reg red,
    output reg yellow,
    output reg green
);


    parameter idle     = 2'b00;
    parameter s1_red   = 2'b01;
    parameter s2_yellow= 2'b10;
    parameter s3_green = 2'b11;

    reg [1:0] state;
    reg [7:0] cnt;


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= idle;
            cnt <= 8'd10;
            {red, yellow, green} <= 3'b000;
        end else begin
            case (state)
                idle: begin
                    state <= s1_red;
                    red <= 1'b1;
                    yellow <= 1'b0;
                    green <= 1'b0;
                    cnt <= 8'd3;
                end
                s1_red: begin
                    red <= 1'b1;
                    yellow <= 1'b0;
                    green <= 1'b0;
                    if (cnt == 0) begin
                        state <= s3_green;
                        red <= 1'b0;
                        green <= 1'b1;
                        cnt <= 8'd60;
                    end else begin
                        cnt <= cnt - 1;
                    end
                end
                s3_green: begin
                    green <= 1'b1;
                    if (pass_request && cnt > 10) begin
                        cnt <= 8'd10;
                    end
                    if (cnt == 0) begin
                        state <= s2_yellow;
                        yellow <= 1'b1;
                        green <= 1'b0;
                        cnt <= 8'd5;
                    end else begin
                        cnt <= cnt - 1;
                    end
                end
                s2_yellow: begin
                    yellow <= 1'b1;
                    if (cnt == 0) begin
                        state <= s1_red;
                        red <= 1'b1;
                        yellow <= 1'b0;
                        cnt <= 8'd3;
                    end else begin
                        cnt <= cnt - 1;
                    end
                end
                default: state <= idle;
            endcase
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            clock <= 8'd10;
        end else begin
            clock <= cnt;
        end
    end

endmodule

