module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

reg [1:0] state;
localparam IDLE = 0, BUSY = 1;

reg [15:0] SR;
reg [7:0] abs_dividend, abs_divisor;
reg signed [7:0] neg_divisor;
reg [3:0] cnt;
reg div_sign, divisor_sign;

always @(posedge clk) begin
    if (rst) begin
        state <= IDLE;
        res_valid <= 0;
        SR <= 0;
        cnt <= 0;
        result <= 0;
        abs_dividend <= 0;
        abs_divisor <= 0;
        neg_divisor <= 0;
        div_sign <= 0;
        divisor_sign <= 0;
    end else begin
        case (state)
            IDLE: begin
                res_valid <= 0;
                if (opn_valid && !res_valid) begin
                    div_sign <= dividend[7];
                    divisor_sign <= divisor[7];
                    abs_dividend <= sign ? (dividend[7] ? -dividend : dividend) : dividend;
                    abs_divisor <= sign ? (divisor[7] ? -divisor : divisor) : divisor;
                    SR <= {7'b0, (abs_dividend << 1)};
                    neg_divisor <= -(abs_divisor);
                    cnt <= 1;
                    state <= BUSY;
                end
            end
            BUSY: begin
                if (cnt <= 8) begin
                    reg signed [7:0] remainder = SR[15:8];
                    reg signed [7:0] new_remainder = remainder - neg_divisor;
                    reg subtract_result = (new_remainder >= 0) ? 1'b1 : 1'b0;

                    if (subtract_result) begin
                        SR[15:8] <= new_remainder;
                        SR[0] <= 1'b1;
                    end else begin
                        SR[0] <= 1'b0;
                    end

                    SR <= {SR[14:0], 1'b0};
                    cnt <= cnt + 1;
                end else begin
                    state <= IDLE;
                    if (sign) begin
                        reg [7:0] quotient = SR[7:0];
                        reg [7:0] remainder = SR[15:8];
                        reg quotient_sign = div_sign ^ divisor_sign;

                        if (quotient_sign)
                            quotient = -quotient;

                        remainder = remainder + (div_sign ? (remainder[7] ? abs_divisor : -abs_divisor) : 0);

                        result <= {remainder, quotient};
                    end else begin
                        result <= SR;
                    end
                    res_valid <= 1;
                end
            end
        endcase
        if (state != BUSY) res_valid <= 0;
    end
end

endmodule

