module div_16bit (
    input [15:0] A,
    input [7:0] B,
    output [15:0] result,
    output [15:0] odd
);
    reg [15:0] a_reg;
    reg [7:0] b_reg;
    reg [15:0] quotient;
    reg [7:0] remainder;


    always @* begin
        a_reg = A;
        b_reg = B;
    end


    always @* begin
        integer i;
        reg [15:0] dividend = a_reg;
        reg [7:0] divisor = b_reg;
        reg [15:0] current_remainder = 0;
        reg [15:0] current_quotient = 0;

        for (i = 15;
 i >= 0;
 i = i - 1) begin
            current_remainder = (current_remainder << 1) | ((dividend >> i) & 1);
            if (current_remainder >= divisor) begin
                current_quotient[i] = 1'b1;
                current_remainder = current_remainder - divisor;
            end else begin
                current_quotient[i] = 1'b0;
            end
        end

        quotient = current_quotient;
        remainder = current_remainder;
    end

    assign result = quotient;
    assign odd = {8'b0, remainder};
endmodule

