module cla_4bit (
    input [3:0] A,
    input [3:0] B,
    input C_in,
    output [3:0] S,
    output G,
    output P,
    output C_out
);
    wire [3:0] g = A & B;
    wire [3:0] p = A ^ B;

    wire c1 = g[0] | (p[0] & C_in);
    wire c2 = g[1] | (p[1] & c1);
    wire c3 = g[2] | (p[2] & c2);
    wire c4 = g[3] | (p[3] & c3);

    assign S = p ^ {c3, c2, c1, C_in};
    assign G = g[3] | (p[3] & g[2]) | (p[3] & p[2] & g[1]) | (p[3] & p[2] & p[1] & g[0]);
    assign P = p[3] & p[2] & p[1] & p[0];
    assign C_out = c4;
endmodule

