        count <= 2'b00;
        accumulator <= 10'b0;
        valid_out <= 1'b0;
        data_out <= 10'b0;
    end else begin
        valid_out <= 1'b0;
        if (valid_in) begin
            accumulator <= accumulator + data_in;
            count <= count + 1;
            if (count == 2'b11) begin
                data_out <= accumulator + data_in;
                valid_out <= 1'b1;
                count <= 2'b00;
                accumulator <= 10'b0;
            end
        end
    end
end

