module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z = 0
);

    reg [2:0] counter;
    reg a_sign, b_sign;
    reg [7:0] a_exponent, b_exponent;
    reg [22:0] a_mantissa, b_mantissa;
    reg [47:0] product;
    reg [7:0] sum_exponent;
    reg guard, round, sticky;
    reg [22:0] z_mantissa;
    reg z_sign;
    reg [7:0] z_exponent;
    reg [47:0] product_shifted;


    reg [5:0] leading_one;
    reg [5:0] shift_amount;

    always @(posedge clk) begin
        if (rst) begin
            counter <= 0;
            z <= 0;
            a_sign <= 0;
            b_sign <= 0;
            a_exponent <= 0;
            b_exponent <= 0;
            a_mantissa <= 0;
            b_mantissa <= 0;
            product <= 0;
            sum_exponent <= 0;
            guard <= 0;
            round <= 0;
            sticky <= 0;
            z_mantissa <= 0;
            z_sign <= 0;
            z_exponent <= 0;
            product_shifted <= 0;
        end else begin
            case (counter)
                0: begin

                    a_sign <= a[31];
                    b_sign <= b[31];
                    a_exponent <= a[30:23];
                    b_exponent <= b[30:23];
                    a_mantissa <= (a[30:23] == 8'd0) ? {1'b0, a[22:0]} : {1'b1, a[22:0]};
                    b_mantissa <= (b[30:23] == 8'd0) ? {1'b0, b[22:0]} : {1'b1, b[22:0]};


                    if ((a[30:23] == 8'hFF && |a[22:0]) || (b[30:23] == 8'hFF && |b[22:0])) begin
                        z <= 32'h7FC00000;

                        counter <= 0;
                    end

                    else if ((a[30:23] == 8'hFF) ^ (b[30:23] == 8'hFF)) begin
                        z <= (a[30:23] == 8'hFF) ? {a_sign, 8'hFF, 23'h0} : {b_sign, 8'hFF, 23'h0};
                        counter <= 0;
                    end

                    else if ((a[30:23] == 8'h00 && a[22:0] == 23'h0) || (b[30:23] == 8'h00 && b[22:0] == 23'h0)) begin
                        z <= (a[30:23] == 8'h00 && a[22:0] == 23'h0) ? {b_sign, 31'h0} : {a_sign, 31'h0};
                        counter <= 0;
                    end
                    else begin

                        product <= {a_mantissa, 23'd0} * {b_mantissa, 23'd0};
                        sum_exponent <= a_exponent + b_exponent - 8'd127;
                        counter <= 1;
                    end
                end

                1: begin

                    leading_one = 6'd0;
                    for (int i = 47;
 i >= 0;
 i = i - 1) begin
                        if (product[i]) begin
                            leading_one = i;
                            break;
                        end
                    end
                    shift_amount = 6'd47 - leading_one;


                    product_shifted <= product << shift_amount;
                    counter <= 2;
                end

                2: begin

                    guard <= product_shifted[23];
                    round <= product_shifted[22];
                    sticky <= |product_shifted[21:0];
                    z_mantissa <= product_shifted[46:24];



                    if (guard && (round || sticky || (product_shifted[24] && z_mantissa[0]))) begin
                        if (z_mantissa == 23'h7fffff) begin 
                            z_mantissa <= 23'h0;
                            sum_exponent <= sum_exponent + 8'd1;
                        end else begin
                            z_mantissa <= z_mantissa + 24'd1;
                        end
                    end

                    counter <= 3;
                end

                3: begin

                    if (sum_exponent >= 8'hff) begin
                        z <= {z_sign, 8'hff, 23'h0};

                    end else if (sum_exponent == 8'h00) begin
                        z <= {z_sign, 8'h00, z_mantissa[22:0]};

                    end else begin
                        z <= {z_sign, sum_exponent, z_mantissa[22:0]};
                    end
                    counter <= 0;
                end

                default: counter <= 0;
            endcase
        end
    end

endmodule

