module LIFObuffer (
    input wire [3:0] dataIn,
    input wire RW,
    input wire EN,
    input wire Rst,
    input wire Clk,
    output reg EMPTY,
    output reg FULL,
    output reg [3:0] dataOut
);

reg [3:0] stack_mem [0:3];
reg [3:0] SP;


integer i;


always @(*) begin
    EMPTY = (SP == 4);
    FULL = (SP == 0);
end


always @(posedge Clk) begin
    if (Rst) begin
        SP <= 4;
        for (i = 0;
 i < 4;
 i = i + 1) begin
            stack_mem[i] <= 0;
        end
        dataOut <= 0;
    end
    else if (EN) begin
        if (RW == 0) begin 
            if (SP != 0) begin
                stack_mem[SP-1] <= dataIn;
                SP <= SP - 1;
            end
        end
        else begin 
            if (SP != 4) begin
                dataOut <= stack_mem[SP-1];
                stack_mem[SP-1] <= 0;

                SP <= SP + 1;
            end
        end
    end
end

endmodule

