module traffic_light (
    input rst_n,
    input clk,
    input pass_request,
    output reg [7:0] clock,
    output reg red,
    output reg yellow,
    output reg green
);

parameter idle = 2'b00;
parameter s1_red = 2'b01;
parameter s2_yellow = 2'b10;
parameter s3_green = 2'b11;

reg [1:0] state;
reg [7:0] cnt;
reg p_red, p_yellow, p_green;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= idle;
        p_red <= 0;
        p_yellow <= 0;
        p_green <= 0;
        cnt <= 8'd10;
        red <= 0;
        yellow <= 0;
        green <= 0;
    end else begin
        case (state)
            idle: begin
                state <= s3_green;
                p_green <= 1;
                cnt <= 8'd60;
            end
            s3_green: begin
                if (cnt > 0) begin
                    if (pass_request && (cnt > 10)) begin
                        cnt <= 8'd10;
                    end else begin
                        cnt <= cnt - 1;
                    end
                end else begin
                    p_green <= 0;
                    p_yellow <= 1;
                    state <= s2_yellow;
                    cnt <= 8'd5;
                end
            end
            s2_yellow: begin
                if (cnt > 0) begin
                    cnt <= cnt - 1;
                end else begin
                    p_yellow <= 0;
                    p_red <= 1;
                    state <= s1_red;
                    cnt <= 8'd10;
                end
            end
            s1_red: begin
                if (cnt > 0) begin
                    cnt <= cnt - 1;
                end else begin
                    p_red <= 0;
                    p_green <= 1;
                    state <= s3_green;
                    cnt <= 8'd60;
                end
            end
            default: state <= idle;
        endcase

        red <= p_red;
        yellow <= p_yellow;
        green <= p_green;
    end
end

assign clock = cnt;

endmodule

