module width_8to16 (
    input clk,
    input rst_n,
    input valid_in,
    input [7:0] data_in,
    output reg valid_out,
    output reg [15:0] data_out
);

    reg [7:0] data_lock;
    reg state;

    localparam IDLE = 1'b0, WAIT_SECOND = 1'b1;
    reg [15:0] combined_data;
    reg combined_valid;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            data_lock <= 8'b0;
            combined_valid <= 1'b0;
            combined_data <= 16'b0;
        end else begin
            combined_valid <= 1'b0;
            case (state)
                IDLE: begin
                    if (valid_in) begin
                        data_lock <= data_in;
                        state <= WAIT_SECOND;
                    end
                end
                WAIT_SECOND: begin
                    if (valid_in) begin
                        combined_data <= {data_lock, data_in};
                        combined_valid <= 1'b1;
                        state <= IDLE;
                    end
                end
            endcase
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            valid_out <= 1'b0;
            data_out <= 16'b0;
        end else begin
            valid_out <= combined_valid;
            data_out <= combined_data;
        end
    end

endmodule

