module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);


    localparam IDLE = 3'd0;
    localparam DIVIDE = 3'd1;
    localparam ADJUST = 3'd2;
    localparam DONE = 3'd3;

    reg [2:0] state;
    reg [7:0] dividend_abs, divisor_abs;
    reg dividend_sign, divisor_sign;
    reg [15:0] shift_reg;
    reg [3:0] cnt;
    reg [7:0] remainder, quotient;


    always @(*) begin
        if (sign) begin
            dividend_abs = dividend[7] ? -dividend : dividend;
            divisor_abs = divisor[7] ? -divisor : divisor;
            dividend_sign = dividend[7];
            divisor_sign = divisor[7];
        end else begin
            dividend_abs = dividend;
            divisor_abs = divisor;
            dividend_sign = 1'b0;
            divisor_sign = 1'b0;
        end
    end

    always @(posedge clk) begin
        if (rst) begin
            state <= IDLE;
            res_valid <= 0;
            remainder <= 0;
            quotient <= 0;
            shift_reg <= 0;
            cnt <= 0;
            dividend_sign <= 0;
            divisor_sign <= 0;
        end else begin
            case (state)
                IDLE: begin
                    res_valid <= 0;
                    if (opn_valid && !res_valid) begin

                        shift_reg <= {8'b0, dividend_abs};
                        state <= DIVIDE;
                        cnt <= 0;
                    end
                end

                DIVIDE: begin
                    if (cnt < 8) begin

                        shift_reg <= shift_reg << 1;


                        if (shift_reg[15:8] >= divisor_abs) begin
                            shift_reg[15:8] <= shift_reg[15:8] - divisor_abs;
                            shift_reg[0] <= 1'b1;
                        end else begin
                            shift_reg[0] <= 1'b0;
                        end

                        cnt <= cnt + 1;
                    end else begin

                        remainder <= shift_reg[15:8];
                        quotient <= shift_reg[7:0];
                        if (sign) begin
                            state <= ADJUST;
                        end else begin
                            state <= DONE;
                        end
                    end
                end

                ADJUST: begin

                    if (dividend_sign) begin
                        remainder <= -remainder;
                    end
                    if (dividend_sign ^ divisor_sign) begin
                        quotient <= -quotient;
                    end
                    state <= DONE;
                end

                DONE: begin
                    result <= {remainder, quotient};
                    res_valid <= 1;
                    state <= IDLE;
                end

                default: state <= IDLE;
            endcase
        end
    end

endmodule

