module div_16bit (
    input [15:0] A,
    input [7:0] B,
    output reg [15:0] result,
    output reg [15:0] odd
);

    reg [15:0] a_reg;
    reg [7:0] b_reg;


    always @(A, B) begin
        a_reg = A;
        b_reg = B;
    end


    always @(*) begin
        reg [15:0] rem = {8'b0, a_reg[15:8]};
        reg [15:0] quo = 0;
        reg [7:0] divisor = b_reg;

        for (int i = 0;
 i < 16;
 i = i + 1) begin

            rem = (rem << 1) | ((i < 8) ? a_reg[8 - i] : a_reg[7 - (i - 8)]);


            if (rem >= divisor) begin
                rem = rem - divisor;
                quo[15 - i] = 1'b1;
            end else begin
                quo[15 - i] = 1'b0;
            end
        end


        result = quo;
        odd = {rem, 8'b0};

    end

endmodule

