module fixed_point_adder #(
    parameter Q = 4,
    parameter N = 8
) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output reg [N-1:0] c
);
    wire signed [N-1:0] a_signed = a;
    wire signed [N-1:0] b_signed = b;
    wire [N-1:0] mag_a = a_signed < 0 ? -a_signed : a_signed;
    wire [N-1:0] mag_b = b_signed < 0 ? -b_signed : b_signed;
    reg [N:0] sum_mag;
    reg result_sign;

    always @(*) begin
        if (a_signed >= 0 && b_signed >= 0) begin
            sum_mag = mag_a + mag_b;
            result_sign = 0;
            if (sum_mag > (2**(N-1)-1)) begin
                c = {1'b0, {(N-1){1'b1}}};
            end else begin
                c = {result_sign, sum_mag[N-2:0]};
            end
        end else if (a_signed < 0 && b_signed < 0) begin
            sum_mag = mag_a + mag_b;
            result_sign = 1;
            if (sum_mag > (2**(N-1)-1)) begin
                c = {1'b1, {(N-1){1'b0}}};
            end else begin
                c = {result_sign, sum_mag[N-2:0]};
            end
        end else begin
            if (mag_a > mag_b) begin
                sum_mag = mag_a - mag_b;
                result_sign = a_signed < 0 ? 1 : 0;
            end else if (mag_b > mag_a) begin
                sum_mag = mag_b - mag_a;
                result_sign = b_signed < 0 ? 1 : 0;
            end else begin
                sum_mag = 0;
                result_sign = 0;
            end
            c = {result_sign, sum_mag[N-2:0]};
        end
    end
endmodule

