module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);
    reg [2:0] counter;
    reg a_sign, b_sign, z_sign;
    reg [7:0] a_exponent, b_exponent;
    reg [22:0] a_mantissa, b_mantissa;
    reg [23:0] a_mant, b_mant;
    reg [47:0] product;
    reg [7:0] exponent_sum;
    reg guard, round, sticky;
    reg [22:0] z_mantissa;

    always @(posedge clk) begin
        if (rst) begin
            counter <= 0;
            z <= 0;
        end else begin
            case (counter)
                0: begin

                    a_sign <= a[31];
                    b_sign <= b[31];
                    a_exponent <= a[30:23];
                    b_exponent <= b[30:23];
                    a_mantissa <= a[22:0];
                    b_mantissa <= b[22:0];


                    if ((a_exponent == 8'hff && a_mantissa != 0) ||
                        (b_exponent == 8'hff && b_mantissa != 0)) begin
                        z <= {1'b0, 8'hff, 23'h000001};
                        counter <= 0;
                    end

                    else if ((a_exponent == 8'hff || b_exponent == 8'hff)) begin
                        if ((a_exponent == 8'hff && b_exponent == 8'hff)) begin
                            z <= {a_sign ^ b_sign, 8'hff, 23'b0};
                        end else if ((a_exponent == 8'hff) != (b_exponent == 8'hff)) begin
                            z <= {a_sign ^ b_sign, 8'hff, 23'b0};
                        end else begin
                            z <= {1'b0, 8'hff, 23'h000001};
                        end
                        counter <= 0;
                    end

                    else if (a_exponent == 0 && a_mantissa == 0 && 
                             b_exponent == 0 && b_mantissa == 0) begin
                        z <= {a_sign ^ b_sign, 31'b0};
                        counter <= 0;
                    end

                    else begin

                        a_mant <= (a_exponent == 0) ? {1'b0, a_mantissa} : {1'b1, a_mantissa};
                        b_mant <= (b_exponent == 0) ? {1'b0, b_mantissa} : {1'b1, b_mantissa};
                        counter <= 1;
                    end
                end

                1: begin

                    product <= a_mant * b_mant;
                    exponent_sum <= a_exponent + b_exponent - 8'd127;
                    counter <= 2;
                end

                2: begin

                    if (product[47] && product[46]) begin
                        product <= product >> 1;
                        exponent_sum <= exponent_sum + 8'd1;
                    end

                    z_mantissa <= product[46:24];
                    {guard, round, sticky} = {product[23], product[22], |product[21:0]};
                    counter <= 3;
                end

                3: begin

                    if (guard && (round || sticky)) begin
                        if (z_mantissa[0]) begin
                            z_mantissa <= z_mantissa + 1;
                        end else begin
                            z_mantissa <= z_mantissa + 1;
                        end
                    end
                    counter <= 4;
                end

                4: begin

                    if (z_mantissa[23]) begin
                        z_mantissa <= z_mantissa >> 1;
                        exponent_sum <= exponent_sum + 8'd1;
                    end

                    if (exponent_sum >= 8'hfe) begin
                        z <= {z_sign, 8'hff, 23'b0};
                    end else if (exponent_sum > 0) begin
                        z <= {z_sign, exponent_sum[6:0], z_mantissa[22:0]};
                    end else begin
                        z <= {z_sign, 31'b0};
                    end
                    counter <= 0;
                end

                default: counter <= 0;
            endcase
