    case (current_state)
        IDLE: next_state = data_in ? S1 : IDLE;
        S1:   next_state = (data_in == 0) ? S2 : IDLE;
        S2:   next_state = (data_in == 0) ? S3 : S1;
        S3:   next_state = data_in ? S4 : IDLE;
        S4:   next_state = data_in ? S1 : IDLE;
        default: next_state = IDLE;
    endcase
end


always @(posedge clk or negedge reset_n) begin
    if (!reset_n) begin
        sequence_detected <= 0;
    end else begin
        sequence_detected <= (current_state == S4) ? 1'b1 : 1'b0;
    end
end

endmodule

