module traffic_light (
    input rst_n,
    input clk,
    input pass_request,
    output reg [7:0] clock,
    output reg red,
    output reg yellow,
    output reg green
);

    reg [7:0] counter;
    reg [1:0] state;


    parameter RED_STATE  = 2'b00,
              GREEN_STATE = 2'b01,
              YELLOW_STATE = 2'b10;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= RED_STATE;
            counter <= 10;
            {red, yellow, green} <= 3'b000;
            clock <= 10;
        end else begin
            clock <= counter;

            case (state)
                RED_STATE: begin
                    red <= 1;
                    yellow <= 0;
                    green <= 0;

                    if (counter == 0) begin
                        state <= GREEN_STATE;
                        counter <= 60;
                    end else begin
                        counter <= counter - 1;
                    end
                end

                GREEN_STATE: begin
                    red <= 0;
                    yellow <= 0;
                    green <= 1;

                    if (pass_request && counter > 10) begin
                        counter <= 10;
                    end else if (counter == 0) begin
                        state <= YELLOW_STATE;
                        counter <= 5;
                    end else begin
                        counter <= counter - 1;
                    end
                end

                YELLOW_STATE: begin
                    red <= 0;
                    yellow <= 1;
                    green <= 0;

                    if (counter == 0) begin
                        state <= RED_STATE;
                        counter <= 10;
                    end else begin
                        counter <= counter - 1;
                    end
                end

                default: state <= RED_STATE;
            endcase
        end
    end

endmodule

