module alu (
    input [31:0] a,
    input [31:0] b,
    input [5:0] aluc,
    output reg [31:0] r,
    output zero,
    output carry,
    output negative,
    output overflow,
    output reg flag
);


    parameter ADD  = 6'b100000;
    parameter ADDU = 6'b100001;
    parameter SUB  = 6'b100010;
    parameter SUBU = 6'b100011;
    parameter AND  = 6'b100100;
    parameter OR   = 6'b100101;
    parameter XOR  = 6'b100110;
    parameter NOR  = 6'b100111;
    parameter SLT  = 6'b101010;
    parameter SLTU = 6'b101011;
    parameter SLL  = 6'b000000;
    parameter SRL  = 6'b000010;
    parameter SRA  = 6'b000011;
    parameter SLLV = 6'b000100;
    parameter SRLV = 6'b000110;
    parameter SRAV = 6'b000111;
    parameter LUI  = 6'b001111;


    reg carry_reg;
    reg overflow_reg;


    assign zero = (r == 32'b0);


    assign negative = r[31];


    assign carry = carry_reg;


    assign overflow = overflow_reg;


    always @(*) begin
        flag = (aluc == SLT || aluc == SLTU) ? 1'b1 : 1'b0;
    end


    always @(*) begin
        r = 32'bz;

        carry_reg = 1'b0;
        overflow_reg = 1'b0;

        case (aluc)
            ADD: begin
                {carry_reg, r} = {1'b0, a} + {1'b0, b};
                overflow_reg = (a[31] == b[31]) && (r[31] != a[31]);
            end
            ADDU: {carry_reg, r} = {1'b0, a} + {1'b0, b};
            SUB: begin
                {carry_reg, r} = {1'b0, a} - {1'b0, b};
                overflow_reg = (a[31] != b[31]) && (r[31] != a[31]);
            end
            SUBU: {carry_reg, r} = {1'b0, a} - {1'b0, b};
            AND: r = a & b;
            OR: r = a | b;
            XOR: r = a ^ b;
            NOR: r = ~(a | b);
            SLT: r = ($signed(a) < $signed(b)) ? 32'b1 : 32'b0;
            SLTU: r = (a < b) ? 32'b1 : 32'b0;
            SLL: r = b << a[4:0];
            SRL: r = b >> a[4:0];
            SRA: r = $signed(b) >>> a[4:0];
            SLLV: r = b << a[4:0];
            SRLV: r = b >> a[4:0];
            SRAV: r = $signed(b) >>> a[4:0];
            LUI: r = {a[15:0], 16'b0};
            default: r = 32'bz;
        endcase
    end

endmodule

