module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

reg [3:0] cnt;
reg start_cnt;
reg [7:0] abs_dividend;
reg [7:0] abs_divisor;
reg [8:0] NEG_DIVISOR;

reg [16:0] SR;


always @(posedge clk) begin
    if (rst) begin
        res_valid <= 0;
        cnt <= 0;
        start_cnt <= 0;
        SR <= 0;
        abs_dividend <= 0;
        abs_divisor <= 0;
        NEG_DIVISOR <= 0;
    end else begin
        if (start_cnt) begin
            if (cnt == 8) begin

                res_valid <= 1;
                start_cnt <= 0;
                cnt <= 0;
                result <= {SR[8:1], SR[0]};

            end else begin

                if (SR[16:8] >= NEG_DIVISOR) begin
                    SR[16:8] <= SR[16:8] - NEG_DIVISOR;
                    SR <= {SR[7:0], 1'b1};
                end else begin
                    SR <= {SR[7:0], 1'b0};
                end
                cnt <= cnt + 1;
            end
        end else if (opn_valid && !res_valid) begin

            if (sign) begin
                abs_dividend <= (dividend[7]) ? -dividend : dividend;
                abs_divisor <= (divisor[7]) ? -divisor : divisor;
            end else begin
                abs_dividend <= dividend;
                abs_divisor <= divisor;
            end
            NEG_DIVISOR <= -abs_divisor;

            SR <= {abs_dividend, 1'b0};

            cnt <= 1;
            start_cnt <= 1;
        end else if (res_valid) begin
            res_valid <= 0;
        end
    end
end

