module div_16bit (
    input [15:0] A,
    input [7:0] B,
    output reg [15:0] result,
    output reg [15:0] odd
);

reg [15:0] a_reg;
reg [7:0] b_reg;
reg [7:0] rem;
reg [15:0] quo;


always @(*) begin
    a_reg = A;
    b_reg = B;
end


always @(*) begin
    rem = 0;
    quo = 0;

    for (integer i = 15;
 i >= 0;
 i = i - 1) begin
        rem = (rem << 1) | ((a_reg >> i) & 1);
        if (rem >= b_reg) begin
            quo = (quo << 1) | 1;
            rem = rem - b_reg;
        end else begin
            quo = quo << 1;
        end
    end

    result = quo;
    odd = {8'b0, rem};

end

endmodule

