module cla_16bit (
    input [15:0] A,
    input [15:0] B,
    input Cin,
    output [15:0] S,
    output G_group,
    output P_group,
    output Cout
);
    wire [15:0] G, P;
    wire [15:0] C;

    assign G = A & B;
    assign P = A ^ B;

    assign C[0] = G[0] | (P[0] & Cin);

    genvar i;
    generate
        for (i = 1;
 i < 16;
 i = i + 1) begin : carry_chain
            assign C[i] = G[i] | (P[i] & C[i-1]);
        end
    endgenerate

    assign S = P ^ C;

    wire [16:0] product_term;
    assign product_term[15] = 1'b1;

    genvar j;
    generate
        for (j = 14;
 j >= 0;
 j = j - 1) begin : product_terms
            assign product_term[j] = P[j+1] & product_term[j+1];
        end
    endgenerate

    reg G_group_reg;
    integer k;
    always @(*) begin
        G_group_reg = 1'b0;
        for (k = 0;
 k < 16;
 k = k + 1) begin
            G_group_reg = G_group_reg | (G[k] & product_term[k]);
        end
    end
    assign G_group = G_group_reg;

    assign P_group = &P;
    assign Cout = G_group | (P_group & Cin);
endmodule

