module fixed_point_subtractor #(
    parameter Q = 4,
    parameter N = 8
) (
    input [N-1:0] a,
    input [N-1:0] b,
    output reg [N-1:0] c
);

    reg a_sign, b_sign;
    reg [N-1:0] a_mag, b_mag;
    reg [N-1:0] res;
    reg sign;

    always @(*) begin
        a_sign = a[N-1];
        b_sign = b[N-1];
        a_mag = a_sign ? (~a + 1) : a;
        b_mag = b_sign ? (~b + 1) : b;

        if (a_sign == b_sign) begin
            res = a_mag - b_mag;
            sign = a_sign;
            if (res == 0) sign = 0;
        end else begin
            if (a_mag > b_mag) begin
                res = a_mag - b_mag;
                sign = a_sign;
            end else if (a_mag < b_mag) begin
                res = b_mag - a_mag;
                sign = b_sign;
            end else begin
                res = 0;
                sign = 0;
            end
        end

        c = {sign, res[N-2:0]};
    end

endmodule

