module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);

    reg [2:0] counter;
    reg a_sign, b_sign;
    reg [7:0] a_exponent, b_exponent;
    reg [22:0] a_mantissa, b_mantissa;
    reg [7:0] exp;
    reg [23:0] a_mant, b_mant;
    reg [49:0] product;
    reg guard, round, sticky;

    always @(posedge clk) begin
        if (rst) begin
            counter <= 3'b0;
            z <= 32'd0;
        end else begin
            case (counter)
                3'b000: begin
                    a_sign <= a[31];
                    b_sign <= b[31];
                    a_exponent <= a[30:23];
                    b_exponent <= b[30:23];
                    a_mantissa <= a[22:0];
                    b_mantissa <= b[22:0];


                    if ((a_exponent == 8'hff && a_mantissa != 0) || 
                        (b_exponent == 8'hff && b_mantissa != 0)) begin
                        z <= {1'b0, 8'hff, 23'h1};
                        counter <= 3'b000;
                    end

                    else if ((a_exponent == 8'hff && a_mantissa == 0) || 
                             (b_exponent == 8'hff && b_mantissa == 0)) begin
                        if ((a_exponent == 8'hff && b_exponent != 8'hff) || 
                            (b_exponent == 8'hff && a_exponent != 8'hff)) begin
                            z <= {a_sign ^ b_sign, 8'hff, 23'h0};
                        end else begin
                            z <= {1'b0, 8'hff, 23'h1};

                        end
                        counter <= 3'b000;
                    end

                    else if ((a_exponent == 8'h0 && a_mantissa == 0) || 
                             (b_exponent == 8'h0 && b_mantissa == 0)) begin
                        z <= {a_sign ^ b_sign, 8'h0, 23'h0};
                        counter <= 3'b000;
                    end
                    else begin

                        a_mant <= (a_exponent == 8'h0) ? {1'b0, a_mantissa} : {1'b1, a_mantissa};
                        b_mant <= (b_exponent == 8'h0) ? {1'b0, b_mantissa} : {1'b1, b_mantissa};

                        exp <= a_exponent + b_exponent - 8'd127;
                        counter <= 3'b001;
                    end
                end
                3'b001: begin

                    product <= a_mant * b_mant;
                    counter <= 3'b010;
                end
                3'b010: begin

                    if (product[49]) begin

                        product <= {1'b0, product[49:1]};
                        exp <= exp + 8'd1;
                    end


                    counter <= 3'b011;
                end
                3'b011: begin


                    z <= {a_sign ^ b_sign, exp[7:0], product[47:25]};
                    counter <= 3'b000;
                end
                default: begin
                    counter <= 3'b000;
                end
            endcase
        end
    end

endmodule

