module asyn_fifo #(
    parameter WIDTH = 8,
    parameter DEPTH = 16
) (
    input wclk,
    input wrstn,
    input winc,
    input [WIDTH-1:0] wdata,
    output wfull,
    input rclk,
    input rrstn,
    input rinc,
    output rempty,
    output [WIDTH-1:0] rdata
);

localparam PTR_WIDTH = $clog2(DEPTH) + 1;
localparam ADDR_WIDTH = $clog2(DEPTH);


reg [PTR_WIDTH-1:0] wptr_bin, wptr_bin_next;
wire [PTR_WIDTH-1:0] wptr_gray = (wptr_bin >> 1) ^ wptr_bin;


reg [PTR_WIDTH-1:0] rptr_bin, rptr_bin_next;
wire [PTR_WIDTH-1:0] rptr_gray = (rptr_bin >> 1) ^ rptr_bin;


reg [PTR_WIDTH-1:0] rptr_gray_sync1, rptr_gray_sync2;
always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) begin
        rptr_gray_sync1 <= 0;
        rptr_gray_sync2 <= 0;
    end else begin
        rptr_gray_sync1 <= rptr_gray;
        rptr_gray_sync2 <= rptr_gray_sync1;
    end
end


reg [PTR_WIDTH-1:0] rptr_bin_sync;
always @(posedge wclk or negedge wrstn) begin
    if (!wrstn)
        rptr_bin_sync <= 0;
    else
        rptr_bin_sync <= (rptr_gray_sync2 >> 1) ^ rptr_gray_sync2;
end


reg [PTR_WIDTH-1:0] wptr_gray_sync1, wptr_gray_sync2;
always @(posedge rclk or negedge rrstn) begin
    if (!rrstn) begin
        wptr_gray_sync1 <= 0;
        wptr_gray_sync2 <= 0;
    end else begin
        wptr_gray_sync1 <= wptr_gray;
        wptr_gray_sync2 <= wptr_gray_sync1;
    end
end


reg [PTR_WIDTH-1:0] wptr_bin_sync;
always @(posedge rclk or negedge rrstn) begin
    if (!rrstn)
        wptr_bin_sync <= 0;
    else
        wptr_bin_sync <= (wptr_gray_sync2 >> 1) ^ wptr_gray_sync2;
end


wire wfull_next = (wptr_bin - rptr_bin_sync) == DEPTH;
assign wfull = wfull_next;


wire rempty_next = (rptr_bin == wptr_bin_sync);
assign rempty = rempty_next;


dual_port_RAM #(
    .WIDTH(WIDTH),
    .DEPTH(DEPTH)
) ram (
    .wclk(wclk),
    .wenc(wfull ? 0 : winc),
    .waddr(wptr_bin[ADDR_WIDTH-1:0]),
    .wdata(wdata),
    .rclk(rclk),
    .renc(rempty ? 0 : rinc),
    .raddr(rptr_bin[ADDR_WIDTH-1:0]),
    .rdata(rdata)
);


always @(posedge wclk or negedge wrstn) begin
    if (!wrstn)
        wptr_bin <= 0;
    else
        wptr_bin <= wptr_bin_next;
end

always @* begin
    if (!wrstn)
        wptr_bin_next = 0;
    else if (winc && !wfull)
        wptr_bin_next = wptr_bin + 1;
    else
        wptr_bin_next = wptr_bin;
end


always @(posedge rclk or negedge rrstn) begin
    if (!rrstn)
        rptr_bin <= 0;
    else
        rptr_bin <= rptr_bin_next;
end

always @* begin
    if (!rrstn)
        rptr_bin_next = 0;
    else if (rinc && !rempty)
        rptr_bin_next = rptr_bin + 1;
    else
        rptr_bin_next = rptr_bin;
end

endmodule


module dual_port_RAM #(
    parameter WIDTH = 8,
    parameter DEPTH = 16
) (
    input wclk,
    input wenc,
    input [$clog2(DEPTH)-1:0] waddr,
    input [WIDTH-1:0] wdata,
    input rclk,
    input renc,
    input [$clog2(DEPTH)-1:0] raddr,
    output reg [WIDTH-1:0] rdata
);

reg [WIDTH-1:0] RAM_MEM [0:DEPTH-1];


always @(posedge wclk) begin
    if (wenc)
        RAM_MEM[waddr] <= wdata;
end


always @(posedge rclk) begin
    if (renc)
        rdata <= RAM_MEM[raddr];
end

endmodule

