module traffic_light (
    input        rst_n,
    input        clk,
    input        pass_request,
    output [7:0] clock,
    output       red,
    output       yellow,
    output       green
);


    parameter IDLE     = 2'b00;
    parameter S1_RED   = 2'b01;
    parameter S2_YELLOW= 2'b10;
    parameter S3_GREEN = 2'b11;

    reg [1:0] state, next_state;
    reg [7:0] cnt;
    reg p_red, p_yellow, p_green;


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
        end else begin
            state <= next_state;
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cnt <= 8'd10;
        end else begin
            case (state)
                IDLE:       cnt <= 8'd10;
                S1_RED:     if (cnt == 0) cnt <= 8'd60;
                            else         cnt <= cnt - 1;
                S3_GREEN:   if (pass_request && p_green && cnt > 8'd10)
                                cnt <= 8'd10;
                            else if (cnt == 0)
                                cnt <= 8'd5;
                            else
                                cnt <= cnt - 1;
                S2_YELLOW:  if (cnt == 0) cnt <= 8'd10;
                            else         cnt <= cnt - 1;
                default:    cnt <= 8'd10;
            endcase
        end
    end


    always @(*) begin
        case (state)
            IDLE:       next_state = S1_RED;
            S1_RED:     next_state = (cnt == 0) ? S3_GREEN : S1_RED;
            S3_GREEN:   next_state = (cnt == 0) ? S2_YELLOW : S3_GREEN;
            S2_YELLOW:  next_state = (cnt == 0) ? S1_RED : S2_YELLOW;
            default:    next_state = IDLE;
        endcase
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            p_red <= 1'b0;
            p_yellow <= 1'b0;
            p_green <= 1'b0;
        end else begin
            case (state)
                IDLE: begin
                    p_red <= 1'b0;
                    p_yellow <= 1'b0;
                    p_green <= 1'b0;
                end
                S1_RED: begin
                    p_red <= 1'b1;
                    p_yellow <= 1'b0;
                    p_green <= 1'b0;
                end
                S2_YELLOW: begin
                    p_red <= 1'b0;
                    p_yellow <= 1'b1;
                    p_green <= 1'b0;
                end
                S3_GREEN: begin
                    p_red <= 1'b0;
                    p_yellow <= 1'b0;
                    p_green <= 1'b1;
                end
                default: begin
                    p_red <= 1'b0;
                    p_yellow <= 1'b0;
                    p_green <= 1'b0;
                end
            endcase
        end
    end


    assign clock = cnt;


    assign red    = p_red;
    assign yellow = p_yellow;
    assign green  = p_green;

endmodule

