module width_8to16 (
    input clk,
    input rst_n,
    input valid_in,
    input [7:0] data_in,
    output reg valid_out = 0,
    output reg [15:0] data_out = 0
);

    reg [7:0] first_data;
    reg [1:0] state;
    localparam IDLE = 0;
    localparam FIRST_RECEIVED = 1;
    localparam WAIT_TO_OUTPUT = 2;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            first_data <= 0;
            valid_out <= 0;
            data_out <= 0;
        end else begin
            case (state)
                IDLE: begin
                    valid_out <= 0;
                    if (valid_in) begin
                        first_data <= data_in;
                        state <= FIRST_RECEIVED;
                    end
                end
                FIRST_RECEIVED: begin
                    if (valid_in) begin
                        data_out <= {first_data, data_in};
                        state <= WAIT_TO_OUTPUT;
                    end
                end
                WAIT_TO_OUTPUT: begin
                    valid_out <= 1;
                    state <= IDLE;
                end
                default: state <= IDLE;
            endcase
        end
    end

endmodule

