module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

    reg [15:0] SR;

    reg [3:0] cnt;
    reg start;
    reg [7:0] quotient;
    reg [7:0] remainder;
    reg sign_dividend, sign_divisor;
    reg [7:0] divisor_abs;
    reg [7:0] dividend_abs;
    reg [7:0] neg_divisor;

    always @(posedge clk) begin
        if (rst) begin
            res_valid <= 0;
            SR <= 16'b0;
            cnt <= 0;
            start <= 0;
            result <= 16'b0;
            sign_dividend <= 0;
            sign_divisor <= 0;
            quotient <= 0;
            remainder <= 0;
            dividend_abs <= 0;
            divisor_abs <= 0;
            neg_divisor <= 0;
        end else begin
            if (opn_valid && !res_valid) begin

                sign_dividend <= sign ? dividend[7] : 0;
                sign_divisor <= sign ? divisor[7] : 0;
                dividend_abs <= sign ? (dividend[7] ? -dividend : dividend) : dividend;
                divisor_abs <= sign ? (divisor[7] ? -divisor : divisor) : divisor;
                neg_divisor <= -divisor_abs;

                SR <= {8'b0, dividend_abs << 1};
                cnt <= 1;
                start <= 1;
                res_valid <= 0;
            end else if (start && !res_valid) begin
                if (cnt <= 8) begin

                    {remainder, quotient} = SR;
                    if (remainder >= neg_divisor) begin
                        remainder = remainder - neg_divisor;
                        quotient = {quotient[6:0], 1'b1};
                    end else begin
                        remainder = remainder;
                        quotient = {quotient[6:0], 1'b0};
                    end
                    SR <= {remainder, quotient};
                    cnt <= cnt + 1;
                end else begin
                    start <= 0;

                    if (sign) begin
                        if (sign_dividend ^ sign_divisor) quotient = -quotient;
                        if (sign_dividend) remainder = -remainder;
                    end

                    result <= {remainder, quotient};
                    res_valid <= 1;
                end
            end else if (res_valid) begin
                res_valid <= 0;
            end
        end
    end

endmodule

