module comparator_4bit (
    input [3:0] A,
    input [3:0] B,
    output A_greater,
    output A_equal,
    output A_less
);

    wire eq3, eq2, eq1, eq0;
    wire gt3, gt2, gt1, gt0;


    assign eq3 = (A[3] == B[3]);
    assign gt3 = (A[3] > B[3]);


    assign eq2 = eq3 & (A[2] == B[2]);
    assign gt2 = eq3 & (A[2] > B[2]);


    assign eq1 = eq2 & (A[1] == B[1]);
    assign gt1 = eq2 & (A[1] > B[1]);


    assign eq0 = eq1 & (A[0] == B[0]);
    assign gt0 = eq1 & (A[0] > B[0]);


    assign A_greater = gt3 | gt2 | gt1 | gt0;


    assign A_equal = eq3 & eq2 & eq1 & eq0;


    assign A_less = ~(A_greater | A_equal);

endmodule

