module cla_4bit (
    input [4:1] A,
    input [4:1] B,
    input cin,
    output [4:1] S,
    output cout
);
    wire [3:1] G, P;
    wire [4:1] C;

    assign G = A & B;
    assign P = A ^ B;

    assign C[1] = G[1] | (P[1] & cin);
    assign C[2] = G[2] | (P[2] & G[1]) | (P[2] & P[1] & cin);
    assign C[3] = G[3] | (P[3] & G[2]) | (P[3] & P[2] & G[1]) | (P[3] & P[2] & P[1] & cin);
    assign cout = G[4] | (P[4] & G[3]) | (P[4] & P[3] & G[2]) | (P[4] & P[3] & P[2] & G[1]) | (P[4] & P[3] & P[2] & P[1] & cin);

    assign S[1] = P[1] ^ cin;
    assign S[2] = P[2] ^ C[1];
    assign S[3] = P[3] ^ C[2];
    assign S[4] = P[4] ^ C[3];
endmodule

