module fixed_point_adder #(
    parameter Q = 4,
    parameter N = 8
) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output reg [N-1:0] c
);

reg [N-1:0] res;

always @(*) begin
    if (a[N-1] == b[N-1]) begin
        res = a + b;
    end else begin
        if ($signed(a) > $signed(b)) begin
            res = a - b;
        end else begin
            res = b - a;
        end
    end
    c = res;
end

endmodule

