module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);

    reg [2:0] counter;
    reg a_sign, b_sign, z_sign;
    reg [7:0] a_exponent, b_exponent, combined_exponent;
    reg [22:0] a_fraction, b_fraction;
    reg [23:0] a_mantissa, b_mantissa;
    reg [47:0] product;
    reg [5:0] lzc;
    reg [47:0] shifted_product;
    reg [22:0] z_mantissa;
    reg guard, round, sticky;
    reg overflow, underflow;

    always @(posedge clk) begin
        if (rst) begin
            counter <= 3'b0;
            z <= 32'b0;
        end else begin
            case (counter)
                0: begin

                    a_sign <= a[31];
                    b_sign <= b[31];
                    a_exponent <= a[30:23];
                    b_exponent <= b[30:23];
                    a_fraction <= a[22:0];
                    b_fraction <= b[22:0];


                    if ((a_exponent == 8'hff && a_fraction != 0) ||
                        (b_exponent == 8'hff && b_fraction != 0)) begin
                        z <= {a_sign ^ b_sign, 8'hff, 23'h1};
                        counter <= 0;
                    end

                    else if ((a_exponent == 8'hff) || (b_exponent == 8'hff)) begin
                        z <= {a_sign ^ b_sign, 8'hff, 23'h0};
                        counter <= 0;
                    end

                    else if ((a_exponent == 0 && a_fraction == 0) ||
                             (b_exponent == 0 && b_fraction == 0)) begin
                        z <= {a_sign ^ b_sign, 8'h0, 23'h0};
                        counter <= 0;
                    end else begin

                        a_mantissa <= (a_exponent == 0) ? {1'b0, a_fraction} : {1'b1, a_fraction};
                        b_mantissa <= (b_exponent == 0) ? {1'b0, b_fraction} : {1'b1, b_fraction};
                        combined_exponent <= a_exponent + b_exponent - 127;
                        counter <= 1;
                    end
                end
                1: begin

                    product <= a_mantissa * b_mantissa;
                    counter <= 2;
                end
                2: begin

                    lzc = 0;
                    for (integer i = 47;
 i >= 0;
 i = i - 1) begin
                        if (product[i]) begin
                            lzc = 47 - i;
                            break;
                        end
                    end
                    shifted_product = product << lzc;


                    z_mantissa = shifted_product[46:24];
                    guard = shifted_product[23];
                    round = shifted_product[22];
                    sticky = |shifted_product[21:0];
                    counter <= 3;
                end
                3: begin

                    if (guard) begin
                        if (round || sticky || (z_mantissa[0])) begin
                            z_mantissa = z_mantissa + 1;
                        end
                        if (z_mantissa == 24'h1000000) begin 
                            z_mantissa = 23'b0;
                            combined_exponent = combined_exponent + 1;
                        end
                    end
                    counter <= 4;
                end
                4: begin

                    if (combined_exponent >= 255) begin
                        overflow = 1;
                        z <= {a_sign ^ b_sign, 8'hff, 23'b0};
                    end else if (combined_exponent <= 0) begin
                        underflow = 1;
                        z <= {a_sign ^ b_sign, 8'h0, z_mantissa};
                    end else begin
                        z <= {a_sign ^ b_sign, combined_exponent[7:0], z_mantissa[22:0]};
                    end
                    counter <= 0;
                end
            endcase
        end
    end

endmodule

