module asyn_fifo #(
    parameter WIDTH = 8,
    parameter DEPTH = 16
) (
    input wire wclk,
    input wire winc,
    input wire [WIDTH-1:0] wdata,
    input wire wrstn,
    input wire rclk,
    input wire rinc,
    input wire rrstn,
    output wire wfull,
    output wire rempty,
    output wire [WIDTH-1:0] rdata
);

    localparam ADDR_BITS = $clog2(DEPTH);
    localparam PTR_WIDTH = ADDR_BITS + 1;

    wire [ADDR_BITS-1:0] waddr_ram, raddr_ram;
    wire wen, ren;

    dual_port_RAM #(
        .DEPTH(DEPTH),
        .WIDTH(WIDTH)
    ) ram (
        .wclk(wclk),
        .waddr(waddr_ram),
        .wdata(wdata),
        .wen(wen),
        .rclk(rclk),
        .raddr(raddr_ram),
        .ren(ren),
        .rdata(rdata)
    );

    reg [PTR_WIDTH-1:0] waddr_bin, raddr_bin;
    wire [PTR_WIDTH-1:0] wgray = waddr_bin ^ (waddr_bin >> 1);
    wire [PTR_WIDTH-1:0] rgray = raddr_bin ^ (raddr_bin >> 1);

    reg [PTR_WIDTH-1:0] wgray_sync1, wgray_sync2;
    reg [PTR_WIDTH-1:0] rgray_sync1, rgray_sync2;

    always @(posedge rclk or negedge rrstn) begin
        if (!rrstn) begin
            wgray_sync1 <= 0;
            wgray_sync2 <= 0;
        end else begin
            wgray_sync1 <= wgray;
            wgray_sync2 <= wgray_sync1;
        end
    end

    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn) begin
            rgray_sync1 <= 0;
            rgray_sync2 <= 0;
        end else begin
            rgray_sync1 <= rgray;
            rgray_sync2 <= rgray_sync1;
        end
    end

    assign wfull = (wgray == {~wgray_sync2[PTR_WIDTH-1:PTR_WIDTH-2], wgray_sync2[PTR_WIDTH-3:0]});
    assign rempty = (rgray == wgray_sync2);

    assign wen = winc && !wfull;
    assign ren = rinc && !rempty;

    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn) begin
            waddr_bin <= 0;
        end else if (wen) begin
            waddr_bin <= waddr_bin + 1;
        end
    end

    always @(posedge rclk or negedge rrstn) begin
        if (!rrstn) begin
            raddr_bin <= 0;
        end else if (ren) begin
            raddr_bin <= raddr_bin + 1;
        end
    end

    assign waddr_ram = waddr_bin[ADDR_BITS-1:0];
    assign raddr_ram = raddr_bin[ADDR_BITS-1:0];

