reg [3:0] SP;


always @(posedge Clk) begin
    if (Rst) begin

        stack_mem[0] <= 0;
        stack_mem[1] <= 0;
        stack_mem[2] <= 0;
        stack_mem[3] <= 0;
        SP <= 4;
    end else if (EN) begin
        if (RW) begin

            if (!EMPTY) begin
                dataOut <= stack_mem[SP-1];
                stack_mem[SP-1] <= 0;

                SP <= SP + 1;
            end
        end else begin

            if (!FULL) begin
                stack_mem[SP-1] <= dataIn;
                SP <= SP - 1;
            end
        end
    end
