module traffic_light (
    input rst_n,
    input clk,
    input pass_request,
    output reg [7:0] clock,
    output reg red,
    output reg yellow,
    output reg green
);


localparam IDLE      = 2'b00,
           RED_ST    = 2'b01,
           GREEN_ST  = 2'b10,
           YELLOW_ST = 2'b11;

reg [1:0] state, next_state;
reg [7:0] cnt;


always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
    end else begin
        state <= next_state;
    end
end


always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        cnt <= 10;
    end else begin
        if (pass_request && (state == GREEN_ST) && (cnt > 10)) begin
            cnt <= 10;
        end else if ((state != next_state) && (next_state != IDLE)) begin
            case (next_state)
                RED_ST:    cnt <= 10;
                GREEN_ST:  cnt <= 60;
                YELLOW_ST: cnt <= 5;
                default:   cnt <= 10;
            endcase
        end else if (cnt > 0) begin
            cnt <= cnt - 1;
        end
    end
end


always @(*) begin
    case (state)
        IDLE:      next_state = RED_ST;
        RED_ST:    next_state = (cnt == 0) ? GREEN_ST : RED_ST;
        GREEN_ST:  next_state = (cnt == 0) ? YELLOW_ST : GREEN_ST;
        YELLOW_ST: next_state = (cnt == 0) ? RED_ST : YELLOW_ST;
        default:   next_state = IDLE;
    endcase
end


always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        {red, yellow, green} <= 3'b000;
    end else begin
        case (state)
            RED_ST:    {red, yellow, green} <= 3'b100;
            GREEN_ST:  {red, yellow, green} <= 3'b001;
            YELLOW_ST: {red, yellow, green} <= 3'b010;
            default:   {red, yellow, green} <= 3'b000;
        endcase
    end
end

assign clock = cnt;

endmodule

