module edge_detect (
    input clk,
    input rst_n,
    input a,
    output reg rise,
    output reg down
);

reg a_prev;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        a_prev <= 0;
        rise <= 0;
        down <= 0;
    end else begin

        if (a_prev == 0 && a == 1) begin
            rise <= 1;
            down <= 0;
        end else if (a_prev == 1 && a == 0) begin
            down <= 1;
            rise <= 0;
        end else begin
            rise <= 0;
            down <= 0;
        end

        a_prev <= a;
    end
end

endmodule

