module alu (
    input [31:0] a,
    input [31:0] b,
    input [5:0] aluc,
    output reg [31:0] r = 0,
    output zero,
    output reg carry = 0,
    output reg negative = 0,
    output reg overflow = 0,
    output flag
);

    parameter ADD  = 6'b100000;
    parameter ADDU = 6'b100001;
    parameter SUB  = 6'b100010;
    parameter SUBU = 6'b100011;
    parameter AND  = 6'b100100;
    parameter OR   = 6'b100101;
    parameter XOR  = 6'b100110;
    parameter NOR  = 6'b100111;
    parameter SLT  = 6'b101010;
    parameter SLTU = 6'b101011;
    parameter SLL  = 6'b000000;
    parameter SRL  = 6'b000010;
    parameter SRA  = 6'b000011;
    parameter SLLV = 6'b000100;
    parameter SRLV = 6'b000110;
    parameter SRAV = 6'b000111;
    parameter LUI  = 6'b001111;

    wire signed_lt = ($signed(a) < $signed(b));
    wire unsigned_lt = (a < b);

    assign flag = (aluc == SLT) ? signed_lt :
                  (aluc == SLTU) ? unsigned_lt :
                  1'bz;

    assign zero = (r == 32'b0);

    always @(*) begin
        carry = 0;
        overflow = 0;
        r = 32'bz;

        case (aluc)
            ADD: begin
                r = a + b;
                carry = (a + b) >> 32;
                overflow = (a[31] == b[31]) && (r[31] != a[31]);
            end
            ADDU: begin
                r = a + b;
                carry = (a + b) >> 32;
            end
            SUB: begin
                r = a - b;
                carry = (a >= b);
                overflow = (a[31] != b[31]) && (r[31] != a[31]);
            end
            SUBU: begin
                r = a - b;
                carry = (a >= b);
            end
            AND: begin
                r = a & b;
            end
            OR: begin
                r = a | b;
            end
            XOR: begin
                r = a ^ b;
            end
            NOR: begin
                r = ~(a | b);
            end
            SLT: begin
                r = {31'b0, signed_lt};
            end
            SLTU: begin
                r = {31'b0, unsigned_lt};
            end
            SLL: begin
                r = b << a[4:0];
            end
            SRL: begin
                r = b >> a[4:0];
            end
            SRA: begin
                r = $signed(b) >>> a[4:0];
            end
            SLLV: begin
                r = b << a[4:0];
            end
            SRLV: begin
                r = b >> a[4:0];
            end
            SRAV: begin
                r = $signed(b) >>> a[4:0];
            end
            LUI: begin
                r = {a[15:0], 16'b0};
            end
            default: r = 32'bz;
        endcase
    end
endmodule

