module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

    reg [7:0] abs_dividend, abs_divisor;
    reg sign_quotient, sign_remainder;
    reg [15:0] SR;
    reg [3:0] cnt;
    reg processing;

    always @(posedge clk) begin
        if (rst) begin
            res_valid <= 0;
            result <= 0;
            abs_dividend <= 0;
            abs_divisor <= 0;
            sign_quotient <= 0;
            sign_remainder <= 0;
            SR <= 0;
            cnt <= 0;
            processing <= 0;
        end else begin
            if (opn_valid && !res_valid && !processing) begin

                if (sign) begin
                    abs_dividend <= dividend[7] ? (-dividend) : dividend;
                    abs_divisor <= divisor[7] ? (-divisor) : divisor;
                    sign_quotient <= (dividend[7] ^ divisor[7]);
                    sign_remainder <= dividend[7];
                end else begin
                    abs_dividend <= dividend;
                    abs_divisor <= divisor;
                    sign_quotient <= 0;
                    sign_remainder <= 0;
                end


                SR <= {8'b0, abs_dividend} << 1;
                cnt <= 0;
                processing <= 1;
                res_valid <= 0;
            end else if (processing) begin
                if (cnt < 8) begin

                    if (SR[15:8] >= abs_divisor) begin
                        SR[15:8] <= SR[15:8] - abs_divisor;
                        SR[0] <= 1;
                    end else begin
                        SR[0] <= 0;
                    end
                    SR <= SR << 1;
                    cnt <= cnt + 1;
                end else begin

                    reg [7:0] final_remainder = SR[15:8];
                    reg [7:0] final_quotient = SR[7:0];

                    if (sign) begin
                        if (sign_quotient)
                            final_quotient = -final_quotient;
                        if (sign_remainder)
                            final_remainder = -final_remainder;
                    end

                    result <= {final_remainder, final_quotient};
                    res_valid <= 1;
                    processing <= 0;
                end
            end


            if (res_valid && opn_valid && !processing) begin
                res_valid <= 0;
            end
        end
    end

endmodule

