    if (!rst_n) begin
        accumulated_sum <= 10'b0;
        counter <= 2'b0;
        valid_out <= 1'b0;
        data_out <= 10'b0;
    end else begin
        valid_out <= 1'b0;
        if (valid_in) begin
            if (counter == 2'b11) begin
                data_out <= accumulated_sum + data_in;
                accumulated_sum <= 10'b0;
                counter <= 2'b0;
                valid_out <= 1'b1;
            end else begin
                accumulated_sum <= accumulated_sum + data_in;
                counter <= counter + 1'b1;
            end
        end
    end
end

endmodule

