module fixed_point_adder #(
    parameter Q = 8, 
    parameter N = 16 
) (
    input [N-1:0] a,
    input [N-1:0] b,
    output [N-1:0] c
);

    reg signed [N-1:0] a_signed, b_signed;
    reg signed [N-1:0] res;

    always @(*) begin
        a_signed = a;
        b_signed = b;

        if (a_signed[N-1] == b_signed[N-1]) begin

            res = a_signed + b_signed;
        end else begin

            if (a_signed >= b_signed) begin
                res = a_signed - b_signed;
            end else begin
                res = b_signed - a_signed;
            end
        end
    end

    assign c = res;

endmodule

