module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);
    reg [2:0] counter;
    reg a_sign, b_sign;
    reg [7:0] a_exponent, b_exponent;
    reg [22:0] a_mantissa, b_mantissa;
    reg [47:0] product;
    reg [47:0] normalized_product;
    reg guard, round, sticky;
    reg [9:0] exponent;
    reg is_nan, is_inf, is_zero;
    reg [23:0] mantissa;

    reg a_is_zero, b_is_zero;
    reg a_is_inf, b_is_inf;
    reg a_is_nan, b_is_nan;

    always @(posedge clk) begin
        if (rst) begin
            counter <= 0;
            z <= 0;
            a_sign <= 0;
            b_sign <= 0;
            a_exponent <= 0;
            b_exponent <= 0;
            a_mantissa <= 0;
            b_mantissa <= 0;
            product <= 0;
            normalized_product <= 0;
            exponent <= 0;
            is_nan <= 0;
            is_inf <= 0;
            is_zero <= 0;
            guard <= 0;
            round <= 0;
            sticky <= 0;
            mantissa <= 0;
            a_is_zero <= 0;
            b_is_zero <= 0;
            a_is_inf <= 0;
            b_is_inf <= 0;
            a_is_nan <= 0;
            b_is_nan <= 0;
        end else begin
            case (counter)
                0: begin

                    a_sign <= a[31];
                    b_sign <= b[31];
                    a_exponent <= a[30:23];
                    b_exponent <= b[30:23];
                    a_mantissa <= (a[30:23] != 0) ? {1'b1, a[22:0]} : {1'b0, a[22:0]};
                    b_mantissa <= (b[30:23] != 0) ? {1'b1, b[22:0]} : {1'b0, b[22:0]};

                    a_is_inf <= (a[30:23] == 8'hFF) && (a_mantissa == 23'b0);
                    b_is_inf <= (b[30:23] == 8'hFF) && (b_mantissa == 23'b0);
                    a_is_nan <= (a[30:23] == 8'hFF) && (a_mantissa != 23'b0);
                    b_is_nan <= (b[30:23] == 8'hFF) && (b_mantissa != 23'b0);

                    a_is_zero <= (a[30:23] == 0) && (a_mantissa == 23'b0);
                    b_is_zero <= (b[30:23] == 0) && (b_mantissa == 23'b0);

                    is_nan <= a_is_nan || b_is_nan;
                    is_inf <= (a_is_inf || b_is_inf) && !(a_is_zero || b_is_zero);
                    is_zero <= (a_is_zero || b_is_zero) && !(a_is_inf || b_is_inf);

                    counter <= 1;
                end

                1: begin

                    product <= a_mantissa * b_mantissa;
                    counter <= 2;
                end

                2: begin

                    if (product[47]) begin
                        normalized_product <= {1'b0, product[47:1]};
                        exponent <= (a_exponent + b_exponent - 8'd127) + 10'd1;
                    end else begin
                        normalized_product <= product;
                        exponent <= a_exponent + b_exponent - 8'd127;
                    end


                    guard <= product[0];
                    round <= product[1];
                    sticky <= |product[46:2];
                    counter <= 3;
                end

                3: begin

                    if (guard && (round || sticky)) begin
                        mantissa <= normalized_product[46:23] + 1;
                        if (mantissa[23]) begin
                            mantissa <= {1'b0, mantissa[22:0]};
                            exponent <= exponent + 1;
                        end
                    end else begin
                        mantissa <= normalized_product[46:23];
                    end
                    counter <= 4;
                end

                4: begin

                    if (exponent >= 10'hFF) begin
                        z <= {a_sign ^ b_sign, 8'hFF, 23'b0};
                    end else if (exponent <= 0) begin
                        z <= {a_sign ^ b_sign, 31'b0};
                    end else begin
                        z <= {a_sign ^ b_sign, exponent[7:0], mantissa[22:0]};
                    end
                    counter <= 0;
                end

                default: counter <= 0;
            endcase
        end
    end
endmodule

