module asyn_fifo #(
    parameter WIDTH = 8,
    parameter DEPTH = 16
) (
    input wire wclk,
    input wire wrstn,
    input wire [WIDTH-1:0] wdata,
    input wire winc,
    input wire rclk,
    input wire rrstn,
    input wire rinc,
    output wire wfull,
    output wire rempty,
    output wire [WIDTH-1:0] rdata
);

localparam n = $clog2(DEPTH);


reg [n:0] waddr_bin;
wire [n:0] wptr_gray = waddr_bin ^ (waddr_bin >> 1);


reg [n:0] raddr_bin;
wire [n:0] rptr_gray = raddr_bin ^ (raddr_bin >> 1);


wire [$clog2(DEPTH)-1:0] waddr = waddr_bin[$clog2(DEPTH)-1:0];
wire [$clog2(DEPTH)-1:0] raddr = raddr_bin[$clog2(DEPTH)-1:0];


dual_port_RAM #(
    .WIDTH(WIDTH),
    .DEPTH(DEPTH)
) ram (
    .wclk(wclk),
    .wenc(winc && !wfull),
    .waddr(waddr),
    .wdata(wdata),
    .rclk(rclk),
    .renc(rinc && !rempty),
    .raddr(raddr),
    .rdata(rdata)
);


reg [n:0] wptr_gray_sync_1, wptr_gray_sync;

always @(posedge rclk or negedge rrstn) begin
    if (!rrstn) begin
        wptr_gray_sync_1 <= 0;
        wptr_gray_sync <= 0;
    end else begin
        wptr_gray_sync_1 <= wptr_gray;
        wptr_gray_sync <= wptr_gray_sync_1;
    end
end


reg [n:0] rptr_gray_sync_1, rptr_gray_sync;

always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) begin
        rptr_gray_sync_1 <= 0;
        rptr_gray_sync <= 0;
    end else begin
        rptr_gray_sync_1 <= rptr_gray;
        rptr_gray_sync <= rptr_gray_sync_1;
    end
end


assign wfull = (wptr_gray[n] != rptr_gray_sync[n]) &&
               (wptr_gray[n-1] != rptr_gray_sync[n-1]) &&
               (wptr_gray[n-2:0] == rptr_gray_sync[n-2:0]);

assign rempty = (rptr_gray == wptr_gray_sync);


always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) begin
        waddr_bin <= 0;
    end else if (winc && !wfull) begin
        waddr_bin <= waddr_bin + 1;
    end
end

always @(posedge rclk or negedge rrstn) begin
    if (!rrstn) begin
        raddr_bin <= 0;
    end else if (rinc && !rempty) begin
        raddr_bin <= raddr_bin + 1;
    end
end

endmodule

