module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);


localparam IDLE = 2'b00;
localparam LATCH = 2'b01;
localparam DIVIDE = 2'b10;
localparam ADJUST = 2'b11;

reg [1:0] state;


reg [7:0] abs_dividend, abs_divisor;
reg sign_dividend, sign_divisor;

reg [8:0] remainder;
reg [7:0] quotient;
reg [3:0] counter;


wire [8:0] temp_remainder = {remainder[7:0], quotient[7]} - abs_divisor;


always @(posedge clk) begin
    if (rst) begin
        state <= IDLE;
        res_valid <= 0;
        result <= 0;
        remainder <= 0;
        quotient <= 0;
        counter <= 0;
        sign_dividend <= 0;
        sign_divisor <= 0;
        abs_dividend <= 0;
        abs_divisor <= 0;
    end else begin
        case (state)
            IDLE: begin
                res_valid <= 0;
                if (opn_valid && !res_valid) begin

                    if (sign) begin
                        sign_dividend <= dividend[7];
                        sign_divisor <= divisor[7];
                        abs_dividend <= dividend[7] ? -dividend : dividend;
                        abs_divisor <= divisor[7] ? -divisor : divisor;
                    end else begin
                        sign_dividend <= 0;
                        sign_divisor <= 0;
                        abs_dividend <= dividend;
                        abs_divisor <= divisor;
                    end
                    state <= LATCH;
                end
            end

            LATCH: begin
                remainder <= 9'b0;
                quotient <= abs_dividend;
                counter <= 0;
                state <= DIVIDE;
            end

            DIVIDE: begin
                if (counter < 8) begin
                    if (temp_remainder[8] == 0) begin
                        remainder <= temp_remainder[7:0];
                        quotient <= {quotient[6:0], 1'b1};
                    end else begin
                        remainder <= {remainder[7:0], quotient[7]};
                        quotient <= {quotient[6:0], 1'b0};
                    end
                    counter <= counter + 1;
                end else begin
                    state <= ADJUST;
                end
            end

            ADJUST: begin

                reg [7:0] adjusted_quotient, adjusted_remainder;

                adjusted_quotient = (sign_dividend ^ sign_divisor) ? -quotient : quotient;
                adjusted_remainder = sign_dividend ? -remainder[7:0] : remainder[7:0];

                result <= {adjusted_remainder, adjusted_quotient};
                res_valid <= 1;
                state <= IDLE;
            end

            default: state <= IDLE;
        endcase
    end
end

endmodule

