module div_16bit (
    input [15:0] A,
    input [7:0] B,
    output reg [15:0] result,
    output reg [15:0] odd
);

reg [15:0] a_reg;
reg [7:0] b_reg;


always @(*) begin
    a_reg = A;
    b_reg = B;
end


always @(*) begin
    reg [15:0] dividend = a_reg;
    reg [7:0] divisor = b_reg;
    reg [15:0] remainder;
    reg [15:0] quotient;
    integer i;

    remainder = 0;
    quotient = 0;

    for (i = 15;
 i >= 0;
 i = i - 1) begin

        remainder = remainder << 1;
        quotient = quotient << 1;


        remainder[0] = dividend[i];
        quotient[0] = (remainder >= divisor) ? 1 : 0;

        if (remainder >= divisor) begin
            remainder = remainder - divisor;
        end
    end

    result = quotient;
    odd = remainder;
end

endmodule

