module comparator_4bit (
    input [3:0] A,
    input [3:0] B,
    output A_greater,
    output A_equal,
    output A_less
);


    wire [3:0] eq, gt, lt;

    assign eq[3] = (A[3] == B[3]);
    assign eq[2] = (A[2] == B[2]);
    assign eq[1] = (A[1] == B[1]);
    assign eq[0] = (A[0] == B[0]);

