    assign gt[2] = (A[2] > B[2]);
    assign gt[1] = (A[1] > B[1]);
    assign gt[0] = (A[0] > B[0]);

    assign lt[3] = (A[3] < B[3]);
    assign lt[2] = (A[2] < B[2]);
    assign lt[1] = (A[1] < B[1]);
    assign lt[0] = (A[0] < B[0]);


    wire term_gt3 = gt[3];
    wire term_gt2 = eq[3] & gt[2];
    wire term_gt1 = eq[3] & eq[2] & gt[1];
    wire term_gt0 = eq[3] & eq[2] & eq[1] & gt[0];

    wire term_lt3 = lt[3];
    wire term_lt2 = eq[3] & lt[2];
    wire term_lt1 = eq[3] & eq[2] & lt[1];
    wire term_lt0 = eq[3] & eq[2] & eq[1] & lt[0];


    assign A_greater = term_gt3 | term_gt2 | term_gt1 | term_gt0;
    assign A_less = term_lt3 | term_lt2 | term_lt1 | term_lt0;


