module fixed_point_adder #(parameter Q = 4, parameter N = 8) (
    input [N-1:0] a,
    input [N-1:0] b,
    output [N-1:0] c
);

    reg [N-1:0] res;

    always @* begin
        reg sign_a, sign_b;
        reg [N-2:0] mag_a, mag_b;
        reg [N-1:0] sum_mag;
        reg [N-2:0] diff_mag;
        reg res_sign;

        sign_a = a[N-1];
        sign_b = b[N-1];
        mag_a = a[N-2:0];
        mag_b = b[N-2:0];

        if (sign_a == sign_b) begin

            sum_mag = {1'b0, mag_a} + {1'b0, mag_b};
            res_sign = sign_a;

            if (sum_mag[N-1:0] >= (1 << (N-1))) begin
                sum_mag = sum_mag - (1 << (N));
                res_sign = ~res_sign;
            end
            res = {res_sign, sum_mag[N-2:0]};
        end else begin

            if (mag_a > mag_b) begin
                diff_mag = mag_a - mag_b;
                res_sign = sign_a;
            end else if (mag_b > mag_a) begin
                diff_mag = mag_b - mag_a;
                res_sign = sign_b;
            end else begin
                diff_mag = 0;
                res_sign = 0;
            end
            res = {res_sign, diff_mag};
        end
    end

    assign c = res;

endmodule

