module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z = 0
);

    reg [2:0] counter;
    reg a_sign, b_sign, z_sign;
    reg [7:0] a_exponent, b_exponent, z_exponent;
    reg [23:0] a_mantissa, b_mantissa;
    reg [47:0] product;
    reg guard_bit, round_bit, sticky;

    reg a_is_nan, b_is_nan, a_is_inf, b_is_inf;
    reg a_is_zero, b_is_zero;

    function integer find_leading_one;
        input [47:0] data;
        integer i;
        begin
            find_leading_one = 0;
            for (i = 47;
 i >= 0;
 i = i - 1) begin
                if (data[i]) begin
                    find_leading_one = i;
                    disable find_leading_one;
                end
            end
        end
    endfunction

    always @(posedge clk) begin
        if (rst) begin
            counter <= 0;
            z <= 0;
            a_sign <= 0;
            b_sign <= 0;
            z_sign <= 0;
            a_exponent <= 0;
            b_exponent <= 0;
            z_exponent <= 0;
            a_mantissa <= 0;
            b_mantissa <= 0;
            product <= 0;
            guard_bit <= 0;
            round_bit <= 0;
            sticky <= 0;
            a_is_nan <= 0;
            b_is_nan <= 0;
            a_is_inf <= 0;
            b_is_inf <= 0;
            a_is_zero <= 0;
            b_is_zero <= 0;
        end else begin
            case (counter)
                0: begin
                    a_sign <= a[31];
                    b_sign <= b[31];
                    z_sign <= a[31] ^ b[31];

                    a_is_zero <= (a[30:23] == 0) && (a[22:0] == 0);
                    b_is_zero <= (b[30:23] == 0) && (b[22:0] == 0);

                    a_is_inf <= (a[30:23] == 8'hff) && (a[22:0] == 0);
                    b_is_inf <= (b[30:23] == 8'hff) && (b[22:0] == 0);

                    a_is_nan <= (a[30:23] == 8'hff) && (a[22:0] != 0);
                    b_is_nan <= (b[30:23] == 8'hff) && (b[22:0] != 0);

                    if (a_is_nan || b_is_nan) begin
                        z <= {z_sign, 8'hff, 1'b1, 22'h0};
                    end else if (a_is_zero) begin
                        if (b_is_inf) z <= {z_sign, 8'hff, 1'b1, 22'h0};
                        else z <= 0;
                    end else if (b_is_zero) begin
                        if (a_is_inf) z <= {z_sign, 8'hff, 1'b1, 22'h0};
                        else z <= 0;
                    end else if (a_is_inf) begin
                        z <= {z_sign, 8'hff, 23'h0};
                    end else if (b_is_inf) begin
                        z <= {z_sign, 8'hff, 23'h0};
                    end else begin
                        counter <= 1;
                    end
                end
                1: begin
                    a_exponent <= a[30:23];
                    b_exponent <= b[30:23];
                    a_mantissa <= (a[30:23] != 0) ? {1'b1, a[22:0]} : {1'b0, a[22:0]};
                    b_mantissa <= (b[30:23] != 0) ? {1'b1, b[22:0]} : {1'b0, b[22:0]};
                    z_exponent <= a_exponent + b_exponent - 127;
                    counter <= 2;
                end
                2: begin
                    product <= a_mantissa * b_mantissa;
                    counter <= 3;
                end
                3: begin
                    integer leading_one = find_leading_one(product);
                    integer shift = leading_one - 46;
                    if (shift > 0) begin
                        product <= product << shift;
                        z_exponent <= z_exponent + shift;
                    end else if (shift < 0) begin
                        product <= product >> (-shift);
                        z_exponent <= z_exponent - (-shift);
                    end
                    {guard_bit, round_bit, sticky} = {product[22], product[21], |product[20:0]};
                    a_mantissa <= product[46:23];
                    counter <= 4;
                end
                4: begin
                    if (guard_bit) begin
                        if (round_bit || sticky) a_mantissa <= a_mantissa + 1;
                        else if (a_mantissa[0]) a_mantissa <= a_mantissa + 1;
                    end
                    if (a_mantissa == 24'h1000000) begin
                        a_mantissa <= 24'h800000;
                        z_exponent <= z_exponent + 1;
                    end
                    counter <= 5;
                end
                5: begin
                    if (z_exponent > 254) begin
                        z <= {z_sign, 8'hff, 23'h0};
                    end else if (z_exponent < 1) begin
                        z <= {z_sign, 8'h0, 23'h0};
                    end else begin
                        z <= {z_sign, z_exponent[7:0], a_mantissa[22:0]};
                    end
                    counter <= 0;
                end
                default: counter <= 0;
            endcase
        end
    end

endmodule

